    /// Issue 483 unit 2: `refold-buyer-roles` enqueues dry unless asked, runs through
    /// `run_spec`'s dispatch, stores its `buyer-role-refold` report dry and wet, and a
    /// cancelled run stores none. (The cohort itself is pinned in
    /// `tests/project_incremental.rs`, `a_review_body_or_platform_in_the_buyer_slot_is_demoted_on_full_and_daily_folds`.)
    #[tokio::test]
    async fn refold_buyer_roles_enqueues_dry_stores_its_report_and_a_stop_stores_none() {
        let db = scratch().await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        sup.enqueue_request(&JobRequest { kind: "refold-buyer-roles".into(), ..Default::default() }).await.unwrap();
        {
            let queue = sup.queue.lock().expect("queue lock");
            assert!(matches!(queue[0].spec, Spec::RefoldBuyerRoles { dry_run: true }), "dry unless asked");
            assert_eq!(queue[0].params, "refold-buyer-roles dry-run");
        }
        let job = |id: u64, dry_run: bool| Job {
            id,
            kind: "refold-buyer-roles".into(),
            params: String::new(),
            spec: Spec::RefoldBuyerRoles { dry_run },
            resume_after: None,
        };
        let msg = sup.run_spec(&job(1, true)).await.expect("dry");
        assert!(msg.contains("DRY RUN") && msg.contains("0 whose buyer role") && msg.contains("would re-queue 0"), "{msg}");
        let (body, _) = db.latest_report(BUYER_ROLE_REFOLD_REPORT).await.unwrap().expect("report");
        assert!(body.contains("\"dry_run\":true") && body.contains("\"fixed\":[]"), "{body}");
        let msg = sup.run_spec(&job(2, false)).await.expect("wet");
        assert!(!msg.contains("DRY RUN") && msg.contains("re-queued 0"), "{msg}");

        // Seeded (issue 483 unit 2 review): one projected notice served the Vergabekammer as
        // its buyer before its parse gained the Bauamt's tender-receipt role (a layer
        // projected before the demote), so the stride path runs and the wet run writes.
        let fetch_id = seed_fetch(&db).await;
        let text = |section: &str, field: &str, value: &str| store::ValueRow {
            section_id: section.into(),
            field_id: field.into(),
            ordinal: 0,
            value: store::NoticeValue::Text { value: value.into(), lang: None },
        };
        let parsed = store::Parsed {
            sections: vec![
                store::Section { id: "PROCEDURE".into(), kind: "Notice".into(), parent: None },
                store::Section { id: "ORG-1".into(), kind: "Organization".into(), parent: None },
                store::Section { id: "ORG-9".into(), kind: "Organization".into(), parent: None },
            ],
            values: vec![
                text("ORG-1", "BT-500-Organization-Company", "Vergabekammer Nordbayern"),
                text("ORG-9", "BT-500-Organization-Company", "Staatliches Bauamt Passau"),
                store::ValueRow {
                    section_id: "PROCEDURE".into(),
                    field_id: "OPT-300-Procedure-Buyer".into(),
                    ordinal: 0,
                    value: store::NoticeValue::Id { scheme: None, value: "ORG-1".into(), is_ref: true },
                },
            ],
        };
        db.record_notice(
            &store::Notice {
                source: "ted".into(),
                publication_id: "00483002-2024".into(),
                content_hash: "h483".into(),
                profile: "eforms:eforms-sdk-1.13".into(),
                declared_version: None,
                fetch_id,
                member_path: "m483".into(),
                ingested_at: 0,
                published_at: Some(store::Stamp::utc(0)),
                dispatched_at: None,
            },
            &store::Parse::Parsed(parsed),
        )
        .await
        .unwrap();
        ingest::project::project(&db, false).await.expect("the fold before the demote applies");
        assert!(db.unprojected_parsed_notice_ids().await.unwrap().is_empty());
        db.execute_for_test(
            "INSERT INTO notice_ids(notice_id, section_id, field_id, ordinal, scheme, value, is_ref) \
             SELECT id, 'PROCEDURE', 'OPT-301-Lot-TenderReceipt', 0, NULL, 'ORG-9', 1 FROM notices \
              WHERE publication_id = '00483002-2024'",
        )
        .await
        .unwrap();
        // Issue 467's poll budget on the stride path (the tripwire's own poll has an empty
        // DB, so it never enters a stride). The whole chain into store and turso, as for
        // the census's seeded poll: measured 2026-10-04 in the gate's profile between 360
        // and 390 KiB (overflows at 360, passes at 390), plus ~24 KiB. Re-measure on a
        // turso upgrade; don't just raise it.
        let seeded = job(4, true);
        poll_once_within("run_refold_buyer_roles over a seeded stride", 416 * 1024, || {
            sup.run_refold_buyer_roles(&seeded, true)
        });
        let msg = sup.run_spec(&job(5, true)).await.expect("seeded dry");
        assert!(msg.contains("1 whose buyer role") && msg.contains("1 with a promoted buyer"), "{msg}");
        assert!(msg.contains("would re-queue 1") && msg.contains("stamped 0"), "dry writes nothing: {msg}");
        assert!(db.unprojected_parsed_notice_ids().await.unwrap().is_empty(), "dry re-queued nothing");
        let (body, _) = db.latest_report(BUYER_ROLE_REFOLD_REPORT).await.unwrap().expect("report");
        assert!(body.contains("ted:00483002-2024") && body.contains("Staatliches Bauamt Passau"), "{body}");
        let msg = sup.run_spec(&job(6, false)).await.expect("seeded wet");
        assert!(msg.contains("re-queued 1") && !msg.contains("stamped 0"), "{msg}");
        assert_eq!(db.unprojected_parsed_notice_ids().await.unwrap().len(), 1, "the notice re-queued");
        db.put_report(BUYER_ROLE_REFOLD_REPORT, "{\"marker\":1}", store::now_unix()).await.unwrap();
        sup.cancel_running.store(3, Ordering::Relaxed);
        let msg = sup.run_spec(&job(3, true)).await.expect("stopped");
        assert!(msg.contains("STOPPED by cancel") && msg.contains("no report stored"), "{msg}");
        let (body, _) = db.latest_report(BUYER_ROLE_REFOLD_REPORT).await.unwrap().expect("report");
        assert_eq!(body, "{\"marker\":1}", "a stopped run stores nothing");
    }

    /// Issue 482: the job wiring around `ingest::project::key_census`. It enqueues with
    /// no flag (read-only), runs through `run_spec`'s dispatch, stores its report with
    /// every bucket, and a cancelled run stores none.
    #[tokio::test]
    async fn the_procedure_key_census_job_stores_its_report_and_a_stop_stores_none() {
        let db = scratch().await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        sup.enqueue_request(&JobRequest { kind: "procedure-key-census".into(), ..Default::default() }).await.unwrap();
        {
            let queue = sup.queue.lock().expect("queue lock");
            assert!(matches!(queue[0].spec, Spec::ProcedureKeyCensus));
            assert_eq!(queue[0].params, "procedure-key-census");
        }
        let job = |id: u64| Job {
            id,
            kind: "procedure-key-census".into(),
            params: String::new(),
            spec: Spec::ProcedureKeyCensus,
            resume_after: None,
        };
        let msg = sup.run_spec(&job(1)).await.expect("census");
        assert!(msg.starts_with("procedure-key-census (issue 482): 0 UUID-keyed Tenders"), "{msg}");
        let (body, _) = db.latest_report(PROCEDURE_KEY_CENSUS_REPORT).await.unwrap().expect("report");
        for bucket in ingest::project::key_census::KEY_CENSUS_BUCKETS {
            assert!(body.contains(&format!("\"{bucket}\"")), "{bucket}: {body}");
        }
        // A cancelled run: a Tender exists, so the walk has a window to refuse.
        let fetch_id = seed_fetch(&db).await;
        db.record_notice(
            &store::Notice {
                source: "ted".into(),
                publication_id: "00000001-2024".into(),
                content_hash: "h".into(),
                profile: "eforms:eforms-sdk-1.13".into(),
                declared_version: None,
                fetch_id,
                member_path: "m".into(),
                ingested_at: 0,
                published_at: Some(store::Stamp::utc(0)),
                dispatched_at: None,
            },
            &store::Parse::Parsed(store::Parsed::default()),
        )
        .await
        .unwrap();
        ingest::project::project(&db, false).await.unwrap();
        db.put_report(PROCEDURE_KEY_CENSUS_REPORT, "{\"marker\":1}", store::now_unix()).await.unwrap();
        sup.cancel_running.store(2, Ordering::Relaxed);
        let msg = sup.run_spec(&job(2)).await.expect("stopped census");
        assert!(msg.contains("STOPPED by cancel") && msg.contains("no report stored"), "{msg}");
        let (body, _) = db.latest_report(PROCEDURE_KEY_CENSUS_REPORT).await.unwrap().expect("report");
        assert_eq!(body, "{\"marker\":1}", "a stopped census stores nothing");
    }

    /// Issue 542: `backfill-org-name-variants` reads the stop flag before every notice window,
    /// so a cancel ends it there instead of answering 409 for a 3.3 h walk (job 2491).
    #[tokio::test]
    async fn the_org_name_variant_backfill_stops_before_its_next_window() {
        let db = scratch().await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        sup.enqueue_request(&JobRequest { kind: "backfill-org-name-variants".into(), ..Default::default() })
            .await
            .unwrap();
        assert!(matches!(sup.queue.lock().expect("queue lock")[0].spec, Spec::BackfillOrgNameVariants));
        assert!(stoppable("backfill-org-name-variants", "backfill-org-name-variants"));
        let job = |id: u64| Job {
            id,
            kind: "backfill-org-name-variants".into(),
            params: String::new(),
            spec: Spec::BackfillOrgNameVariants,
            resume_after: None,
        };
        // A notice to walk, so the stopped run below has a window it refuses.
        let fetch_id = seed_fetch(&db).await;
        db.record_notice(
            &store::Notice {
                source: "ted".into(),
                publication_id: "00000001-2024".into(),
                content_hash: "h".into(),
                profile: "eforms:eforms-sdk-1.13".into(),
                declared_version: None,
                fetch_id,
                member_path: "m".into(),
                ingested_at: 0,
                published_at: Some(store::Stamp::utc(0)),
                dispatched_at: None,
            },
            &store::Parse::Parsed(store::Parsed::default()),
        )
        .await
        .unwrap();
        sup.cancel_running.store(2, Ordering::Relaxed);
        let msg = sup.run_spec(&job(2)).await.expect("stopped backfill");
        assert!(msg.starts_with("backfill-org-name-variants STOPPED by cancel after notice id 0: 0 notices"), "{msg}");
        // Another job's flag does not stop it: the walk finishes over the one notice.
        let msg = sup.run_spec(&job(3)).await.expect("backfill");
        assert!(msg.starts_with("organization_names backfilled over 1 notices:"), "{msg}");
        // A recovered job resumes after its durable cursor, so nothing past it is re-walked.
        let resumed = Job { resume_after: Some("999999".into()), ..job(4) };
        let msg = sup.run_spec(&resumed).await.expect("resumed backfill");
        assert!(
            msg.starts_with("organization_names backfilled over 0 notices (resumed after notice id 999999):"),
            "{msg}"
        );
    }

    /// Issue 542: the dissolve job threads ingest's name fields and normaliser into the
    /// store and names the re-derived variants in its summary, dry and wet. One real
    /// dissolve: the withheld-supplier PPON (issue 522) is condemned by the live v2 gate,
    /// and its `Individual` mention's labelled BT-500 text (`EN`) reaches the fresh org
    /// as `ENG` only if ingest's field list and normaliser both arrived. (The
    /// re-derivation rules themselves are pinned in `store/tests/placeholder_dissolve.rs`.)
    #[tokio::test]
    async fn the_placeholder_dissolve_names_its_rederived_name_variants() {
        let path = format!("/tmp/tender-db-sup-dissolve-variants-{}-{}.db", std::process::id(), store::now_unix());
        for s in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{path}{s}"));
        }
        let db = Arc::new(store::Db::open(&path).await.unwrap());
        let raw = store::turso::Builder::new_local(&path).build().await.unwrap();
        let conn = raw.connect().unwrap();
        conn.execute("PRAGMA foreign_keys = OFF", ()).await.unwrap();
        for sql in [
            "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
             VALUES (1, 'GB', 'national', 'GBPPONPBXY3232WNHZ', 'Withheld Section94 Supplier',
                     'withheld section94 supplier', 0, 0)",
            "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country)
             VALUES (100, 'ORG-0001', 1, 'Individual', 'GB')",
            "INSERT INTO notice_texts (notice_id, section_id, field_id, ordinal, lang, value)
             VALUES (100, 'ORG-0001', 'BT-500-Organization-Company', 0, 'EN', 'Individual')",
        ] {
            conn.execute(sql, ()).await.unwrap();
        }
        let sup = Supervisor::new(db, "archive".into(), reqwest::Client::new());
        let job = |id: u64, dry_run: bool| Job {
            id,
            kind: "repair-placeholder-orgs".into(),
            params: String::new(),
            spec: Spec::RepairPlaceholderOrgs { dry_run },
            resume_after: None,
        };
        let dry = sup.run_spec(&job(1, true)).await.expect("dry dissolve");
        assert!(dry.contains("1 condemned by the v2 gate"), "{dry}");
        assert!(dry.ends_with("; name variants would be re-derived for up to 1 re-bound orgs (per window)"), "{dry}");
        let wet = sup.run_spec(&job(2, false)).await.expect("wet dissolve");
        assert!(wet.ends_with("; 1 name variants re-derived over 1 re-bound org passes (issue 542)"), "{wet}");
        let mut rows = conn
            .query(
                "SELECT n.lang, n.name FROM organization_names n
                   JOIN organization_mentions m ON m.organization_id = n.org_id
                  WHERE m.notice_id = 100 AND m.section_id = 'ORG-0001'",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("the re-bound org has its variant");
        let text = |i: usize| match row.get_value(i).unwrap() {
            store::turso::Value::Text(t) => t,
            other => panic!("unexpected {other:?}"),
        };
        assert_eq!((text(0), text(1)), ("ENG".to_owned(), "Individual".to_owned()));
        drop(rows);
        // A second wet run finds nothing condemned and re-derives nothing.
        let again = sup.run_spec(&job(3, false)).await.expect("rerun");
        assert!(again.ends_with("; 0 name variants re-derived over 0 re-bound org passes (issue 542)"), "{again}");
        drop(conn);
        for s in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{path}{s}"));
        }
    }

    /// Issue 477 unit 3: the job wiring around `fetch::audit_fts_ids`. It enqueues wet by
    /// default with its options in the params, is stoppable, a dry run asks nothing and
    /// stores nothing, and a wet run stores the report from the ledger. (The by-id
    /// requests themselves are tested against a mock in `ingest/tests/fetch.rs`; here
    /// the production 12 s pace would make every request a 12 s wait.)
    #[tokio::test]
    async fn the_fts_id_audit_job_enqueues_wet_by_default_and_a_dry_run_asks_nothing() {
        let db = scratch().await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        sup.enqueue_request(&JobRequest { kind: "audit-fts-ids".into(), ..Default::default() }).await.unwrap();
        sup.enqueue_request(&JobRequest {
            kind: "audit-fts-ids".into(),
            dry_run: Some(true),
            max_ids: Some(50),
            recheck_absent_days: Some(30),
            ..Default::default()
        })
        .await
        .unwrap();
        {
            let queue = sup.queue.lock().expect("queue lock");
            assert!(matches!(
                queue[0].spec,
                Spec::AuditFtsIds { dry_run: false, max_ids: None, recheck_absent_days: None }
            ));
            assert_eq!(queue[0].params, "audit-fts-ids");
            assert!(matches!(
                queue[1].spec,
                Spec::AuditFtsIds { dry_run: true, max_ids: Some(50), recheck_absent_days: Some(30) }
            ));
            assert_eq!(queue[1].params, "audit-fts-ids dry-run max 50 recheck-absent 30d");
        }
        assert!(stoppable("audit-fts-ids", "audit-fts-ids"));

        // 2021: ids 1 and 3 held, so 000002-2021 is missing.
        db.record_fetch(&store::Fetch {
            source: "fts".into(),
            kind: "monthly".into(),
            period: "2021-01".into(),
            url: "u".into(),
            sha256: "f".into(),
            bytes: 1,
            fetched_at: 0,
            path: "p".into(),
        })
        .await
        .unwrap();
        let fetch_id = db.current_packages("fts", "monthly", None).await.unwrap()[0].fetch_id;
        for id in ["000001-2021", "000003-2021"] {
            db.record_notice(
                &store::Notice {
                    source: "fts".into(),
                    publication_id: id.into(),
                    content_hash: id.into(),
                    profile: "fts:ocds-1.1".into(),
                    declared_version: None,
                    fetch_id,
                    member_path: format!("{id}.json"),
                    ingested_at: 0,
                    published_at: None,
                    dispatched_at: None,
                },
                &store::Parse::Pending,
            )
            .await
            .unwrap();
        }
        let job = |id: u64, dry_run: bool, max_ids: Option<u64>| Job {
            id,
            kind: "audit-fts-ids".into(),
            params: String::new(),
            spec: Spec::AuditFtsIds { dry_run, max_ids, recheck_absent_days: None },
            resume_after: None,
        };
        let msg = sup.run_spec(&job(1, true, None)).await.expect("dry run");
        assert!(msg.starts_with("audit-fts-ids DRY RUN (issue 477): 1 missing id(s), 1 due, 0 probed"), "{msg}");
        assert!(db.latest_report(fts::audit::REPORT_KIND).await.unwrap().is_none(), "a dry run stores nothing");

        // A wet run capped at zero asks nothing and stores the ledger's report.
        let msg = sup.run_spec(&job(2, false, Some(0))).await.expect("wet run");
        assert!(msg.starts_with("audit-fts-ids (issue 477): 1 missing id(s), 1 due, 0 probed"), "{msg}");
        assert!(msg.contains("2021 2/3 held, 0 absent, 0 present, 1 unaccounted"), "{msg}");
        let (body, _) = db.latest_report(fts::audit::REPORT_KIND).await.unwrap().expect("report");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["unaccounted"], 1);
        assert_eq!(report["years"][0]["highest"], 3);
        assert_eq!(report["complete"], false);
    }

    /// Issue 477 review: a halted audit stores its report and FAILS the job, so the
