    /// Issue 469 U4, end to end through the PRODUCTION rules (the real
    /// `registry_pair_key`, `registry_mention_key` and normaliser): beside the
    /// company-number pair, a college split across its UKPRN org and its PPON org. The
    /// dry run plans it in the register family and lists it in the verdict shape; the
    /// wet run merges the company-number pair and — since U5 (D1) — HOLDS the register
    /// pair, which no HIGH verdict admitted, re-recording it in the residual; and a
    /// `keep` built from the residual listing's own `country` / `scheme` / `key` /
    /// `members`, recorded as a merge verdict, denies the pair on the next dry run.
    #[tokio::test]
    async fn an_altid_dry_run_lists_a_register_pair_that_round_trips_into_a_verdict() {
        let (db, conn, path) = altid_fixture("registry").await;
        altid_satellite(&conn).await;
        altid_registry_rows(&conn).await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let key = "GB-UKPRN:GBUKPRN10007798~PBZB4962TVLR";
        let plan = || {
            let sup = &sup;
            async move {
                let (body, _) = sup.db().latest_report("altid-merge-plan").await.unwrap().expect("recorded");
                (serde_json::from_str::<serde_json::Value>(&body).unwrap(), body)
            }
        };

        // 1. The dry run plans it beside the company-number pair, which it leaves alone.
        let msg = sup.run_spec(&altid_job(3, true)).await.expect("dry plans");
        assert!(msg.contains("GB-UKPRN 1 of 1 two orgs (plan 1)"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["pairs"], serde_json::json!(["03914810~PHDQ2359NZMP"]), "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([key]), "{body}");
        assert_eq!(v["registry_gates"]["GB-UKPRN"]["planned"], 1, "{body}");
        let l = &v["registry_plan"][0];
        assert_eq!(
            (l["country"].clone(), l["scheme"].clone(), l["key"].clone(), l["registry_scheme"].clone()),
            ("GB".into(), "GB:altid".into(), key.into(), "GB-UKPRN".into()),
            "{body}"
        );
        assert_eq!((l["keep"].clone(), l["loser"].clone()), (3.into(), 4.into()), "{body}");
        let members: Vec<(i64, &str)> = l["members"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| (m["org_id"].as_i64().unwrap(), m["side"].as_str().unwrap()))
            .collect();
        assert_eq!(members, vec![(3, "registry"), (4, "ppon")], "ascending, verdict-ready: {body}");
        assert_eq!((l["self"].clone(), l["coherent"].clone()), (0.into(), true.into()), "{body}");
        assert_eq!(l["witness_publications"], serde_json::json!(["ocds-c"]), "{body}");
        assert_eq!(l["verdict_cohort"], serde_json::Value::Null, "planned on corroboration alone: {body}");

        // 2. The wet run merges the company-number pair; the register pair carries no
        // admitting verdict, so it is held and re-recorded (U5's D1).
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let msg = sup.run_spec(&altid_job(4, false)).await.expect("wet merges");
        assert!(msg.contains("WET: merged 1 of 1 reviewed live pairs"), "{msg}");
        assert!(
            msg.contains("register (issue 469 U5): merged 0 of 1 reviewed live pairs (1 awaiting a HIGH verdict"),
            "{msg}"
        );
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (3, 4)").await, 2);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_log").await, 1);
        let (v, body) = plan().await;
        assert_eq!(v["residual_of_wet_run"], true, "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([key]), "the held pair, re-recorded: {body}");
        assert_eq!((v["registry_unconfirmed"].as_u64(), v["registry_merged_this_run"].as_u64()), (Some(1), Some(0)), "{body}");

        // 3. A reviewer's `keep`, built from the residual listing as an operator would
        // POST it, denies the pair on the next dry run.
        let l = &v["registry_plan"][0];
        let verdict = store::MergeVerdict {
            country: l["country"].as_str().unwrap().to_owned(),
            scheme: l["scheme"].as_str().unwrap().to_owned(),
            key: l["key"].as_str().unwrap().to_owned(),
            members: l["members"].as_array().unwrap().iter().map(|m| m["org_id"].as_i64().unwrap()).collect(),
            action: "keep".into(),
            rationale: "fixture".into(),
            confidence: "high".into(),
            reviewed_holders: None,
        };
        db.record_merge_verdicts("469-u4-test", &[verdict], store::now_unix()).await.unwrap();
        let msg = sup.run_spec(&altid_job(5, true)).await.expect("dry re-plans");
        assert!(msg.contains("GB-UKPRN 1 of 1 two orgs (denied 1 verdict-keep)"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["registry_denied"][0]["gate"], "verdict-keep", "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([]), "{body}");
        remove_db(&path);
    }

    /// Issue 469 U5, end to end through the PRODUCTION rules: U6's runbook in small. The
    /// dry run plans the college's register pair; a register-confirmed HIGH merge verdict
    /// built from its listing (cohort under `altid-registry-confirmed-`) admits it on the
    /// next dry run; the wet run merges BOTH families in one job — the PPON org folds into
    /// the UKPRN org — writes the register ledger row the alias replays, and records what it
    /// wrote in the residual (S4's read). The next dry run reads the pair `already_one`.
    #[tokio::test]
    async fn an_altid_wet_run_merges_a_confirmed_register_pair_and_the_next_dry_reads_it_already_one() {
        let (db, conn, path) = altid_fixture("registry-wet").await;
        altid_satellite(&conn).await;
        altid_registry_rows(&conn).await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let plan = || {
            let sup = &sup;
            async move {
                let (body, _) = sup.db().latest_report("altid-merge-plan").await.unwrap().expect("recorded");
                (serde_json::from_str::<serde_json::Value>(&body).unwrap(), body)
            }
        };
        // 1. Dry; 2. the confirmed verdict, built from the listing as U6's tooling posts it.
        sup.run_spec(&altid_job(3, true)).await.expect("dry plans");
        let (v, _) = plan().await;
        let l = &v["registry_plan"][0];
        let verdict = store::MergeVerdict {
            country: l["country"].as_str().unwrap().to_owned(),
            scheme: l["scheme"].as_str().unwrap().to_owned(),
            key: l["key"].as_str().unwrap().to_owned(),
            members: l["members"].as_array().unwrap().iter().map(|m| m["org_id"].as_i64().unwrap()).collect(),
            action: "merge".into(),
            rationale: "UKRLP: UKPRN 10007798 is Leeds City College".into(),
            confidence: "high".into(),
            reviewed_holders: None,
        };
        let cohort = format!("{}2026-10-12", store::ALTID_REGISTRY_CONFIRMED_COHORT_PREFIX);
        db.record_merge_verdicts(&cohort, &[verdict], store::now_unix()).await.unwrap();
        // 3. Dry again: admitted, and the listing names the cohort.
        let msg = sup.run_spec(&altid_job(4, true)).await.expect("dry re-plans");
        assert!(msg.contains("GB-UKPRN 1 of 1 two orgs (plan 1; 1 verdict-admitted)"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["registry_gates"]["GB-UKPRN"]["admitted_verdict"], 1, "{body}");
        assert_eq!(v["registry_plan"][0]["verdict_cohort"], serde_json::json!(cohort), "{body}");

        // 4. Wet: both families in one job.
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let msg = sup.run_spec(&altid_job(5, false)).await.expect("wet merges");
        assert!(msg.contains("WET: merged 1 of 1 reviewed live pairs"), "{msg}");
        assert!(msg.contains("register (issue 469 U5): merged 1 of 1 reviewed live pairs (0 awaiting"), "{msg}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations WHERE id = 4").await, 0);
        assert_eq!(
            altid_count(&conn, "SELECT organization_id FROM organization_mentions WHERE notice_id = 13").await,
            3,
            "the PPON-first mention moved to the UKPRN org"
        );
        assert_eq!(
            altid_count(
                &conn,
                "SELECT COUNT(*) FROM org_merge_log WHERE rule = 'e2-altid' AND keep = 3 AND loser = 4 AND job_id = 5 \
                   AND json_extract(evidence, '$.coh') IS NULL \
                   AND json_extract(evidence, '$.registry_scheme') = 'GB-UKPRN' \
                   AND json_extract(evidence, '$.registry_kind') = 'national' \
                   AND json_extract(evidence, '$.registry') = 'GBUKPRN10007798' \
                   AND json_extract(evidence, '$.registry_literal') = 'GB-UKPRN-10007798' \
                   AND json_extract(evidence, '$.ppon') = 'PBZB4962TVLR' \
                   AND json_extract(evidence, '$.keep_id') = 'GBUKPRN10007798' \
                   AND json_extract(evidence, '$.loser_id') = 'GBPPONPBZB4962TVLR' \
                   AND json_extract(evidence, '$.confirmed') = 'register' \
                   AND json_extract(evidence, '$.verdict') = 'admitted' \
                   AND json_extract(evidence, '$.witnesses') = 1 \
                   AND json_extract(evidence, '$.publishers') = 0 \
                   AND json_extract(evidence, '$.witness_notices[0]') = 12"
            )
            .await,
            1
        );
        let (v, body) = plan().await;
        assert_eq!(v["residual_of_wet_run"], true, "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([]), "nothing reviewed is left: {body}");
        assert_eq!(v["registry_merged_this_run"], 1, "{body}");
        assert_eq!(v["registry_merged"][0]["evidence"]["confirmed"], "register", "{body}");
        assert_eq!(v["registry_merged"][0]["verdict_cohort"], serde_json::json!(cohort), "{body}");

        // The next dry plan reads the pair one org.
        let msg = sup.run_spec(&altid_job(6, true)).await.expect("re-dry");
        assert!(msg.contains("GB-UKPRN 0 of 1 two orgs"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["registry_pairs"]["GB-UKPRN"]["already_one"], 1, "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([]), "{body}");
        assert_eq!(v["registry_regrown"], serde_json::json!([]), "{body}");
        remove_db(&path);
    }

    /// Issue 513 unit 1, through the PRODUCTION normaliser: beside the fixture's
    /// company-number pair, two NHS trusts each split across a register org and a PPON
    /// org. `GB-NHS-RR8` mints `GBNHSRR8`; `GB-NHS-R0B` mints nothing — its one digit is a
    /// zero, and the normaliser's all-zero filler rule refuses it, so its party bound a
    /// provisional org by name (469 U2's open question). The dry run stores both pairs in
    /// `registry_nhs_listing` with their identity, class and holders; the wet run's
    /// residual leaves the listing out.
    #[tokio::test]
    async fn an_altid_dry_run_stores_every_nhs_pair_and_a_wet_run_does_not() {
        let (db, conn, path) = altid_fixture("registry-nhs").await;
        altid_satellite(&conn).await;
        let org = "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at) VALUES";
        let notice = "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at) VALUES";
        let id = "INSERT INTO notice_ids (notice_id, section_id, field_id, ordinal, scheme, value, is_ref) VALUES";
        let mention = "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier, scheme) VALUES";
        let stsft = "South Tyneside and Sunderland NHS Foundation Trust";
        let leeds = "Leeds Teaching Hospitals NHS Trust";
        for sql in [
            format!("{org} (5, 'GB', NULL, NULL, '{stsft}', 'x', 1, 0)"),
            format!("{org} (6, 'GB', 'national', 'GBPPONPYDR3797LZLJ', '{stsft}', 'x', 0, 0)"),
            format!("{org} (7, 'GB', 'national', 'GBNHSRR8', '{leeds}', 'x', 0, 0)"),
            format!("{org} (8, 'GB', 'national', 'GBPPONPDTR3338MNPG', '{leeds}', 'x', 0, 0)"),
            format!("{notice} (14, 'fts', 'ocds-e', 'h', 'fts:ocds-1.1', 1, 'e', 0)"),
            format!("{notice} (15, 'fts', 'ocds-f', 'h', 'fts:ocds-1.1', 1, 'f', 0)"),
            format!("{notice} (16, 'fts', 'ocds-g', 'h', 'fts:ocds-1.1', 1, 'g', 0)"),
            format!("{notice} (17, 'fts', 'ocds-h', 'h', 'fts:ocds-1.1', 1, 'h', 0)"),
            format!("{id} (14, 'ORG-E', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-R0B', 0)"),
            format!("{id} (14, 'ORG-E', 'BT-501-Organization-Company', 1, 'GB-PPON', 'GB-PPON-PYDR-3797-LZLJ', 0)"),
            format!("{id} (15, 'ORG-F', 'BT-501-Organization-Company', 0, 'GB-PPON', 'GB-PPON-PYDR-3797-LZLJ', 0)"),
            format!("{id} (16, 'ORG-G', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-RR8', 0)"),
            format!("{id} (16, 'ORG-G', 'BT-501-Organization-Company', 1, 'GB-PPON', 'GB-PPON-PDTR-3338-MNPG', 0)"),
            format!("{id} (17, 'ORG-H', 'BT-501-Organization-Company', 0, 'GB-PPON', 'GB-PPON-PDTR-3338-MNPG', 0)"),
            format!("{mention} (14, 'ORG-E', 5, '{stsft}', 'GB', 'GB-NHS-R0B', 'GB-NHS')"),
            format!("{mention} (15, 'ORG-F', 6, '{stsft}', 'GB', 'GB-PPON-PYDR-3797-LZLJ', 'GB-PPON')"),
            format!("{mention} (16, 'ORG-G', 7, '{leeds}', 'GB', 'GB-NHS-RR8', 'GB-NHS')"),
            format!("{mention} (17, 'ORG-H', 8, '{leeds}', 'GB', 'GB-PPON-PDTR-3338-MNPG', 'GB-PPON')"),
        ] {
            conn.execute(sql.as_str(), ()).await.unwrap();
        }
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let plan = || {
            let sup = &sup;
            async move {
                let (body, _) = sup.db().latest_report("altid-merge-plan").await.unwrap().expect("recorded");
                (serde_json::from_str::<serde_json::Value>(&body).unwrap(), body)
            }
        };

        let msg = sup.run_spec(&altid_job(3, true)).await.expect("dry plans");
        assert!(msg.contains("GB-NHS 2 of 2 two orgs (denied 2 registry-shape)"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["registry_pairs"]["GB-NHS"]["no_identity"], 1, "{body}");
        assert_eq!(v["registry_nhs_listing_truncated"], false, "{body}");
        let listing = v["registry_nhs_listing"].as_array().expect("listed");
        let held = |hs: &serde_json::Value| -> Vec<(i64, serde_json::Value, bool)> {
            hs.as_array()
                .unwrap()
                .iter()
                .map(|h| (h["org_id"].as_i64().unwrap(), h["identifier"].clone(), h["provisional"].as_bool().unwrap()))
                .collect()
        };
        let row = |e: &serde_json::Value| {
            (
                e["literal"].as_str().unwrap().to_owned(),
                e["value"].as_str().unwrap().to_owned(),
                e["identity"].clone(),
                e["class"].as_str().unwrap().to_owned(),
                e["ppon"].as_str().unwrap().to_owned(),
                held(&e["registry_holders"]),
                held(&e["ppon_holders"]),
                e["witness_publications"].clone(),
            )
        };
        let rows: Vec<_> = listing.iter().map(row).collect();
        assert_eq!(
            rows,
            vec![
                (
                    "GB-NHS-R0B".to_owned(),
                    "GBNHSR0B".to_owned(),
                    serde_json::Value::Null,
                    "both_distinct".to_owned(),
                    "PYDR3797LZLJ".to_owned(),
                    vec![(5, serde_json::Value::Null, true)],
                    vec![(6, "GBPPONPYDR3797LZLJ".into(), false)],
                    serde_json::json!(["ocds-e"]),
                ),
                (
                    "GB-NHS-RR8".to_owned(),
                    "GBNHSRR8".to_owned(),
                    "GBNHSRR8".into(),
                    "both_distinct".to_owned(),
                    "PDTR3338MNPG".to_owned(),
                    vec![(7, "GBNHSRR8".into(), false)],
                    vec![(8, "GBPPONPDTR3338MNPG".into(), false)],
                    serde_json::json!(["ocds-g"]),
                ),
            ],
            "{body}"
        );
        assert_eq!(listing[0]["registry_holders"][0]["name"], stsft, "{body}");
        assert_eq!(
            (listing[0]["registry_holder_count"].clone(), listing[0]["ppon_holder_count"].clone(), listing[0]["witnesses"].clone()),
            (1.into(), 1.into(), 1.into()),
            "{body}"
        );
        // The listing moves nothing: the company-number plan is the fixture's one pair.
        assert_eq!(v["pairs"], serde_json::json!(["03914810~PHDQ2359NZMP"]), "{body}");
        assert_eq!(v["registry_pairs_planned"], serde_json::json!([]), "{body}");

        // The wet run's residual carries no listing.
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let msg = sup.run_spec(&altid_job(4, false)).await.expect("wet merges");
        assert!(msg.contains("WET: merged 1 of 1 reviewed live pairs"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["residual_of_wet_run"], true, "{body}");
        assert!(v.get("registry_nhs_listing").is_none(), "{body}");
        assert!(v.get("registry_nhs_listing_truncated").is_none(), "{body}");
        remove_db(&path);
    }

    /// Issue 448: `altid` is a rule of `match-org-identifiers`, dry unless told
    /// otherwise, and the refusal an operator meets for a mistyped rule names it.
    #[tokio::test]
    async fn the_unknown_rule_message_lists_altid() {
        let sup = Supervisor::new(scratch().await, "archive".into(), reqwest::Client::new());
        let mut typo = req("match-org-identifiers");
        typo.rule = Some("alt-id".into());
        let err = sup.enqueue_request(&typo).await.expect_err("an unknown rule is refused");
        assert!(err.contains("altid"), "the message must list the rule: {err}");
        let mut altid = req("match-org-identifiers");
        altid.rule = Some("altid".into());
        sup.enqueue_request(&altid).await.expect("altid enqueues");
        let queued = sup.queued();
        assert_eq!(queued.len(), 1);
        assert_eq!(queued[0].params, "match-org-identifiers altid dry-run");
    }

    fn nhs_body_job(id: u64, dry: bool) -> Job {
        Job {
            id,
            kind: "match-org-identifiers".into(),
            params: String::new(),
            spec: Spec::MatchOrgIdentifiersNhsBody { dry_run: dry, max_groups: None },
            resume_after: None,
        }
    }

    fn nhs_body_unwind_job(id: u64, code: &str, dry: bool) -> Job {
        Job {
            id,
            kind: "match-org-identifiers".into(),
            params: String::new(),
            spec: Spec::MatchOrgIdentifiersNhsBodyUnwind { code: code.into(), dry_run: dry, cohort: None },
            resume_after: None,
        }
    }

    fn nhs_body_canary_job(id: u64, notices: &[i64]) -> Job {
        Job {
            id,
            kind: "match-org-identifiers".into(),
            params: String::new(),
            spec: Spec::MatchOrgIdentifiersNhsBodyCanary { notices: notices.to_vec() },
            resume_after: None,
        }
    }

    /// Issue 513: `nhs-body` is a rule of `match-org-identifiers`, dry unless told
    /// otherwise, and a mistyped rule's refusal names it and `nhs-body-unwind`. Since U4 a
    /// wet run enqueues (capped by `max_groups`), and the arm refuses it while there is
    /// nothing reviewed to hold it to: an empty key satellite, then no stored plan, then a
    /// plan from before U4 (no `admitted_codes`) — each refusal writes nothing. The unwind
    /// needs a three-character `code` and upper-cases it; `code` on another rule refuses.
    /// The canary needs `notices` (deduplicated, capped), is read-only (`dry_run: false`
    /// refuses), and `notices` on another rule refuses.
    #[tokio::test]
    async fn the_unknown_rule_message_lists_nhs_body_and_a_wet_run_needs_a_reviewed_plan() {
        let (db, conn, path) = altid_fixture("nhs-body-rules").await;
        let sup = Supervisor::new(db, "archive".into(), reqwest::Client::new());
        let mut typo = req("match-org-identifiers");
        typo.rule = Some("nhs_body".into());
        let err = sup.enqueue_request(&typo).await.expect_err("an unknown rule is refused");
        assert!(err.contains("nhs-body") && err.contains("nhs-body-unwind"), "the message must list the rules: {err}");
        let mut wet = req("match-org-identifiers");
        wet.rule = Some("nhs-body".into());
        wet.dry_run = Some(false);
        wet.max_groups = Some(20);
        sup.enqueue_request(&wet).await.expect("a wet run enqueues since U4");
        let mut dry = req("match-org-identifiers");
        dry.rule = Some("nhs-body".into());
        sup.enqueue_request(&dry).await.expect("the census enqueues, dry by default");
        let mut unwind = req("match-org-identifiers");
        unwind.rule = Some("nhs-body-unwind".into());
        let err = sup.enqueue_request(&unwind).await.expect_err("an unwind names its body");
        assert!(err.contains("`code`"), "{err}");
        unwind.code = Some("RTHX".into());
        assert!(sup.enqueue_request(&unwind).await.is_err(), "an ODS code is three characters");
        unwind.code = Some("rth".into());
        sup.enqueue_request(&unwind).await.expect("the unwind enqueues, dry by default");
        let mut stray = req("match-org-identifiers");
        stray.rule = Some("altid".into());
        stray.code = Some("RTH".into());
        let err = sup.enqueue_request(&stray).await.expect_err("code is the unwind's only");
        assert!(err.contains("nhs-body-unwind only"), "{err}");
        let mut canary = req("match-org-identifiers");
        canary.rule = Some("nhs-body-canary".into());
        let err = sup.enqueue_request(&canary).await.expect_err("a canary names its notices");
        assert!(err.contains("needs `notices`"), "{err}");
        canary.notices = Some((1..=(store::NHS_BODY_CANARY_NOTICES_CAP as i64 + 1)).collect());
        assert!(sup.enqueue_request(&canary).await.is_err(), "capped");
        canary.notices = Some(vec![14, 16, 14]);
        canary.dry_run = Some(false);
        let err = sup.enqueue_request(&canary).await.expect_err("the canary is read-only");
        assert!(err.contains("read-only"), "{err}");
        canary.dry_run = None;
        sup.enqueue_request(&canary).await.expect("the canary enqueues");
        let mut stray = req("match-org-identifiers");
        stray.rule = Some("nhs-body".into());
        stray.notices = Some(vec![14]);
        let err = sup.enqueue_request(&stray).await.expect_err("notices is the canary's only");
        assert!(err.contains("nhs-body-canary only"), "{err}");
        let params: Vec<String> = sup.queued().iter().map(|q| q.params.clone()).collect();
        assert_eq!(
            params,
            vec![
                "match-org-identifiers nhs-body cap=20",
                "match-org-identifiers nhs-body dry-run",
                "match-org-identifiers nhs-body-unwind code=RTH dry-run",
                "match-org-identifiers nhs-body-canary notices=14,16 read-only",
            ],
        );

        let err = sup.run_spec(&nhs_body_job(2, false)).await.expect_err("an empty satellite refuses a wet run");
        assert!(err.contains("org_match_keys is empty") && err.contains("nothing was written"), "{err}");
        altid_satellite(&conn).await;
        let err = sup.run_spec(&nhs_body_job(3, false)).await.expect_err("no stored plan refuses");
        assert!(err.contains("no stored nhs-body-plan") && err.contains("nothing was written"), "{err}");
        assert!(sup.db().latest_report("nhs-body-plan").await.unwrap().is_none(), "nothing recorded");
        sup.db().put_report("nhs-body-plan", r#"{"codes":[],"dry_run":true}"#, store::now_unix()).await.unwrap();
        let err = sup.run_spec(&nhs_body_job(4, false)).await.expect_err("a pre-U4 plan refuses");
        assert!(err.contains("no `admitted_codes`") && err.contains("re-run the dry plan"), "{err}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations").await, 2, "nothing was written");
        remove_db(&path);
    }

    /// Issue 519 U4 (decision §3.6, ruling 10): the unwind takes an optional `cohort` — one
    /// cohort of the body, last in first out — named in the job's params; an empty one is
    /// refused (omitting it is how every cohort is asked for), and `cohort` on any other rule
    /// refuses. A durable job row written before U4 (no `cohort`) still reads, as every cohort.
    #[tokio::test]
    async fn an_nhs_body_unwind_takes_a_cohort_and_cohort_is_the_unwinds_only() {
        let (db, _conn, path) = altid_fixture("nhs-body-unwind-cohort").await;
        let sup = Supervisor::new(db, "archive".into(), reqwest::Client::new());
        let mut unwind = req("match-org-identifiers");
        unwind.rule = Some("nhs-body-unwind".into());
        unwind.code = Some("qmf".into());
        unwind.cohort = Some("  ".into());
        let err = sup.enqueue_request(&unwind).await.expect_err("an empty cohort is refused");
        assert!(err.contains("`cohort`") && err.contains("omit it"), "{err}");
        unwind.cohort = Some("nhs-body-children-2026-10-13".into());
        sup.enqueue_request(&unwind).await.expect("a scoped unwind enqueues, dry by default");
        unwind.cohort = None;
        sup.enqueue_request(&unwind).await.expect("the code-wide unwind still enqueues");
        for rule in ["nhs-body", "nhs-body-canary", "altid"] {
            let mut stray = req("match-org-identifiers");
            stray.rule = Some(rule.into());
            stray.notices = (rule == "nhs-body-canary").then(|| vec![14]);
            stray.cohort = Some("nhs-body-children-2026-10-13".into());
            let err = sup.enqueue_request(&stray).await.expect_err("cohort is the unwind's only");
            assert!(err.contains("`cohort` is for rule nhs-body-unwind only"), "{rule}: {err}");
        }
        let params: Vec<String> = sup.queued().iter().map(|q| q.params.clone()).collect();
        assert_eq!(
            params,
            vec![
                "match-org-identifiers nhs-body-unwind code=QMF cohort=nhs-body-children-2026-10-13 dry-run",
                "match-org-identifiers nhs-body-unwind code=QMF dry-run",
            ],
        );
        let old: Spec = serde_json::from_str(r#"{"MatchOrgIdentifiersNhsBodyUnwind":{"code":"RTH","dry_run":true}}"#)
            .expect("a pre-U4 unwind row deserializes");
        assert!(matches!(old, Spec::MatchOrgIdentifiersNhsBodyUnwind { cohort: None, .. }));
        remove_db(&path);
    }

    /// Issue 519 U4 (review): the census line's S4 count is the HALTING entries only
    /// (`name`, `ppon`, `identity`); an `identity-stray` — a mis-published child mention the
    /// triple arm rightly refused — is counted apart, listed, never a halt, so a stray does
    /// not read as "1 keys regrown" on 513's daily S4 read.
    #[test]
    fn the_nhs_body_line_counts_identity_strays_apart_from_the_s4_halt() {
        let entry = |kind: &'static str, org_id: i64| store::NhsBodyRegrown {
            code: "QMF".into(),
            kind,
            key: "GBNHS13T".into(),
            org_id,
            survivor: Some(40),
        };
        let mut r = store::NhsBodyReport {
            ledger_rows: 2,
            nhs_body_regrown: vec![entry("identity-stray", 72), entry("identity-stray", 73)],
            ..store::NhsBodyReport::default()
        };
        let msg = nhs_body_summary(&r, true);
        assert!(msg.contains("ledger: 2 nhs-body rows, 0 keys regrown (S4), 2 identity-stray listed (no halt)"), "{msg}");
        r.nhs_body_regrown.extend([entry("identity", 74), entry("name", 75), entry("ppon", 76)]);
        let msg = nhs_body_summary(&r, true);
        assert!(msg.contains("ledger: 2 nhs-body rows, 3 keys regrown (S4), 2 identity-stray listed (no halt)"), "{msg}");
    }

    /// Issue 513 U2, through the PRODUCTION table and rules (`ingest::nhs_ods`, the
    /// normaliser, the crosswalk): Oxford's body as unit 1 found such bodies — two spelling
    /// clusters its `GB-NHS-RTH` parties bound by name, the PPON org a PPON-first party
    /// names beside the code, and a stray (`University of Oxford` typed RTH) — plus `ICB`,
    /// a tail ODS does not know, and `GB-NHS-ROB`, R0B typed with a letter O, which the real
    /// table folds uniquely into R0B (it has no O/0 twin). The dry census lists all four RTH
    /// holders with the real ODS check, folds ROB, lists ICB off the allowlist, and stores
    /// `nhs-body-plan`; a reviewer's verdict over exactly the RTH holders is then admitted
    /// by the next dry run. Nothing is written.
    #[tokio::test]
    async fn an_nhs_body_census_lists_every_holder_and_admits_a_reviewed_verdict() {
        let path = format!("/tmp/tender-db-sup-nhs-body-{}-{}.db", std::process::id(), store::now_unix());
        remove_db(&path);
        let db = Arc::new(store::Db::open(&path).await.unwrap());
        let conn = store::turso::Builder::new_local(&path).build().await.unwrap().connect().unwrap();
        conn.execute("PRAGMA foreign_keys = OFF", ()).await.unwrap();
        let org = "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at) VALUES";
        let notice = "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at) VALUES";
        let id = "INSERT INTO notice_ids (notice_id, section_id, field_id, ordinal, scheme, value, is_ref) VALUES";
        let mention = "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier, scheme) VALUES";
        let ouh = "Oxford University Hospitals NHS Foundation Trust";
        let ouh_ft = "Oxford University Hospitals NHS FT";
        let upper = "OXFORD UNIVERSITY HOSPITALS NHS FOUNDATION TRUST";
        let cm = "NHS Cheshire and Merseyside ICB";
        let sts = "South Tyneside and Sunderland NHS Foundation Trust";
        for sql in [
            format!("{org} (5, 'GB', NULL, NULL, '{ouh}', 'oxford university hospitals nhs foundation trust', 1, 0)"),
            format!("{org} (6, 'GB', NULL, NULL, '{ouh_ft}', 'oxford university hospitals nhs ft', 1, 0)"),
            format!("{org} (7, 'GB', 'national', 'GBPPONPHDQ2359NZMP', '{upper}', 'oxford university hospitals nhs foundation trust', 0, 0)"),
            format!("{org} (8, 'GB', NULL, NULL, 'University of Oxford', 'university of oxford', 1, 0)"),
            format!("{org} (9, 'GB', NULL, NULL, '{cm}', 'nhs cheshire and merseyside icb', 1, 0)"),
            format!("{org} (10, 'GB', NULL, NULL, '{sts}', 'south tyneside and sunderland nhs foundation trust', 1, 0)"),
            format!("{notice} (14, 'fts', 'ocds-a', 'h', 'fts:ocds-1.1', 1, 'a', 0)"),
            format!("{notice} (15, 'fts', 'ocds-b', 'h', 'fts:ocds-1.1', 1, 'b', 0)"),
            format!("{notice} (16, 'fts', 'ocds-c', 'h', 'fts:ocds-1.1', 1, 'c', 0)"),
            format!("{notice} (17, 'fts', 'ocds-d', 'h', 'fts:ocds-1.1', 1, 'd', 0)"),
            format!("{notice} (18, 'fts', 'ocds-e', 'h', 'fts:ocds-1.1', 1, 'e', 0)"),
            format!("{notice} (19, 'fts', 'ocds-f', 'h', 'fts:ocds-1.1', 1, 'f', 0)"),
            format!("{id} (14, 'ORG-A', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-RTH', 0)"),
            format!("{id} (15, 'ORG-B', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-RTH', 0)"),
            format!("{id} (16, 'ORG-C', 'BT-501-Organization-Company', 0, 'GB-PPON', 'GB-PPON-PHDQ-2359-NZMP', 0)"),
            format!("{id} (16, 'ORG-C', 'BT-501-Organization-Company', 1, 'GB-NHS', 'GB-NHS-RTH', 0)"),
            format!("{id} (17, 'ORG-D', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-RTH', 0)"),
            format!("{id} (18, 'ORG-E', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-ICB', 0)"),
            format!("{id} (19, 'ORG-F', 'BT-501-Organization-Company', 0, 'GB-NHS', 'GB-NHS-ROB', 0)"),
            format!("{mention} (14, 'ORG-A', 5, '{ouh}', 'GB', 'GB-NHS-RTH', 'GB-NHS')"),
            format!("{mention} (15, 'ORG-B', 6, '{ouh_ft}', 'GB', 'GB-NHS-RTH', 'GB-NHS')"),
            format!("{mention} (16, 'ORG-C', 7, '{upper}', 'GB', 'GB-PPON-PHDQ-2359-NZMP', 'GB-PPON')"),
            format!("{mention} (17, 'ORG-D', 8, 'University of Oxford', 'GB', 'GB-NHS-RTH', 'GB-NHS')"),
            format!("{mention} (18, 'ORG-E', 9, '{cm}', 'GB', 'GB-NHS-ICB', 'GB-NHS')"),
            format!("{mention} (19, 'ORG-F', 10, '{sts}', 'GB', 'GB-NHS-ROB', 'GB-NHS')"),
        ] {
            conn.execute(sql.as_str(), ()).await.unwrap();
        }
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let plan = || {
            let sup = &sup;
            async move {
                let (body, _) = sup.db().latest_report("nhs-body-plan").await.unwrap().expect("recorded");
                (serde_json::from_str::<serde_json::Value>(&body).unwrap(), body)
            }
        };
        // `codes[]` is in code order, and `R0B` sorts before `RTH`.
        let code_of = |v: &serde_json::Value, code: &str| {
            v["codes"].as_array().unwrap().iter().find(|c| c["code"] == code).cloned().unwrap_or_else(|| {
                panic!("{code} not planned: {v}")
            })
        };

        let msg = sup.run_spec(&nhs_body_job(3, true)).await.expect("the census runs");
        assert!(msg.contains("DRY RUN — census recorded as nhs-body-plan"), "{msg}");
        assert!(msg.contains("5 coded GB parties (4 on the allowlist, 1 of them by an O/0 fold"), "{msg}");
        assert!(msg.contains("2 codes, 5 holders"), "{msg}");
        assert!(msg.contains("1 tails off the allowlist"), "{msg}");
        assert!(msg.contains("generic-name wall saw nothing"), "an empty satellite is said: {msg}");
        let (v, body) = plan().await;
        assert_eq!(v["dry_run"], true, "{body}");
        assert_eq!(v["generic_wall_readable"], false, "{body}");
        assert_eq!(v["ods_version"], ingest::nhs_ods::VERSION, "{body}");
        // The real `survivor_code` folds ROB into R0B: a swapped or non-folding lookup
        // in the wiring would list ROB off the allowlist instead.
        assert_eq!(v["folded_parties"], 1, "{body}");
        let r0b = code_of(&v, "R0B");
        assert_eq!(
            r0b["tails"],
            serde_json::json!([{"tail": "ROB", "parties": 1, "later_parties": 0, "folded": true}]),
            "{body}"
        );
        assert_eq!(r0b["holder_ids"], serde_json::json!([10]), "{body}");
        let rth = &code_of(&v, "RTH");
        assert_eq!(rth["code"], "RTH", "{body}");
        assert_eq!(rth["ods"]["name"], "OXFORD UNIVERSITY HOSPITALS NHS FOUNDATION TRUST", "{body}");
        assert_eq!(rth["holder_ids"], serde_json::json!([5, 6, 7, 8]), "{body}");
        assert_eq!(rth["ppons"], serde_json::json!(["PHDQ2359NZMP"]), "{body}");
        let checks: Vec<(i64, String, String)> = rth["holders"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| {
                (
                    h["org_id"].as_i64().unwrap(),
                    h["via"].as_str().unwrap().to_owned(),
                    h["check"]["verdict"].as_str().unwrap().to_owned(),
                )
            })
            .collect();
        assert_eq!(
            checks,
            vec![
                (5, "party".to_owned(), "admitted".to_owned()),
                (6, "party".to_owned(), "admitted".to_owned()),
                (7, "ppon".to_owned(), "admitted".to_owned()),
                (8, "party".to_owned(), "non-nhs".to_owned()),
            ],
            "{body}"
        );
        assert_eq!(rth["holders"][2]["minted_identity"], false, "a PPON is no minted identity: {body}");
        assert_eq!(v["off_allowlist"][0]["tail"], "ICB", "{body}");
        assert_eq!(v["off_allowlist"][0]["ods"], serde_json::Value::Null, "{body}");
        assert_eq!(v["admitted_verdict"], 0, "{body}");

        // U3's shape: the reviewer reads all four holders, keeps the stray out.
        let verdict = store::MergeVerdict {
            country: "GB".into(),
            scheme: store::NHS_BODY_SCHEME.into(),
            key: "RTH".into(),
            members: vec![5, 6, 7],
            action: "merge".into(),
            rationale: "ODS RTH; University of Oxford is not the trust".into(),
            confidence: "high".into(),
            reviewed_holders: Some(vec![5, 6, 7, 8]),
        };
        db.record_merge_verdicts("nhs-body-ods-confirmed-test", &[verdict], store::now_unix()).await.unwrap();
        let msg = sup.run_spec(&nhs_body_job(4, true)).await.expect("the census re-runs");
        assert!(msg.contains("verdicts: 1 admitted, 0 not admitted"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(v["admitted_verdict"], 1, "{body}");
        assert_eq!(code_of(&v, "RTH")["verdict"]["status"], "admitted", "{body}");
        assert_eq!(code_of(&v, "RTH")["verdict"]["reviewed_holders"], serde_json::json!([5, 6, 7, 8]), "{body}");
        // A census moves nothing.
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations").await, 6);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_log").await, 0);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_verdicts WHERE applied_at IS NOT NULL").await, 0);
        assert_eq!(v["admitted_codes"], serde_json::json!(["RTH"]), "{body}");

        // Issue 513 U4, the round trip: the wet run folds the admitted body into its PPON org
        // (7), ledgered, the code recorded on it, the verdict stamped; the stored plan is the
        // residual (nothing left) with the ledger's evidence parsed back to JSON.
        altid_satellite(&conn).await;
        db.build_organization_indexes().await.unwrap();
        let msg = sup.run_spec(&nhs_body_job(5, false)).await.expect("the wet run folds");
        assert!(msg.contains("WET: folded 1 reviewed bodies (1 merged") && msg.contains("2 org rows removed"), "{msg}");
        assert!(msg.contains("held against 1 stored: 0 deferred") && msg.contains("residual 0 bodies"), "{msg}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (5, 6)").await, 0);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organization_mentions WHERE organization_id = 7").await, 3);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_log WHERE rule = 'nhs-body' AND keep = 7").await, 2);
        assert_eq!(
            altid_count(&conn, "SELECT COUNT(*) FROM organization_merged_identifiers WHERE identifier = 'GBNHSRTH' AND org_id = 7")
                .await,
            1
        );
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_verdicts WHERE applied_at IS NOT NULL").await, 1);
        let (v, body) = plan().await;
        assert_eq!((v["dry_run"].as_bool(), v["residual_of_wet_run"].as_bool()), (Some(false), Some(true)), "{body}");
        assert_eq!(v["admitted_codes"], serde_json::json!([]), "the residual: {body}");
        assert_eq!(v["live_admitted_codes"], serde_json::json!(["RTH"]), "{body}");
        assert_eq!(v["folded"][0]["keep"], 7, "{body}");
        assert_eq!(v["folded"][0]["target"], "ppon", "{body}");
        // `codes[]` is the pre-fold census: the folded body says so, the other does not.
        let folded = |code: &str| code_of(&v, code)["folded"].as_bool();
        assert_eq!((folded("RTH"), folded("R0B")), (Some(true), Some(false)), "{body}");
        assert_eq!(v["ledger_rows"], 2, "{body}");
        let evidence = &v["nhs_body_merged"][0]["evidence"];
        assert_eq!((evidence["code"].as_str(), evidence["target"].as_str()), (Some("RTH"), Some("ppon")), "{body}");
        assert_eq!(evidence["target_identity"], "GBPPONPHDQ2359NZMP", "{body}");
        assert_eq!(evidence["cohort"], "nhs-body-ods-confirmed-test", "{body}");
        // The re-dry: the body reads as one org, its verdict applied, nothing regrown (S4).
        let msg = sup.run_spec(&nhs_body_job(6, true)).await.expect("the census re-runs");
        assert!(msg.contains("ledger: 2 nhs-body rows, 0 keys regrown"), "{msg}");
        let (v, body) = plan().await;
        assert_eq!(code_of(&v, "RTH")["holder_ids"], serde_json::json!([7, 8]), "{body}");
        assert_eq!(code_of(&v, "RTH")["verdict"]["status"], "applied", "{body}");
        assert_eq!(v["nhs_body_regrown"], serde_json::json!([]), "{body}");

        // S5's prod half, through the production rules: the coded spellings, the PPON-first
        // party and the stray re-resolve through a fresh armed resolver onto the orgs they
        // are recorded on, and the rolled-back transaction leaves every row as it was.
        let on_7 = "SELECT COUNT(*) FROM organization_mentions WHERE organization_id = 7";
        let mentions_before = altid_count(&conn, on_7).await;
        let msg = sup.run_spec(&nhs_body_canary_job(9, &[14, 15, 16, 17, 99])).await.expect("the canary runs");
        assert!(msg.contains("READ-ONLY") && msg.contains("AGREES"), "{msg}");
        assert!(msg.contains("4 mention(s) of 5 notice(s) re-resolved: 4 agree, 0 disagree"), "{msg}");
        assert!(msg.contains("no recorded mention on [99]"), "{msg}");
        assert!(msg.contains("nhs-body alias asked 2, bound 2"), "the two spellings, by the alias: {msg}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organizations").await, 4, "nothing minted");
        assert_eq!(altid_count(&conn, on_7).await, mentions_before);
        let (body, _) = sup.db().latest_report("nhs-body-canary").await.unwrap().expect("recorded");
        assert!(body.contains("\"agree\":4") && body.contains("\"disagree\":0"), "{body}");

        // D7: the unwind, dry then wet — the two spellings dissolve back to their own rows.
        let msg = sup.run_spec(&nhs_body_unwind_job(7, "RTH", true)).await.expect("the dry unwind");
        assert!(msg.contains("DRY RUN") && msg.contains("2 of its 3 mentions moved off (2 by name"), "{msg}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_log WHERE rule = 'nhs-body'").await, 2, "dry");
        let msg = sup.run_spec(&nhs_body_unwind_job(8, "RTH", false)).await.expect("the wet unwind");
        assert!(msg.contains("WET") && msg.contains("2 ledger rows retired, 2 loser ids redirected"), "{msg}");
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM org_merge_log WHERE rule = 'nhs-body'").await, 0);
        assert_eq!(altid_count(&conn, "SELECT COUNT(*) FROM organization_mentions WHERE organization_id = 7").await, 1);
        let (body, _) = sup.db().latest_report("nhs-body-unwind").await.unwrap().expect("recorded");
        assert!(body.contains("\"code\":\"RTH\"") && body.contains("\"moved\":2"), "{body}");
        remove_db(&path);
    }

    /// Issue 519 unit 2: the census through the PRODUCTION child map and strict gate. QHM's
    /// PPON org (5) holds the body; 13T's identity org (6, `GB-NHS-13T` mints) holds it only
    /// through the child code, and B2M3M's (7) — a five-character child — is found by its
    /// identity seek alone, under QWU, which a QWU-coded cluster (8) lists. The stored plan
    /// lists both children with the real `child_check` answers (13T's NENC name admitted, its
    /// CSU name refused: `child-name-mixed`), and the summary carries the child clause with
    /// the map's version. A census moves nothing.
