    fn guid_twin_cleanup(path: &str) {
        for suffix in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{path}{suffix}"));
        }
    }

    /// One row-count read on a test connection.
    async fn count_of(conn: &store::turso::Connection, sql: &str) -> i64 {
        let mut rows = conn.query(sql, ()).await.unwrap();
        match rows.next().await.unwrap().unwrap().get_value(0).unwrap() {
            store::turso::Value::Integer(n) => n,
            other => panic!("{sql}: {other:?}"),
        }
    }

    /// Issue 530 unit 3 (Build 1): the job wired to the REAL `idgate::uuid_v4`, rule 530-T
    /// (`ingest::project::guid_twin::guid_twin_decide`), `guid_role_class` and (Build 1b) A7's role
    /// mapping `ingest::project::guid_twin::guid_twin_role_ref`. Without a deferred index it refuses and
    /// stores nothing; with them it stores `guid-twin-plan` — the Göttingen award's DÖE copy names the
    /// buyer under two GUIDs, both rows are planned whole onto the DE identifier-NULL row 2294259 (never
    /// the VAT row) and R1's bars pass — and answers a one-line summary; nothing is written but the
    /// report, and a cancelled run stores none. The R1 control is planned under its OWN role references,
    /// stored as the DÖE copy holds them (DE-1.x ids, the buyer's unflagged as before issue 98's
    /// inventory fix): Procedure-Buyer on ORG-0001 and Lot-AddInfo on ORG-0002, no review slot on its
    /// name, so A7's guard reads both and binds nothing (a stub mapping would read 0 references).
    /// Build 2: the wet run refuses — before any write — on a re-plan that trips a tripwire (a verdict on
    /// a planned row) and on a reconcile that disagrees with the stored plan; applies on a fresh plan,
    /// records A1's boundary and A10's Verify ids (the kept no-twin row 23014305, the max org id after);
    /// the recurrence arm then passes; a restart and a staged second job find nothing left; and a FRESH
    /// dry plan after the dissolve passes R1 (the controls it dissolved are met through the log), so a
    /// later wet run is not wedged.
    #[tokio::test]
    async fn the_dissolve_guid_twins_job_refuses_without_its_indexes_and_stores_its_plan() {
        use store::turso::Value;
        let (db, conn, path) = guid_twin_job_fixture("u3").await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let job = |id: u64| Job {
            id,
            kind: "dissolve-guid-twins".into(),
            params: String::new(),
            spec: Spec::DissolveGuidTwins {
                dry_run: true,
                stable_mentions: GUID_CENSUS_STABLE_MENTIONS,
                samples: 30,
                extra_unsafe_names: Vec::new(),
            },
            resume_after: None,
        };
        let err = sup.run_spec(&job(1)).await.expect_err("the deferred tender indexes are absent");
        assert!(err.contains("dissolve-guid-twins refused"), "{err}");
        assert!(db.latest_report(GUID_TWIN_REPORT).await.unwrap().is_none(), "a refusal stores nothing");

        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let msg = sup.run_spec(&job(2)).await.expect("plan");
        assert!(msg.starts_with("dissolve-guid-twins (issue 530, DRY): 3 GUID row(s)"), "{msg}");
        // Build 2 (A3 iii): the compiled KEEP and names, the newest notice, the new tripwires read.
        assert!(
            msg.contains(&format!(
                "KEEP compiled \"{}\": {} value(s)",
                ingest::project::guid_twin::GUID_KEEP_530_VERSION,
                ingest::project::guid_twin::keep_530().len()
            )),
            "{msg}"
        );
        // OQ1's exposure: the twin copy's refused ORG-0001 is its Procedure-Buyer (the DE-1.x alias mapped).
        assert!(msg.contains("(1 copy(ies) with a refused buyer)"), "{msg}");
        assert!(msg.contains("notices to id 26483900"), "{msg}");
        assert!(msg.contains("PLAN: 2 row(s) whole (2 mention(s)), 0 partial (0 rehome(s)"), "{msg}");
        assert!(msg.contains("Targets: 1 key(s), 1 with an identifier-NULL row"), "{msg}");
        assert!(
            msg.contains("1 wet window(s) of up to 2000 mention(s) or ~120000 re-read mention(s) (largest 2 mention(s), window 1; the largest target's window 1; HEAVIEST by re-read: window 1, ~2 re-read mention(s), its biggest target 2294259 \"DE landkreis göttingen\" with 0 today)"),
            "{msg}"
        );
        assert!(msg.contains("R1 BARS PASS"), "{msg}");
        assert!(msg.contains("22759261 planned whole") && msg.contains("254 not_planned not a GUID row"), "{msg}");
        assert!(msg.contains("23014305 not_planned no"), "the no-twin row is found and kept: {msg}");
        assert!(msg.contains("DE landkreis göttingen: 3 GUID row(s), 2 planned, 0 partial, 1 kept"), "{msg}");
        assert!(msg.contains("references read for 1 twin copy(ies), 2 row(s), 2 (section, role) pair(s)"), "{msg}");
        assert!(msg.contains("role-mix refused 0, merge survivor 0, under review 0; rule/planner role disagreements 0"), "{msg}");
        assert!(msg.contains("compiled KEEP self-check missing 0 (keep_add_commit 0 line(s))"), "{msg}");
        assert!(msg.ends_with("NOTHING IS WRITTEN."), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_REPORT).await.unwrap().expect("report");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["planned_row_ids"], serde_json::json!([22_759_261, 22_759_262]), "{body}");
        assert_eq!(report["largest_target"]["target_id"], 2_294_259, "{body}");
        assert_eq!(report["bars"]["pass"], true, "{body}");
        assert_eq!(report["roles"]["by_role_set"]["Lot-AddInfo+Procedure-Buyer"], 1, "{body}");
        // A7 through the REAL mapping: the twin copy's two references read and mapped (a stub returning
        // no role would give role_refs 0), coherent, so nothing bound and nothing tripped.
        assert_eq!(report["role_ref_notices"], 1, "{body}");
        assert_eq!(report["role_ref_rows_read"], 2, "{body}");
        assert_eq!(report["role_refs"], 2, "{body}");
        assert_eq!(report["guard"]["role_mix"]["groups"], 0, "{body}");
        assert_eq!(report["bars"]["tripwire_role_mix"], 0, "{body}");
        assert_eq!(report["bars"]["role_ref_disagree"], 0, "{body}");
        let refused = &report["roles"]["incoherent"];
        assert_eq!(refused.as_array().map(Vec::len), Some(0), "{body}");
        assert_eq!(report["salt"], 530_003, "{body}");
        assert_eq!(report["not_planned_ids"][0], 254, "{body}");
        assert!(report["rule"].as_str().unwrap().contains("the gate is WIRED"), "{body}");
        assert_eq!(report["keep_source"], "compiled", "{body}");
        assert_eq!(report["keep_version"], ingest::project::guid_twin::GUID_KEEP_530_VERSION, "{body}");
        assert_eq!(report["keep_size"], ingest::project::guid_twin::keep_530().len(), "{body}");
        assert_eq!(report["refused_buyer_copies"], 1, "{body}");
        assert_eq!(report["notice_max_id"], 26_483_900, "{body}");
        assert_eq!(report["log_high_water"], 0, "{body}");
        assert_eq!(report["wet_windows"]["wet_windows"], 1, "{body}");
        assert_eq!(report["wet_windows"]["heaviest_window"]["rebound_estimate"], 2, "F1: the target's 0 existing + 2 planned: {body}");
        assert_eq!(report["wet_windows"]["windows"][0]["rebound_estimate"], 2, "{body}");
        assert_eq!(report["exhibits"]["DE landkreis göttingen"]["kept_ids"], serde_json::json!([23_014_305]), "{body}");
        assert_eq!(report["bars"]["under_review_checked"], true, "{body}");
        assert!(report.get("wet_mentions").is_none(), "the wet list is not serialized");
        // Read-only: the GUID rows and their mentions stand as they were.
        let still = count_of(&conn, "SELECT COUNT(*) FROM organization_mentions WHERE organization_id IN (22759261, 22759262)").await;
        assert_eq!(still, 2, "a dry plan moves nothing");

        // A cancelled run stores nothing over the plan.
        db.put_report(GUID_TWIN_REPORT, "{\"marker\":1}", store::now_unix()).await.unwrap();
        sup.cancel_running.store(3, Ordering::Relaxed);
        let msg = sup.run_spec(&job(3)).await.expect("stopped plan");
        assert!(msg.contains("STOPPED by cancel") && msg.contains("no report stored"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_REPORT).await.unwrap().expect("report");
        assert_eq!(body, "{\"marker\":1}", "a stopped plan stores nothing");

        // Build 2: the WET run on this binary's fresh plan.
        sup.run_spec(&job(4)).await.expect("the plan again");
        db.set_foreign_keys(false).await.unwrap();
        // A1's boundary (every parsed notice at or below it projected before the deploy): here every notice
        // of the fixture is pre-deploy stock, so the boundary is the newest one (review round 3, F9: a
        // boundary below the twin copy is refused — that copy was folded before the gate).
        let gate = 26_483_900;
        let wet = |id: u64| Job {
            id,
            kind: "dissolve-guid-twins".into(),
            params: String::new(),
            spec: Spec::DissolveGuidTwinsWet { max_windows: Some(1), gate_since_notice_id: Some(gate) },
            resume_after: None,
        };
        let untouched = || async {
            assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 2, "nothing dissolved");
            assert_eq!(
                count_of(&conn, "SELECT COUNT(*) FROM organization_mentions WHERE organization_id IN (22759261, 22759262)").await,
                2,
                "nothing moved"
            );
        };
        // (a) The re-plan trips a tripwire: a case review recorded for planned row 22759261 since the plan.
        conn.execute(
            "INSERT INTO org_case_reviews (case_org_id, cohort, verdict, diagnosis, handling, rationale, confidence, reviewed_at)
             VALUES (22759261, 'c', 'v', 'd', 'h', 'r', 'high', 0)",
            (),
        )
        .await
        .unwrap();
        let err = sup.run_spec(&wet(9)).await.expect_err("the re-plan fails");
        assert!(err.contains("the re-plan fails") && err.contains("under-review tripwire 1"), "{err}");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((report["outcome"].as_str(), report["replan"]["bars"]["tripwire_under_review"].as_u64()), (Some("refused"), Some(1)), "{body}");
        assert!(report["reconcile"].is_null(), "step 5 is never reached: {body}");
        assert!(db.guid_twin_log(9).await.unwrap().is_empty());
        untouched().await;
        conn.execute("DELETE FROM org_case_reviews", ()).await.unwrap();
        // (b) The reconcile disagrees: the stored plan holds 22759262 PARTIAL, the re-plan whole — every
        // bar still passes, so only the tuple reconcile can refuse it.
        let (body, computed_at) = db.latest_report(GUID_TWIN_REPORT).await.unwrap().expect("plan");
        let mut doctored: serde_json::Value = serde_json::from_str(&body).unwrap();
        doctored["planned_row_ids"] = serde_json::json!([22_759_261]);
        doctored["partial_row_ids"] = serde_json::json!([22_759_262]);
        db.put_report(GUID_TWIN_REPORT, &doctored.to_string(), computed_at).await.unwrap();
        let err = sup.run_spec(&wet(10)).await.expect_err("no reconcile");
        assert!(err.contains("does not reconcile") && !err.contains("the re-plan fails"), "{err}");
        let (rbody, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&rbody).unwrap();
        assert_eq!(report["outcome"], "refused", "{rbody}");
        assert_eq!(report["reconcile"]["ok"], false, "{rbody}");
        assert_eq!(report["reconcile"]["dropped"], serde_json::json!([[22_759_262, false]]), "{rbody}");
        assert_eq!(report["reconcile"]["added"], serde_json::json!([[22_759_262, true]]), "{rbody}");
        assert!(db.guid_twin_log(10).await.unwrap().is_empty());
        untouched().await;
        db.put_report(GUID_TWIN_REPORT, &body, computed_at).await.unwrap();

        // Applied: the re-plan reconciles, one window (one target key) dissolves both rows onto 2294259,
        // the manifest is stored.
        let msg = sup.run_spec(&wet(5)).await.expect("applied");
        assert!(msg.starts_with("dissolve-guid-twins wet (issue 530 Build 2) APPLIED"), "{msg}");
        assert!(msg.contains("Windows: 1 of 1 applied this run (0 earlier by this job); 2 mention(s) moved, 2 row(s) dissolved"), "{msg}");
        assert!(msg.contains("Reverse drift (A1): 0 mention(s) of 0 value(s) since notice Some(26483900)"), "{msg}");
        let mut rows = conn
            .query("SELECT DISTINCT organization_id FROM organization_mentions WHERE notice_id = 26483825", ())
            .await
            .unwrap();
        assert_eq!(rows.next().await.unwrap().unwrap().get_value(0).unwrap(), Value::Integer(2_294_259));
        assert!(rows.next().await.unwrap().is_none());
        drop(rows);
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 0);
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("the manifest");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["outcome"], "applied", "{body}");
        assert_eq!(report["manifest"]["dissolved"].as_array().map(Vec::len), Some(2), "{body}");
        assert_eq!(report["manifest"]["reused_targets"], serde_json::json!([2_294_259]), "{body}");
        assert_eq!(report["reconcile"]["ok"], true, "{body}");
        assert_eq!(report["gate_since_notice_id"], 26_483_900, "the passed boundary, recorded: {body}");
        assert_eq!(report["reverse_drift"]["reverse_drift_mentions"], 0, "{body}");
        // A10: the kept no-twin row is the surviving list; the max org id is read AFTER the windows.
        let max_after = count_of(&conn, "SELECT MAX(id) FROM organizations").await;
        assert_eq!(max_after, 23_014_305, "the dissolved rows are gone");
        assert_eq!(report["verify"]["goettingen_kept_ids"], serde_json::json!([23_014_305]), "{body}");
        assert_eq!(report["verify"]["goettingen_surviving_ids"], serde_json::json!([23_014_305]), "{body}");
        assert_eq!(report["verify"]["wet_max_org_id"], max_after, "{body}");
        assert_eq!(report["wet_max_org_id"], max_after, "{body}");
        assert!(msg.contains("Max org id after: Some(23014305)"), "{msg}");
        assert_eq!(report["r3"]["manifest_mentions_campaign"], 2, "{body}");
        assert_eq!(report["r3"]["windows_log_equal"], true, "{body}");
        assert!(report["windows"][0]["hold_ms"].is_u64(), "{body}");
        // A1's recurrence arm, wired to the compiled statics: the manifest's one target, no candidate.
        let recur = Job {
            id: 11,
            kind: "dissolve-guid-twins".into(),
            params: String::new(),
            spec: Spec::GuidTwinRecurrence { since_notice_id: None, samples: 10 },
            resume_after: None,
        };
        let msg = sup.run_spec(&recur).await.expect("recurrence");
        assert!(msg.contains("recurrence (issue 530 A1) PASS"), "{msg}");
        let (rbody, _) = db.latest_report(GUID_TWIN_RECURRENCE_REPORT).await.unwrap().expect("stored");
        let rec: serde_json::Value = serde_json::from_str(&rbody).unwrap();
        assert_eq!((rec["targets_from_log"].as_u64(), rec["candidate_count"].as_u64(), rec["pass"].as_bool()), (Some(1), Some(0), Some(true)), "{rbody}");
        assert_eq!(rec["refused_mentions"], 2, "the two moved mentions, refused by the compiled rule: {rbody}");
        // The same job again (a restart): its logged rows close the reconcile, nothing is left to apply,
        // and its window counts against max_windows.
        let msg = sup.run_spec(&wet(5)).await.expect("a resumed job finds nothing left");
        assert!(msg.contains("Windows: 0 of 0 applied this run (1 earlier by this job)"), "{msg}");
        assert!(msg.contains("Manifest: 2 logged mention(s) on this dry plan (2 by job 5)"), "{msg}");
        // Another job on the same dry plan (a staged second run): the rows logged since the plan close the
        // reconcile and meet the controls; nothing is left; its manifest is the campaign's.
        let msg = sup.run_spec(&wet(6)).await.expect("a staged second run");
        assert!(msg.contains("Windows: 0 of 0 applied") && msg.contains("Manifest: 2 logged mention(s) on this dry plan (0 by job 6)"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["manifest"]["dissolved"].as_array().map(Vec::len), Some(2), "the campaign's manifest survives the later job: {body}");
        // A FRESH dry plan after the dissolve passes R1: its planned controls are gone, but the log shows a
        // wet run dissolved them whole onto 2294259. A wet run on it is accepted (nothing is left).
        let msg = sup.run_spec(&job(7)).await.expect("the plan after");
        assert!(msg.contains("R1 BARS PASS"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_REPORT).await.unwrap().expect("plan");
        let fresh = guid_twin_stored_dry(&body).unwrap();
        assert_eq!(fresh.log_high_water, Some(2));
        assert!(guid_twin_check_dry(&fresh).is_ok());
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        let control = report["controls"].as_array().unwrap().iter().find(|c| c["org_id"] == 22_759_261).unwrap().clone();
        assert_eq!((control["dissolved_by_wet"].as_bool(), control["ok"].as_bool()), (Some(true), Some(true)), "{control}");
        let msg = sup.run_spec(&wet(8)).await.expect("not wedged");
        assert!(msg.contains("APPLIED") && msg.contains("Windows: 0 of 0 applied") && msg.contains("Manifest: 0 logged mention(s)"), "{msg}");
        drop(conn);
        guid_twin_cleanup(&path);
    }

    /// A second twin beside the job fixture's Göttingen award: `Landkreis Musterhausen` named under two
    /// GUIDs by notice 26483850 (Tender 948290), both rows planned whole onto its DE identifier-NULL row
    /// 2400000 — an independent target key, so a small window size splits the plan into two windows.
    async fn guid_twin_second_twin(conn: &store::turso::Connection) {
        use store::turso::Value;
        conn.execute(
            "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at,
                                  published_at, parse_state)
             VALUES (26483850, 'doe', 'd26483850', 'h', 'eforms:eforms-de-1.2', 1, 'm', 0, 1717200000, 'parsed')",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO tender_versions (tender_id, seq, caused_by_notice_id, published_at, publication_id)
             VALUES (948290, 1, 26483850, 1717200000, 'd')",
            (),
        )
        .await
        .unwrap();
        for (id, identifier) in [
            (2_400_000i64, None),
            (22_800_001, Some("1C2D3E4F5A6B4C7D8E9F0A1B2C3D4E5F")),
            (22_800_002, Some("2D3E4F5A6B7C4D8E9F0A1B2C3D4E5F60")),
        ] {
            conn.execute(
                "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
                 VALUES (?, 'DE', ?, ?, 'Landkreis Musterhausen', 'landkreis musterhausen', 0, 0)",
                (
                    Value::Integer(id),
                    identifier.map_or(Value::Null, |_| Value::Text("national".into())),
                    identifier.map_or(Value::Null, |i: &str| Value::Text(i.into())),
                ),
            )
            .await
            .unwrap();
        }
        for (org, section, guid) in [
            (22_800_001i64, "ORG-0001", "1c2d3e4f-5a6b-4c7d-8e9f-0a1b2c3d4e5f"),
            (22_800_002, "ORG-0002", "2d3e4f5a-6b7c-4d8e-9f0a-1b2c3d4e5f60"),
        ] {
            conn.execute(
                "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier)
                 VALUES (26483850, ?, ?, 'Landkreis Musterhausen', 'DE', ?)",
                (Value::Text(section.into()), Value::Integer(org), Value::Text(guid.into())),
            )
            .await
            .unwrap();
        }
    }

    /// Issue 530 Build 2: the `max_windows` cap and the stop checkpoint BETWEEN windows (543) on a real
    /// job with several windows — two independent target keys at a window size of 2. A `max_windows: 1`
    /// job applies exactly one window (PARTIAL, outcome `capped`) and logs it; the same job restarted
    /// applies none (its committed window counts against its cap); a second job on the same dry plan
    /// applies the rest, numbering its window as its own (1), the reconcile closing with the first job's
    /// rows, and the manifest is the campaign's. On a fresh fixture a cancel after window 1 stops the job
    /// between windows: the report is stored `stopped`, window 1 stands, window 2 is not applied, and the
    /// job fails.
    #[tokio::test]
    async fn the_wet_twin_dissolve_caps_stages_and_stops_between_windows() {
        for cancel in [false, true] {
            let tag = if cancel { "530w-stop" } else { "530w-cap" };
            let (db, conn, path) = guid_twin_job_fixture(tag).await;
            guid_twin_second_twin(&conn).await;
            db.build_organization_indexes().await.unwrap();
            db.build_tender_indexes().await.unwrap();
            let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
            sup.guid_twin_window_mentions.store(2, Ordering::Relaxed);
            let dry = Job {
                id: 1,
                kind: "dissolve-guid-twins".into(),
                params: String::new(),
                spec: Spec::DissolveGuidTwins {
                    dry_run: true,
                    stable_mentions: GUID_CENSUS_STABLE_MENTIONS,
                    samples: 30,
                    extra_unsafe_names: Vec::new(),
                },
                resume_after: None,
            };
            let msg = sup.run_spec(&dry).await.expect("plan");
            assert!(msg.contains("PLAN: 4 row(s) whole") && msg.contains("R1 BARS PASS"), "{msg}");
            db.set_foreign_keys(false).await.unwrap();
            let wet = |id: u64, max_windows: Option<u64>| Job {
                id,
                kind: "dissolve-guid-twins".into(),
                params: String::new(),
                spec: Spec::DissolveGuidTwinsWet { max_windows, gate_since_notice_id: Some(26_483_900) },
                resume_after: None,
            };
            let windows_of = |job: i64| {
                let db = db.clone();
                async move { db.guid_twin_log(job).await.unwrap().iter().map(|r| r.window_no).collect::<std::collections::BTreeSet<_>>() }
            };
            let musterhausen = || count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22800001, 22800002)");
            if !cancel {
                let msg = sup.run_spec(&wet(2, Some(1))).await.expect("a capped run is a partial success");
                assert!(msg.contains("PARTIAL: max_windows Some(1)") && msg.contains("Windows: 1 of 2 applied this run"), "{msg}");
                let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
                let report: serde_json::Value = serde_json::from_str(&body).unwrap();
                assert_eq!((report["outcome"].as_str(), report["windows_applied"].as_u64(), report["windows_planned"].as_u64()), (Some("capped"), Some(1), Some(2)), "{body}");
                assert_eq!(windows_of(2).await, [1].into_iter().collect(), "window 1 (Göttingen, the smaller key) only");
                assert_eq!(musterhausen().await, 2, "the second key untouched");
                // A KEEP-add deploy mid-campaign: the campaign's dry plan fails this binary's check, so a
                // manifest-only job is refused — yet it still stores the campaign's manifest (the plan's
                // high-water mark is read before the plan is checked).
                let (plan_body, _) = db.latest_report(GUID_TWIN_REPORT).await.unwrap().expect("the dry plan");
                let mut stale: serde_json::Value = serde_json::from_str(&plan_body).unwrap();
                stale["keep_version"] = serde_json::json!("keep-530-before-a-keep-add");
                db.put_report(GUID_TWIN_REPORT, &stale.to_string(), store::now_unix()).await.unwrap();
                let err = sup.run_spec(&wet(6, Some(0))).await.expect_err("the old plan fails this binary's check");
                assert!(err.contains("cannot drive a wet run") && err.contains("keep-530-before-a-keep-add"), "{err}");
                let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
                let report: serde_json::Value = serde_json::from_str(&body).unwrap();
                assert_eq!(report["outcome"], "refused", "{body}");
                let dissolved: Vec<i64> =
                    report["manifest"]["dissolved"].as_array().unwrap().iter().map(|d| d["org_id"].as_i64().unwrap()).collect();
                assert_eq!(dissolved, vec![22_759_261, 22_759_262], "the campaign's manifest even so: {body}");
                db.put_report(GUID_TWIN_REPORT, &plan_body, store::now_unix()).await.unwrap();
                // Review round 3 (F2): a MANIFEST-ONLY job on the same dry plan after the capped one — the
                // recovery of a `manifest_unread` job — runs every check, applies no window and stores the
                // campaign's manifest (window 1 of job 2), where re-queuing job 2's own JSON would apply window 2.
                let msg = sup.run_spec(&wet(5, Some(0))).await.expect("manifest only");
                assert!(msg.starts_with("dissolve-guid-twins wet MANIFEST ONLY (max_windows 0)") && msg.contains("Windows: 0 of 1 applied"), "{msg}");
                let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
                let report: serde_json::Value = serde_json::from_str(&body).unwrap();
                assert_eq!((report["outcome"].as_str(), report["windows_applied"].as_u64()), (Some("manifest_only"), Some(0)), "{body}");
                let dissolved: Vec<i64> =
                    report["manifest"]["dissolved"].as_array().unwrap().iter().map(|d| d["org_id"].as_i64().unwrap()).collect();
                assert_eq!(dissolved, vec![22_759_261, 22_759_262], "the campaign's manifest, job 2's window: {body}");
                assert!(windows_of(5).await.is_empty(), "no new log rows");
                assert_eq!(musterhausen().await, 2, "window 2 not applied");
                // The same job restarted: its committed window counts against its cap.
                let msg = sup.run_spec(&wet(2, Some(1))).await.expect("restart");
                assert!(msg.contains("PARTIAL") && msg.contains("Windows: 0 of 1 applied this run (1 earlier by this job)"), "{msg}");
                assert_eq!(musterhausen().await, 2);
                // A second job on the same dry plan applies the rest.
                let msg = sup.run_spec(&wet(3, None)).await.expect("the rest");
                assert!(msg.contains("APPLIED") && msg.contains("Windows: 1 of 1 applied this run (0 earlier by this job)"), "{msg}");
                assert!(msg.contains("Reconcile: ok"), "{msg}");
                assert_eq!(windows_of(3).await, [1].into_iter().collect(), "window numbers are per job");
                assert_eq!(musterhausen().await, 0);
                let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
                let report: serde_json::Value = serde_json::from_str(&body).unwrap();
                let dissolved: Vec<i64> =
                    report["manifest"]["dissolved"].as_array().unwrap().iter().map(|d| d["org_id"].as_i64().unwrap()).collect();
                assert_eq!(dissolved, vec![22_759_261, 22_759_262, 22_800_001, 22_800_002], "both jobs' rows: {body}");
                assert_eq!(report["r3"]["manifest_mentions_this_job"], 2, "{body}");
                assert_eq!(report["r3"]["windows_log_equal"], true, "{body}");
            } else {
                sup.guid_twin_cancel_after_windows.store(1, Ordering::Relaxed);
                let err = sup.run_spec(&wet(4, None)).await.expect_err("stopped between windows");
                assert!(err.contains("STOPPED by cancel after 1 window(s)"), "{err}");
                let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored before the job fails");
                let report: serde_json::Value = serde_json::from_str(&body).unwrap();
                assert_eq!((report["outcome"].as_str(), report["windows_applied"].as_u64()), (Some("stopped"), Some(1)), "{body}");
                assert_eq!(windows_of(4).await, [1].into_iter().collect(), "window 1 stands");
                assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 0);
                assert_eq!(musterhausen().await, 2, "window 2 not applied");
            }
            drop(conn);
            guid_twin_cleanup(&path);
        }
    }

    /// Issue 530 Build 2, A1 at job level: a compiled-KEEP value refused before it joined KEEP — its
    /// mention on an identifier-NULL row although the compiled rule binds it — is REVERSE DRIFT. The wet
    /// run refuses while it stands (nothing written), the recurrence arm reads it, the restore arm moves
    /// it onto ONE minted identified row (as a rebuild binds it; `guid-twin-restore`), and the wet run
    /// then applies.
    #[tokio::test]
    async fn the_reverse_drift_refuses_the_wet_run_until_the_restore_arm_moves_it() {
        use store::turso::Value;
        // The committed KEEP file's first value, as a platform publishes it, and a fresh v4 value.
        const K: &str = "0000bb8f-e88c-4f63-ac7b-4f7567774c1f";
        const F: &str = "9a8b7c6d-5e4f-4a3b-9c2d-1e0f9a8b7c6d";
        assert!(ingest::project::guid_twin::keep_530().contains(K), "premise: K is in the compiled KEEP");
        let (db, conn, path) = guid_twin_job_fixture("530-drift").await;
        conn.execute(
            "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at,
                                  published_at, parse_state)
             VALUES (26483950, 'doe', 'd26483950', 'h', 'eforms:eforms-de-1.2', 1, 'm', 0, 1717200000, 'parsed')",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO tender_versions (tender_id, seq, caused_by_notice_id, published_at, publication_id)
             VALUES (948310, 1, 26483950, 1717200000, 'd')",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
             VALUES (2500000, 'DE', NULL, NULL, 'Landkreis Kassel', 'landkreis kassel', 1, 0)",
            (),
        )
        .await
        .unwrap();
        for (section, raw) in [("ORG-0001", K), ("ORG-0002", F)] {
            conn.execute(
                "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier)
                 VALUES (26483950, ?, 2500000, 'Landkreis Kassel', 'DE', ?)",
                (Value::Text(section.into()), Value::Text(raw.into())),
            )
            .await
            .unwrap();
        }
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let run = |id: u64, spec: Spec| Job { id, kind: "dissolve-guid-twins".into(), params: String::new(), spec, resume_after: None };
        let dry = Spec::DissolveGuidTwins { dry_run: true, stable_mentions: GUID_CENSUS_STABLE_MENTIONS, samples: 30, extra_unsafe_names: Vec::new() };
        assert!(sup.run_spec(&run(1, dry)).await.expect("plan").contains("R1 BARS PASS"));
        db.set_foreign_keys(false).await.unwrap();
        // A1's boundary: the fixture's pre-deploy stock ends at 26483900; the K/F copy 26483950 is post-deploy.
        let gate = Some(26_483_900);
        let wet = || Spec::DissolveGuidTwinsWet { max_windows: None, gate_since_notice_id: gate };
        let err = sup.run_spec(&run(2, wet())).await.expect_err("drift refuses");
        assert!(err.contains("1 mention(s) in reverse drift since notice 26483900") && err.contains("\"restore\":true"), "{err}");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["reverse_drift"]["reverse_drift_mentions"], 1, "{body}");
        assert_eq!(report["reverse_drift"]["reverse_drift"][0]["restore"], "mint", "{body}");
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 2, "nothing written");
        let msg = sup.run_spec(&run(3, Spec::GuidTwinRecurrence { since_notice_id: gate, samples: 10 })).await.expect("recurrence");
        assert!(msg.contains("REVERSE DRIFT") && msg.contains("reverse drift 1 mention(s) of 1 value(s) (stock 0, since 1)"), "{msg}");
        let msg = sup.run_spec(&run(4, Spec::GuidTwinRestore { since_notice_id: gate })).await.expect("restore");
        assert!(msg.contains("restore (issue 530 A1) DONE") && msg.contains("1 value(s) restored, 1 mention(s) moved") && msg.contains("1 minted"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_RESTORE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((report["outcome"].as_str(), report["restored"][0]["minted"].as_bool()), (Some("restored"), Some(true)), "{body}");
        let mut rows = conn
            .query(
                "SELECT m.section_id, o.identifier, o.identifier_kind, o.country FROM organization_mentions m \
                   JOIN organizations o ON o.id = m.organization_id WHERE m.notice_id = 26483950 ORDER BY 1",
                (),
            )
            .await
            .unwrap();
        let k = rows.next().await.unwrap().unwrap();
        assert_eq!(
            (k.get_value(1).unwrap(), k.get_value(2).unwrap(), k.get_value(3).unwrap()),
            (Value::Text("0000BB8FE88C4F63AC7B4F7567774C1F".into()), Value::Text("national".into()), Value::Text("DE".into())),
            "K sits on its identified row, as a rebuild binds it"
        );
        let f = rows.next().await.unwrap().unwrap();
        assert_eq!(f.get_value(1).unwrap(), Value::Null, "F, refused, stays on the name-keyed row");
        drop(rows);
        let msg = sup.run_spec(&run(5, wet())).await.expect("the drift restored, the wet run applies");
        assert!(msg.contains("APPLIED") && msg.contains("Reverse drift (A1): 0 mention(s)"), "{msg}");
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 0);
        drop(conn);
        guid_twin_cleanup(&path);
    }

    /// Issue 530 Build 2 (review round 2): the restore refuses — before any read, storing nothing — without
    /// the org FK indexes; A1's boundary is anchored: before any wet window a `since_notice_id` at or above
    /// the newest notice, or above the stored dry plan's `notice_max_id`, is refused; from the first window
    /// on the boundary it logged is the only value the wet run, the recurrence arm and the restore accept,
    /// and the recurrence arm defaults to it (its report says where its boundary came from). Review round 3:
    /// a boundary BELOW the stock twin copy (F9: that copy, folded before the gate, sits on GUID rows the
    /// re-plan holds) is refused by the wet run and the restore before any write, naming the copy; and once
    /// the log is emptied (F10: a from-archive rebuild) the recurrence arm with no `since_notice_id` refuses
    /// instead of reading nothing, while an explicit `1` reads.
    #[tokio::test]
    async fn the_restore_and_recurrence_arms_are_anchored_to_the_recorded_boundary() {
        use store::turso::Value;
        let (db, conn, path) = guid_twin_job_fixture("530-anchor").await;
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let run = |id: u64, spec: Spec| Job { id, kind: "dissolve-guid-twins".into(), params: String::new(), spec, resume_after: None };
        // A1's boundary: above the stock twin copy 26483825, at or below the plan's start.
        let gate = 26_483_850;
        let err = sup.run_spec(&run(1, Spec::GuidTwinRestore { since_notice_id: Some(gate) })).await.expect_err("no indexes");
        assert!(err.contains("dissolve-guid-twins restore refused: missing") && err.contains("organization_names_org"), "{err}");
        assert!(db.latest_report(GUID_TWIN_RESTORE_REPORT).await.unwrap().is_none(), "a refusal stores nothing");
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let dry = Spec::DissolveGuidTwins { dry_run: true, stable_mentions: GUID_CENSUS_STABLE_MENTIONS, samples: 30, extra_unsafe_names: Vec::new() };
        assert!(sup.run_spec(&run(2, dry)).await.expect("plan").contains("R1 BARS PASS"));
        let err = sup.run_spec(&run(3, Spec::GuidTwinRestore { since_notice_id: Some(26_483_900) })).await.expect_err("an empty walk");
        assert!(err.contains("at or above the newest notice 26483900"), "{err}");
        // A notice newer than the plan: a boundary between the plan's start and it is a typo.
        conn.execute(
            "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at,
                                  published_at, parse_state)
             VALUES (26483999, 'doe', 'd26483999', 'h', 'eforms:eforms-de-1.2', 1, 'm', 0, 1717200000, 'parsed')",
            (),
        )
        .await
        .unwrap();
        let err = sup.run_spec(&run(4, Spec::GuidTwinRecurrence { since_notice_id: Some(26_483_950), samples: 10 })).await.expect_err("past the plan");
        assert!(err.contains("above the stored dry plan's notice_max_id 26483900"), "{err}");
        assert!(db.latest_report(GUID_TWIN_RECURRENCE_REPORT).await.unwrap().is_none());
        // The wet run logs the boundary it was given.
        db.set_foreign_keys(false).await.unwrap();
        let wet = |since: i64| Spec::DissolveGuidTwinsWet { max_windows: None, gate_since_notice_id: Some(since) };
        // F9: a boundary below the stock twin copy (a dropped digit, a stale probe) — the wet run and the
        // restore refuse before any write, naming the highest pre-gate copy above it.
        // Step 1 cannot be re-read after the deploy (a max id read then would hide the copies the gate refused
        // since): both refusals name the value to pass, the highest pre-gate copy.
        let err = sup.run_spec(&run(11, wet(26_483_824))).await.expect_err("below the stock");
        assert!(err.contains("boundary 26483824 is below notice 26483825, which was folded before the gate") && err.contains("step 1"), "{err}");
        assert!(err.contains("Pass 26483825, the highest copy folded before the gate") && !err.contains("re-read step 1"), "{err}");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((report["outcome"].as_str(), report["reverse_drift"]["forward_drift_since_max_notice"].as_i64()), (Some("refused"), Some(26_483_825)), "{body}");
        assert!(db.guid_twin_log(11).await.unwrap().is_empty());
        let err = sup.run_spec(&run(12, Spec::GuidTwinRestore { since_notice_id: Some(26_483_824) })).await.expect_err("restore below");
        assert!(err.contains("restore REFUSED") && err.contains("is below notice 26483825"), "{err}");
        assert!(err.contains("Pass 26483825") && !err.contains("re-read step 1"), "{err}");
        assert!(db.latest_report(GUID_TWIN_RESTORE_REPORT).await.unwrap().is_none(), "nothing written");
        assert_eq!(db.guid_twin_recorded_boundary().await.unwrap(), None, "nothing recorded");
        // The named value clears the below-check (a manifest-only job: every check, no window, nothing logged).
        let named = Spec::DissolveGuidTwinsWet { max_windows: Some(0), gate_since_notice_id: Some(26_483_825) };
        let msg = sup.run_spec(&run(15, named)).await.expect("the named value passes every check");
        assert!(msg.starts_with("dissolve-guid-twins wet MANIFEST ONLY (max_windows 0)"), "{msg}");
        assert_eq!(db.guid_twin_recorded_boundary().await.unwrap(), None, "a manifest-only job records nothing");
        assert!(sup.run_spec(&run(5, wet(gate))).await.expect("applied").contains("APPLIED"));
        assert_eq!(db.guid_twin_recorded_boundary().await.unwrap(), Some(gate));
        let mut rows = conn.query("SELECT DISTINCT gate_since_notice_id FROM guid_twin_dissolve_log", ()).await.unwrap();
        assert_eq!(rows.next().await.unwrap().unwrap().get_value(0).unwrap(), Value::Integer(gate));
        assert!(rows.next().await.unwrap().is_none());
        drop(rows);
        // From now on, only that value.
        let err = sup.run_spec(&run(6, wet(gate - 1))).await.expect_err("another boundary");
        assert!(err.contains(&format!("is not A1's boundary {gate}")), "{err}");
        let err = sup.run_spec(&run(7, Spec::GuidTwinRestore { since_notice_id: Some(gate + 1) })).await.expect_err("restore off the boundary");
        assert!(err.contains(&format!("since_notice_id {} is not A1's boundary {gate}", gate + 1)) && err.contains("Nothing was read or written"), "{err}");
        assert!(db.latest_report(GUID_TWIN_RESTORE_REPORT).await.unwrap().is_none());
        let err = sup
            .run_spec(&run(8, Spec::GuidTwinRecurrence { since_notice_id: Some(gate + 1), samples: 10 }))
            .await
            .expect_err("recurrence off the boundary");
        assert!(err.contains("is not A1's boundary"), "{err}");
        // The recurrence arm defaults to the recorded boundary, and says so.
        let msg = sup.run_spec(&run(9, Spec::GuidTwinRecurrence { since_notice_id: None, samples: 10 })).await.expect("recurrence");
        assert!(msg.contains("PASS") && msg.contains(&format!("above notice Some({gate})")), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_RECURRENCE_REPORT).await.unwrap().expect("stored");
        let rec: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((rec["since_notice_id"].as_i64(), rec["boundary"]["recorded"].as_i64()), (Some(gate), Some(gate)), "{body}");
        assert_eq!(rec["boundary"]["source"], "the recorded boundary (none passed)", "{body}");
        let msg = sup.run_spec(&run(10, Spec::GuidTwinRestore { since_notice_id: Some(gate) })).await.expect("restore on the boundary");
        assert!(msg.contains("restore (issue 530 A1) DONE") && msg.contains("0 value(s) restored"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_RESTORE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(report["boundary"]["matches_recorded"], true, "{body}");
        // F10: a from-archive rebuild empties the log. The recurrence arm with no since refuses (it would
        // read the dissolve-log targets alone: nothing), an explicit since reads.
        conn.execute("DELETE FROM guid_twin_dissolve_log", ()).await.unwrap();
        let err = sup.run_spec(&run(13, Spec::GuidTwinRecurrence { since_notice_id: None, samples: 10 })).await.expect_err("no boundary");
        assert!(err.contains("no boundary is recorded") && err.contains("or 1 after a rebuild"), "{err}");
        let msg = sup.run_spec(&run(14, Spec::GuidTwinRecurrence { since_notice_id: Some(1), samples: 10 })).await.expect("explicit since");
        assert!(msg.contains("above notice Some(1)"), "{msg}");
        // With nothing recorded, the below-check is back — but a refresh residue is no pre-gate fold: a copy a
        // re-parse turned into a twin after the gate, its changed sibling re-resolved name-keyed (2294259) and
        // its unchanged one kept on its own GUID row, is forward drift (a wet run's work), never a low boundary.
        guid_twin_copy(&conn, 26_483_960, 948_320, [(2_294_259, "9a8b7c6d-5e4f-4a3b-9c2d-1e0f9a8b7c6d"), (23_100_001, "1b2c3d4e-5f6a-4b7c-8d9e-0f1a2b3c4d5e")]).await;
        let msg = sup.run_spec(&run(16, Spec::GuidTwinRestore { since_notice_id: Some(gate) })).await.expect("a residue is no pre-gate fold");
        assert!(msg.contains("restore (issue 530 A1) DONE") && msg.contains("0 value(s) restored"), "{msg}");
        // A copy folded before the gate (both refused sections on their GUID rows) above the value is refused…
        guid_twin_copy(&conn, 26_483_970, 948_330, [(23_100_002, "2c3d4e5f-6a7b-4c8d-9e0f-1a2b3c4d5e6f"), (23_100_003, "3d4e5f6a-7b8c-4d9e-8f0a-2b3c4d5e6f7a")]).await;
        let err = sup.run_spec(&run(17, Spec::GuidTwinRestore { since_notice_id: Some(gate) })).await.expect_err("a pre-gate copy above");
        assert!(err.contains(&format!("boundary {gate} is below notice 26483970")) && err.contains("Pass 26483970"), "{err}");
        // …except at 1, the corpus start after a from-archive rebuild (which folded every notice under the gate).
        let msg = sup.run_spec(&run(18, Spec::GuidTwinRestore { since_notice_id: Some(1) })).await.expect("1 is never checked from below");
        assert!(msg.contains("restore (issue 530 A1) DONE"), "{msg}");
        drop(conn);
        guid_twin_cleanup(&path);
    }

    /// Issue 530 (review round 3): one twin copy on the Göttingen fixture — notice `notice` in Tender `tender`,
    /// two "Landkreis Göttingen" ORG sections, each `(org, raw v4 value)`; an org id from 23,100,000 up is
    /// created as that value's own DE GUID row.
    async fn guid_twin_copy(conn: &store::turso::Connection, notice: i64, tender: i64, sections: [(i64, &str); 2]) {
        use store::turso::Value;
        conn.execute(
            "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at,
                                  published_at, parse_state)
             VALUES (?, 'doe', ?, 'h', 'eforms:eforms-de-1.2', 1, 'm', 0, 1717200000, 'parsed')",
            (Value::Integer(notice), Value::Text(format!("d{notice}"))),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO tender_versions (tender_id, seq, caused_by_notice_id, published_at, publication_id)
             VALUES (?, 1, ?, 1717200000, 'd')",
            (Value::Integer(tender), Value::Integer(notice)),
        )
        .await
        .unwrap();
        for (k, (org, raw)) in sections.into_iter().enumerate() {
            if org >= 23_100_000 {
                conn.execute(
                    "INSERT INTO organizations (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
                     VALUES (?, 'DE', 'national', ?, 'Landkreis Göttingen', 'landkreis göttingen', 0, 0)",
                    (Value::Integer(org), Value::Text(raw.replace('-', "").to_uppercase())),
                )
                .await
                .unwrap();
            }
            conn.execute(
                "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier)
                 VALUES (?, ?, ?, 'Landkreis Göttingen', 'DE', ?)",
                (Value::Integer(notice), Value::Text(format!("ORG-000{}", k + 1)), Value::Integer(org), Value::Text(raw.into())),
            )
            .await
            .unwrap();
        }
    }

    /// Issue 530 (review round 3): after a from-archive rebuild `guid_twin_dissolve_log` is empty and A1's
    /// boundary is the corpus start, 1. The below-check never fires at 1 (every copy was folded under the
    /// gate), so the forward-drift wet run — here over the stock and a refresh residue — applies, and its
    /// first window records 1. A value above 1 is still checked, and names the pre-gate copy, never the
    /// (higher) residue.
    #[tokio::test]
    async fn a_boundary_of_1_is_the_corpus_start_after_a_rebuild() {
        let (db, conn, path) = guid_twin_job_fixture("530-rebuilt").await;
        guid_twin_copy(&conn, 26_483_960, 948_320, [(2_294_259, "9a8b7c6d-5e4f-4a3b-9c2d-1e0f9a8b7c6d"), (23_100_001, "1b2c3d4e-5f6a-4b7c-8d9e-0f1a2b3c4d5e")]).await;
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let run = |id: u64, spec: Spec| Job { id, kind: "dissolve-guid-twins".into(), params: String::new(), spec, resume_after: None };
        let dry = Spec::DissolveGuidTwins { dry_run: true, stable_mentions: GUID_CENSUS_STABLE_MENTIONS, samples: 30, extra_unsafe_names: Vec::new() };
        let msg = sup.run_spec(&run(1, dry)).await.expect("plan");
        assert!(msg.contains("R1 BARS PASS"), "{msg}");
        db.set_foreign_keys(false).await.unwrap();
        let wet = |since: i64| Spec::DissolveGuidTwinsWet { max_windows: None, gate_since_notice_id: Some(since) };
        let err = sup.run_spec(&run(2, wet(26_483_824))).await.expect_err("below the stock");
        assert!(err.contains("is below notice 26483825") && err.contains("Pass 26483825"), "the pre-gate copy, never the residue 26483960: {err}");
        let restore = sup.run_spec(&run(3, Spec::GuidTwinRestore { since_notice_id: Some(1) })).await.expect("the restore at 1");
        assert!(restore.contains("restore (issue 530 A1) DONE"), "{restore}");
        let msg = sup.run_spec(&run(4, wet(1))).await.expect("the wet run at 1");
        assert!(msg.contains("APPLIED"), "{msg}");
        assert_eq!(db.guid_twin_recorded_boundary().await.unwrap(), Some(1), "its first window records 1");
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262, 23100001)").await, 0, "the residue row moved too");
        drop(conn);
        guid_twin_cleanup(&path);
    }

    /// Issue 530 Build 2 (review round 2, A1 + A3 iii): a KEEP-add candidate the wet run's own drift read
    /// finds — a value the gate already refused in a SECOND Tender since the boundary — whose own GUID row
    /// the re-plan would dissolve refuses the run before any write, naming its KEEP file line; one whose
    /// own row the re-plan does not hold does not refuse, and the report lists it for R3.
    #[tokio::test]
    async fn the_wet_run_refuses_a_keep_add_candidate_it_would_dissolve() {
        use store::turso::Value;
        let (db, conn, path) = guid_twin_job_fixture("530-cand").await;
        conn.execute(
            "INSERT INTO notices (id, source, publication_id, content_hash, profile, fetch_id, member_path, ingested_at,
                                  published_at, parse_state)
             VALUES (26483960, 'doe', 'd26483960', 'h', 'eforms:eforms-de-1.2', 1, 'm', 0, 1717200000, 'parsed')",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO tender_versions (tender_id, seq, caused_by_notice_id, published_at, publication_id)
             VALUES (948320, 1, 26483960, 1717200000, 'd')",
            (),
        )
        .await
        .unwrap();
        // A twin copy after the boundary: the gate refused 22759261's value and a fresh one onto 2294259.
        for (section, raw) in [("ORG-0001", "037c1508-d945-4e73-9d6e-65099a79bec1"), ("ORG-0002", "9a8b7c6d-5e4f-4a3b-9c2d-1e0f9a8b7c6d")] {
            conn.execute(
                "INSERT INTO organization_mentions (notice_id, section_id, organization_id, name, country, raw_identifier)
                 VALUES (26483960, ?, 2294259, 'Landkreis Göttingen', 'DE', ?)",
                (Value::Text(section.into()), Value::Text(raw.into())),
            )
            .await
            .unwrap();
        }
        db.build_organization_indexes().await.unwrap();
        db.build_tender_indexes().await.unwrap();
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let run = |id: u64, spec: Spec| Job { id, kind: "dissolve-guid-twins".into(), params: String::new(), spec, resume_after: None };
        let dry = || Spec::DissolveGuidTwins { dry_run: true, stable_mentions: GUID_CENSUS_STABLE_MENTIONS, samples: 30, extra_unsafe_names: Vec::new() };
        assert!(sup.run_spec(&run(1, dry())).await.expect("plan").contains("R1 BARS PASS"));
        db.set_foreign_keys(false).await.unwrap();
        let wet = || Spec::DissolveGuidTwinsWet { max_windows: None, gate_since_notice_id: Some(26_483_900) };
        let err = sup.run_spec(&run(2, wet())).await.expect_err("a candidate on a planned row");
        assert!(err.contains("1 KEEP-add candidate(s) whose own GUID row the re-plan would dissolve"), "{err}");
        assert!(err.contains("DE\t037C1508D9454E739D6E65099A79BEC1\t22759261\t1\t2\tmulti_tender"), "the KEEP file line: {err}");
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 2, "nothing written");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((report["outcome"].as_str(), report["reverse_drift"]["candidates"][0]["own_row"].as_i64()), (Some("refused"), Some(22_759_261)), "{body}");
        // The same copy naming the kept no-twin row's value instead: its row is outside the re-plan, so the
        // run applies and lists the candidate for R3.
        conn.execute(
            "UPDATE organization_mentions SET raw_identifier = '7a1b2c3d-4e5f-4a6b-8c7d-9e0f1a2b3c4d' \
              WHERE notice_id = 26483960 AND section_id = 'ORG-0001'",
            (),
        )
        .await
        .unwrap();
        let msg = sup.run_spec(&run(3, wet())).await.expect("applied");
        assert!(msg.contains("APPLIED") && msg.contains("1 KEEP-add candidate(s) (7A1B2C3D4E5F4A6B8C7D9E0F1A2B3C4D"), "{msg}");
        let (body, _) = db.latest_report(GUID_TWIN_DISSOLVE_REPORT).await.unwrap().expect("stored");
        let report: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((report["outcome"].as_str(), report["reverse_drift"]["candidate_count"].as_u64()), (Some("applied"), Some(1)), "{body}");
        assert_eq!(report["reverse_drift"]["candidates"][0]["own_row"], 23_014_305, "{body}");
        assert_eq!(count_of(&conn, "SELECT COUNT(*) FROM organizations WHERE id IN (22759261, 22759262)").await, 0);
        drop(conn);
        guid_twin_cleanup(&path);
    }

    /// Issue 524 unit 2a: `refresh-org-names` takes the census's `min_mentions` and `samples` rules and
    /// checks `org_ids` (1 to the cap once deduplicated, each positive); an omitted `dry_run` is the
    /// plan. Unit 2b: `dry_run: false` queues the wet run under the same kind (`org_ids` checked alike,
    /// `max_groups: 0` refused), and `revert-org-name-refresh` requires its `job`. Both kinds are heavy
    /// writers and stoppable.
    #[tokio::test]
    async fn refresh_org_names_checks_its_params_dry_and_wet() {
        let sup = Supervisor::new(scratch().await, "archive".into(), reqwest::Client::new());
        let ask = |dry_run: Option<bool>, min_mentions: Option<u64>, samples: Option<u64>, org_ids: Option<Vec<i64>>| {
            JobRequest { kind: "refresh-org-names".into(), dry_run, min_mentions, samples, org_ids, ..Default::default() }
        };
        let err = sup.enqueue_request(&ask(None, Some(1), None, None)).await.expect_err("one mention elects nothing");
        assert!(err.contains("min_mentions") && err.contains("2 or more"), "{err}");
        assert!(sup.enqueue_request(&ask(None, None, None, Some(vec![]))).await.is_err(), "an empty scope");
        let err = sup.enqueue_request(&ask(None, None, None, Some(vec![5, 0]))).await.expect_err("id 0");
        assert!(err.contains("positive"), "{err}");
        let err = sup.enqueue_request(&ask(Some(false), None, None, Some(vec![-1]))).await.expect_err("wet, id -1");
        assert!(err.contains("positive"), "{err}");
        let too_many: Vec<i64> = (1..=ORG_NAME_REFRESH_ORG_IDS_MAX as i64 + 1).collect();
        assert!(sup.enqueue_request(&ask(None, None, None, Some(too_many))).await.is_err(), "over the cap");
        let zero = JobRequest { max_groups: Some(0), ..ask(Some(false), None, None, None) };
        let err = sup.enqueue_request(&zero).await.expect_err("a wet run that may rename nothing");
        assert!(err.contains("max_groups"), "{err}");
        let revert = |job: Option<i64>| JobRequest { kind: "revert-org-name-refresh".into(), job, ..Default::default() };
        let err = sup.enqueue_request(&revert(None)).await.expect_err("the job is required");
        assert!(err.contains("`job`"), "{err}");
        assert!(sup.enqueue_request(&revert(Some(0))).await.is_err(), "job 0");
        // The 2b review: there is no dry revert, so asking for one is refused rather than run wet.
        let dry_revert = JobRequest { dry_run: Some(true), ..revert(Some(2601)) };
        let err = sup.enqueue_request(&dry_revert).await.expect_err("no dry mode");
        assert!(err.contains("no dry run") && err.contains("org-name-refresh-applied"), "{err}");
        assert!(err.contains("`applied`") && err.contains("`prior_applied`"), "{err}");
        // The re-review: a field the revert does not take is refused, never ignored into a whole-job undo.
        for (field, ask) in [
            ("org_ids", JobRequest { org_ids: Some(vec![760]), ..revert(Some(2601)) }),
            ("max_groups", JobRequest { max_groups: Some(10), ..revert(Some(2601)) }),
            ("min_mentions", JobRequest { min_mentions: Some(2), ..revert(Some(2601)) }),
            ("samples", JobRequest { samples: Some(5), ..revert(Some(2601)) }),
        ] {
            let err = sup.enqueue_request(&ask).await.expect_err(field);
            assert!(err.contains(&format!("`{field}`")) && err.contains("no per-org or capped revert"), "{err}");
        }
        sup.enqueue_request(&ask(None, None, None, None)).await.expect("the defaults");
        sup.enqueue_request(&ask(Some(true), Some(3), Some(0), Some(vec![760, 61, 760]))).await.expect("scoped");
        sup.enqueue_request(&ask(Some(false), Some(1), None, None)).await.expect("wet: the plan's min_mentions apply");
        let capped = JobRequest { max_groups: Some(500), ..ask(Some(false), None, None, Some(vec![61, 760, 61])) };
        sup.enqueue_request(&capped).await.expect("wet, scoped and capped");
        sup.enqueue_request(&revert(Some(2601))).await.expect("the revert");
        let confirmed = JobRequest { dry_run: Some(false), ..revert(Some(2602)) };
        sup.enqueue_request(&confirmed).await.expect("`dry_run: false` confirms");
        let queued = sup.queued();
        assert_eq!(queued.len(), 6, "the refused asks queued nothing");
        assert_eq!(queued[0].kind, "refresh-org-names");
        assert_eq!(queued[0].params, "refresh-org-names dry min_mentions=2 samples=30");
        assert_eq!(queued[1].params, "refresh-org-names dry min_mentions=3 samples=1 org_ids=2", "deduplicated");
        assert_eq!((queued[2].kind.as_str(), queued[2].params.as_str()), ("refresh-org-names", "refresh-org-names wet"));
        assert_eq!(queued[3].params, "refresh-org-names wet org_ids=2 max_groups=500");
        assert_eq!(
            (queued[4].kind.as_str(), queued[4].params.as_str()),
            ("revert-org-name-refresh", "revert-org-name-refresh job=2601")
        );
        {
            let queue = sup.queue.lock().expect("queue lock");
            let specs: Vec<&Spec> = queue.iter().map(|j| &j.spec).collect();
            assert!(matches!(
                specs[2],
                Spec::RefreshOrgNamesWet { org_ids: None, max_groups: None, exclude_rules, exclude_released, exclude_stale_top }
                    if exclude_rules.is_empty() && exclude_released.is_empty() && !exclude_stale_top
            ));
            assert!(matches!(
                specs[3],
                Spec::RefreshOrgNamesWet { org_ids: Some(ids), max_groups: Some(500), .. } if ids == &vec![61, 760]
            ));
            assert!(matches!(specs[4], Spec::RevertOrgNameRefresh { job: 2601 }));
        }
        for kind in ["refresh-org-names", "revert-org-name-refresh"] {
            assert!(heavy_write_kind(kind), "{kind}: TRUNCATE-checkpointed write windows");
        }
        assert!(stoppable("refresh-org-names", &queued[0].params), "a cancel reaches the walk between pages");
        assert!(stoppable("refresh-org-names", &queued[2].params), "and the wet run between windows");
        assert!(stoppable("revert-org-name-refresh", &queued[4].params), "and the revert between windows");
        // The 60 canaries (rule v12's six on rule v11's 54 — v11's nine on rule v10's 45, v10's six on
        // rule v9's 39, v9's nine on rule v8's 30, which kept the recency decision's 27), each id once.
        let ids: std::collections::BTreeSet<i64> = ORG_NAME_REFRESH_CANARIES.iter().map(|c| c.id).collect();
        assert_eq!((ids.len(), ORG_NAME_REFRESH_CANARIES.len()), (60, 60));
        let expect = |id: i64| ORG_NAME_REFRESH_CANARIES.iter().find(|c| c.id == id).and_then(|c| c.expect);
        for id in [31_558_903, 22_713_056, 6_341_366, 760, 61, 10] {
            assert_eq!(expect(id), Some("keep:S1"), "{id}: applied by 2516, live under its new name");
        }
        // Rule v11: the six v10 canaries, applied by job 2554, are live under their new names.
        for id in [4_220_276, 4_823_670, 8_092_631, 8_152_890, 9_766_149, 4_993_534] {
            assert_eq!(expect(id), Some("keep:S1"), "{id}: applied by 2554");
        }
        // Rule v12: v11's step-4 canaries, applied by job 2565 — the six fresh tops and two stale tops.
        for id in [8_765_882, 5_393_731, 9_856_301, 7_822_785, 11_268_197, 5_011_106, 2_857_103, 2_715_115] {
            assert_eq!(expect(id), Some("keep:S1"), "{id}: applied by 2565");
        }
        // Rule v12: v11's step 5, capped job 2567, renamed the first 500 ready targets by org id (up to
        // past 2,675,242), 3042 and 1800186 among them.
        for id in [3_042, 1_800_186] {
            assert_eq!(expect(id), Some("keep:S1"), "{id}: applied by 2567");
        }
        // Rule v11: one canary per new hold, each naming the spelling it would serve (plan 2543's).
        for (id, reason) in [
            (1_556_789, store::HEAD_HOLD_TOP_STALE),
            (1_276_213, store::HEAD_HOLD_TOP_STALE),
            (1_345_526, store::HEAD_HOLD_TOP_STALE),
            (1_918_631, store::HEAD_HOLD_DOUBLED),
            (5_350_675, store::HEAD_HOLD_SEAT_DROPPED),
            (22_831_984, store::HEAD_HOLD_PLACEHOLDER_ID),
        ] {
            assert_eq!(expect(id), Some(format!("hold:{reason}").as_str()), "{id}");
            let canary = ORG_NAME_REFRESH_CANARIES.iter().find(|c| c.id == id).unwrap();
            assert!(canary.serves.is_some(), "{id}: the hold names the spelling it would serve");
        }
        for id in [178, 2_186, 3_262, 3_694, 6_867, 10_671, 1_076, 10_603, 3_909, 1_846] {
            assert_eq!(expect(id), Some("hold:recent"), "{id}");
        }
        // Rule v9: 4295185 (`glue`) and 9814 (`junk_only`) back under their v8 reason.
        for id in [3_740_262, 445, 334, 4_295_185, 9_814] {
            assert_eq!(expect(id), Some("hold:residue"), "{id}");
        }
        // Rule v10: v9's change:R1 canaries print their heads within 3 years of plan 2527, so seven hold
        // `head_current` (with the spelling each would serve); 3042, a digits release, still changed
        // (rule v11: a release is exempt from `top_stale`), and so did a fresh top with a rival (1800186);
        // rule v12: job 2567 renamed both (above), so no canary expects a change any more.
        for id in [1_220, 2_762, 3_406, 6_079, 11_179, 1_919, 791] {
            assert_eq!(expect(id), Some(format!("hold:{}", store::HEAD_HOLD_CURRENT).as_str()), "{id}");
            let canary = ORG_NAME_REFRESH_CANARIES.iter().find(|c| c.id == id).unwrap();
            assert!(canary.serves.is_some(), "{id}: the hold names the spelling it would serve");
        }
        let changes = ORG_NAME_REFRESH_CANARIES.iter().filter(|c| c.expect == Some("change:R1")).count();
        assert_eq!(changes, 0, "every change:R1 canary has been applied (3042 and 1800186 by job 2567)");
        // Rule v9: one canary per serve hold, each expecting the hold's reason by its store const.
        for (id, reason) in [
            (22_028_982, store::HEAD_HOLD_REVIEW_BODY),
            (4_065_575, store::HEAD_HOLD_ORGAN),
            (17_116_440, store::HEAD_HOLD_CODE_ADDED),
            (8_069_375, store::HEAD_HOLD_ADDRESS_ADDED),
            (16_508_165, store::HEAD_HOLD_CAPS_VARIANT),
        ] {
            assert_eq!(expect(id), Some(format!("hold:{reason}").as_str()), "{id}");
        }
        assert_eq!(expect(30_914_328), None);
    }

    /// Issue 524 rule v9's per-class wet-run filters at enqueue: `exclude_rules` and `exclude_released`
    /// are checked (non-empty, known classes, not every rule), refused on a dry plan and by the revert,
    /// deduplicated and sorted, and recorded on the params line and in the queued spec.
    #[tokio::test]
    async fn refresh_org_names_takes_the_v9_filters_on_a_wet_run_only() {
        let sup = Supervisor::new(scratch().await, "archive".into(), reqwest::Client::new());
        let strings = |v: &[&str]| Some(v.iter().map(|s| (*s).to_owned()).collect::<Vec<_>>());
        let ask = |dry_run: Option<bool>, rules: Option<Vec<String>>, released: Option<Vec<String>>| JobRequest {
            kind: "refresh-org-names".into(),
            dry_run,
            exclude_rules: rules,
            exclude_released: released,
            ..Default::default()
        };
        // A dry plan, asked or by default, refuses them.
        for dry_run in [None, Some(true)] {
            let err = sup.enqueue_request(&ask(dry_run, strings(&["R2"]), None)).await.expect_err("a dry plan");
            assert!(err.contains("`exclude_rules`") && err.contains("dry plan"), "{err}");
            let err = sup.enqueue_request(&ask(dry_run, None, strings(&["digits"]))).await.expect_err("a dry plan");
            assert!(err.contains("`exclude_released`"), "{err}");
        }
        for (rules, released, needle) in [
            (strings(&[]), None, "an empty `exclude_rules`"),
            (None, strings(&[]), "an empty `exclude_released`"),
            (strings(&["R3"]), None, "`exclude_rules` value \"R3\""),
            (strings(&["r2"]), None, "`exclude_rules` value \"r2\""),
            (None, strings(&["lowercase"]), "`exclude_released` value \"lowercase\""),
            (strings(&["R0e", "R0n", "R0w", "R1", "R2", "R2"]), None, "names every rule"),
        ] {
            let err = sup.enqueue_request(&ask(Some(false), rules, released)).await.expect_err(needle);
            assert!(err.contains(needle), "{needle}: {err}");
        }
        let revert = JobRequest {
            kind: "revert-org-name-refresh".into(),
            job: Some(2601),
            exclude_rules: strings(&["R2"]),
            ..Default::default()
        };
        let err = sup.enqueue_request(&revert).await.expect_err("the revert restores the whole job");
        assert!(err.contains("`exclude_rules`") && err.contains("no per-org or capped revert"), "{err}");
        assert!(sup.queued().is_empty(), "the refused asks queued nothing");
        sup.enqueue_request(&ask(Some(false), strings(&["R2"]), None)).await.expect("the R2 fallback");
        sup.enqueue_request(&ask(Some(false), None, strings(&["digits"]))).await.expect("the released fallback");
        let both = JobRequest { max_groups: Some(500), ..ask(Some(false), strings(&["R2", "R0n", "R2"]), strings(&["unfit", "digits"])) };
        sup.enqueue_request(&both).await.expect("both, capped");
        let queued = sup.queued();
        assert_eq!(queued[0].params, "refresh-org-names wet exclude_rules=R2");
        assert_eq!(queued[1].params, "refresh-org-names wet exclude_released=digits");
        assert_eq!(queued[2].params, "refresh-org-names wet max_groups=500 exclude_rules=R0n,R2 exclude_released=digits,unfit");
        let queue = sup.queue.lock().expect("queue lock");
        assert!(matches!(
            &queue[2].spec,
            Spec::RefreshOrgNamesWet { max_groups: Some(500), exclude_rules, exclude_released, .. }
                if exclude_rules == &vec!["R0n".to_owned(), "R2".to_owned()]
                    && exclude_released == &vec!["digits".to_owned(), "unfit".to_owned()]
        ));
    }

    /// Issue 524 rule v11's `exclude_stale_top` at enqueue: a wet run takes it (`true` on, `false` or
    /// omitted off), records it on the params line and in the queued spec; a dry plan and the revert
    /// refuse it whatever its value.
    #[tokio::test]
    async fn refresh_org_names_takes_exclude_stale_top_on_a_wet_run_only() {
        let sup = Supervisor::new(scratch().await, "archive".into(), reqwest::Client::new());
        let ask = |dry_run: Option<bool>, stale: Option<bool>| JobRequest {
            kind: "refresh-org-names".into(),
            dry_run,
            exclude_stale_top: stale,
            ..Default::default()
        };
        for dry_run in [None, Some(true)] {
            for stale in [Some(true), Some(false)] {
                let err = sup.enqueue_request(&ask(dry_run, stale)).await.expect_err("a dry plan");
                assert!(err.contains("`exclude_stale_top`") && err.contains("dry plan"), "{err}");
            }
        }
        let revert = JobRequest {
            kind: "revert-org-name-refresh".into(),
            job: Some(2601),
            exclude_stale_top: Some(true),
            ..Default::default()
        };
        let err = sup.enqueue_request(&revert).await.expect_err("the revert restores the whole job");
        assert!(err.contains("`exclude_stale_top`") && err.contains("no per-org or capped revert"), "{err}");
        assert!(sup.queued().is_empty(), "the refused asks queued nothing");
        // The v11 protocol's fallback run, and the same with it off.
        let fallback = JobRequest {
            exclude_rules: Some(vec!["R2".to_owned()]),
            exclude_released: Some(vec!["unfit".to_owned()]),
            ..ask(Some(false), Some(true))
        };
        sup.enqueue_request(&fallback).await.expect("the stale-top fallback");
        sup.enqueue_request(&ask(Some(false), Some(false))).await.expect("off");
        let queued = sup.queued();
        assert_eq!(
            queued[0].params,
            "refresh-org-names wet exclude_rules=R2 exclude_released=unfit exclude_stale_top=true"
        );
        assert_eq!(queued[1].params, "refresh-org-names wet");
        let queue = sup.queue.lock().expect("queue lock");
        assert!(matches!(&queue[0].spec, Spec::RefreshOrgNamesWet { exclude_stale_top: true, .. }));
        assert!(matches!(&queue[1].spec, Spec::RefreshOrgNamesWet { exclude_stale_top: false, .. }));
        // A job queued before rule v11 deserialises with the filter off.
        let old: Spec = serde_json::from_str(
            r#"{"RefreshOrgNamesWet":{"org_ids":null,"max_groups":null,"exclude_rules":["R2"],"exclude_released":[]}}"#,
        )
        .expect("a v10 spec");
        assert!(matches!(old, Spec::RefreshOrgNamesWet { exclude_stale_top: false, .. }));
    }

    /// Issue 524 rule v11: `exclude_stale_top` drops, before the pre-pass, the planned R1 changes with
    /// no junk release whose stored `top_newest` is missing or older than the plan's `as_of` less 365
    /// days — read last, after the rule and release filters — and leaves the same targets alone when off;
    /// the job line and the report record it.
    #[test]
    fn exclude_stale_top_drops_a_stale_no_rival_target_and_leaves_it_alone_when_off() {
        let entry = |id: i64, rule: &str, released: Option<&str>, top: Option<&str>| {
            serde_json::json!({
                "org_id": id, "verdict": "change", "rule": rule, "old_name": "Old", "old_name_norm": "old",
                "new_name": "New", "recent_released": released, "top_newest": top,
            })
        };
        // `as_of` 2026-10-16 11:20:05 UTC (plan 2543's): the cutoff is 2025-10-16 11:20:05.
        let plan = serde_json::json!({
            "epoch": store::HEAD_ELECTION_EPOCH, "rev": crate::v1::rev(), "stopped": false, "truncated": false,
            "scope_ids": null, "by_hold": {}, "listing_cap": 100_000, "as_of": 1_792_132_805,
            "planned": [
                entry(20, "R1", None, Some("2020-10-26")),          // 2857103's shape: stale, no rival — dropped
                entry(21, "R1", None, Some("2026-09-22")),          // fresh — kept
                entry(22, "R1", Some("digits"), Some("2022-10-12")), // a release — kept (3042's shape)
                entry(23, "R2", None, Some("2018-01-01")),          // R2 — kept (excluded by rule, if asked)
                entry(24, "R1", None, None),                        // undated — dropped (fails closed)
                entry(25, "R1", None, Some("2025-10-16")),          // the cutoff's own day — dropped
                entry(26, "R1", None, Some("2025-10-17")),          // a day inside the year — kept
            ],
        })
        .to_string();
        let ids = |p: &RefreshPlanTargets| p.targets.iter().map(|t| t.org_id).collect::<Vec<_>>();
        let off = org_name_refresh_targets(&plan, 7, None, &[], &[], false).expect("off");
        assert_eq!((ids(&off), off.excluded_by_stale_top, off.excluded_ids.clone()), (vec![20, 21, 22, 23, 24, 25, 26], 0, vec![]));
        let on = org_name_refresh_targets(&plan, 7, None, &[], &[], true).expect("on");
        assert_eq!((ids(&on), on.excluded_by_stale_top, on.excluded_ids.clone()), (vec![21, 22, 23, 26], 3, vec![20, 24, 25]));
        // With the v11 protocol's standing filters: R2 by rule first, the stale ones by top.
        let r2 = vec!["R2".to_owned()];
        let unfit = vec!["unfit".to_owned()];
        let all = org_name_refresh_targets(&plan, 7, None, &r2, &unfit, true).expect("all three");
        assert_eq!((ids(&all), all.excluded_by_rule, all.excluded_by_release, all.excluded_by_stale_top), (vec![21, 22, 26], 1, 0, 3));
        // Scoped: an asked id the filter drops is planned, not `unplanned`.
        let scoped = org_name_refresh_targets(&plan, 7, Some(&[20, 21, 99]), &[], &[], true).expect("scoped");
        assert_eq!((ids(&scoped), scoped.excluded_ids.clone(), scoped.unplanned.clone()), (vec![21], vec![20], vec![99]));
        // The job line and the report.
        let r = store::OrgNameRefreshApplied { targets: 3, ready: 3, applied: 3, windows: 1, ..Default::default() };
        let line = org_name_refresh_applied_summary(&r, 9, &all, None);
        assert!(
            line.contains(
                "Filters (rule v9, v11): exclude_rules=R2 exclude_released=unfit exclude_stale_top=true — 4 planned \
                 change(s) in scope dropped before the pre-pass (1 by rule, 0 by junk release, 3 by stale top)."
            ),
            "{line}"
        );
        let stale_only = org_name_refresh_applied_summary(&r, 9, &on, None);
        assert!(stale_only.contains("Filters (rule v9, v11): exclude_stale_top=true — 3 planned"), "{stale_only}");
        assert!(!org_name_refresh_applied_summary(&r, 9, &off, None).contains("Filters"), "off, no clause");
        let body: serde_json::Value = serde_json::from_str(&org_name_refresh_applied_json(&r, 9, &all, None).unwrap()).unwrap();
        assert_eq!((body["exclude_stale_top"].as_bool(), body["excluded_by_stale_top"].as_u64()), (Some(true), Some(3)));
        assert_eq!(body["excluded_ids"], serde_json::json!([20, 23, 24, 25]));
        let body: serde_json::Value = serde_json::from_str(&org_name_refresh_applied_json(&r, 9, &off, None).unwrap()).unwrap();
        assert_eq!((body["exclude_stale_top"].as_bool(), body["excluded_by_stale_top"].as_u64()), (Some(false), Some(0)));
    }

    /// Issue 524 rule v9: the filters drop their classes off the stored plan's targets before the
    /// pre-pass — by rule first, then by junk release — counting each and listing the ids; an asked id
    /// they drop is planned, not `unplanned`; no filter takes every planned change, as before.
    #[test]
    fn the_wet_filters_drop_their_classes_before_the_pre_pass() {
        let entry = |id: i64, rule: &str, released: Option<&str>| {
            serde_json::json!({
                "org_id": id, "verdict": "change", "rule": rule, "old_name": "Old", "old_name_norm": "old",
                "new_name": "New", "recent_released": released,
            })
        };
        let plan = serde_json::json!({
            "epoch": store::HEAD_ELECTION_EPOCH, "rev": crate::v1::rev(), "stopped": false, "truncated": false,
            "scope_ids": null, "by_hold": {}, "listing_cap": 100_000, "as_of": 1_792_108_800,
            "planned": [
                entry(10, "R1", None), entry(11, "R2", None), entry(12, "R1", Some("digits")),
                entry(13, "R2", Some("digits")), entry(14, "R1", Some("unfit")), entry(15, "R0n", None),
            ],
        })
        .to_string();
        let owned = |v: &[&str]| v.iter().map(|s| (*s).to_owned()).collect::<Vec<_>>();
        let ids = |p: &RefreshPlanTargets| p.targets.iter().map(|t| t.org_id).collect::<Vec<_>>();
        let all = org_name_refresh_targets(&plan, 7, None, &[], &[], false).expect("no filter");
        assert_eq!((ids(&all), all.excluded_by_rule, all.excluded_by_release, all.excluded_ids.clone()), (vec![10, 11, 12, 13, 14, 15], 0, 0, vec![]));
        // Rule v10: the plan's own `as_of`, not when it was stored.
        assert_eq!((all.as_of, all.computed_at), (1_792_108_800, 7));
        let r2 = org_name_refresh_targets(&plan, 7, None, &owned(&["R2"]), &[], false).expect("the R2 fallback");
        assert_eq!((ids(&r2), r2.excluded_by_rule, r2.excluded_ids.clone()), (vec![10, 12, 14, 15], 2, vec![11, 13]));
        let digits = org_name_refresh_targets(&plan, 7, None, &[], &owned(&["digits"]), false).expect("the released fallback");
        assert_eq!((ids(&digits), digits.excluded_by_release, digits.excluded_ids.clone()), (vec![10, 11, 14, 15], 2, vec![12, 13]));
        // Both: 13 is an R2 AND released by digits — counted once, by its rule.
        let both = org_name_refresh_targets(&plan, 7, None, &owned(&["R2"]), &owned(&["digits", "unfit"]), false).expect("both");
        assert_eq!((ids(&both), both.excluded_by_rule, both.excluded_by_release), (vec![10, 15], 2, 2));
        assert_eq!((both.exclude_rules.clone(), both.exclude_released.clone()), (owned(&["R2"]), owned(&["digits", "unfit"])));
        // Scoped: an asked id the filter drops is not `unplanned`; an id the plan lacks still is.
        let scoped = org_name_refresh_targets(&plan, 7, Some(&[11, 10, 99]), &owned(&["R2"]), &[], false).expect("scoped");
        assert_eq!((ids(&scoped), scoped.excluded_ids.clone(), scoped.unplanned.clone()), (vec![10], vec![11], vec![99]));
        // The applied report and the job line record them.
        let r = store::OrgNameRefreshApplied { targets: 2, ready: 2, applied: 2, windows: 1, ..Default::default() };
        let line = org_name_refresh_applied_summary(&r, 9, &both, None);
        assert!(
            line.contains(
                "Filters (rule v9): exclude_rules=R2 exclude_released=digits,unfit — 4 planned change(s) in scope \
                 dropped before the pre-pass (2 by rule, 2 by junk release)."
            ),
            "{line}"
        );
        assert!(!org_name_refresh_applied_summary(&r, 9, &all, None).contains("Filters"), "no filter, no clause");
        let body: serde_json::Value = serde_json::from_str(&org_name_refresh_applied_json(&r, 9, &both, None).unwrap()).unwrap();
        assert_eq!(body["exclude_rules"], serde_json::json!(["R2"]));
        assert_eq!(body["exclude_released"], serde_json::json!(["digits", "unfit"]));
        assert_eq!((body["excluded_by_rule"].as_u64(), body["excluded_by_release"].as_u64()), (Some(2), Some(2)));
        assert_eq!(body["excluded_ids"], serde_json::json!([11, 12, 13, 14]));
    }

    /// Issue 524 rule v9, end to end: a wet run with `exclude_rules: ["R2"]` renames the plan's R1
    /// change and leaves its R2 change as it was (never read by the pre-pass), the report and the line
    /// saying so; one with `exclude_released: ["digits"]` drops a released change; a later unfiltered
    /// run takes the rest.
    #[tokio::test]
    async fn a_filtered_wet_run_leaves_the_excluded_class_unrenamed() {
        let path = format!("/tmp/tender-db-sup-refresh-filters-{}-{}.db", std::process::id(), store::now_unix());
        remove_db(&path);
        let db = Arc::new(store::Db::open(&path).await.unwrap());
        db.build_organization_indexes().await.unwrap();
        let conn = store::turso::Builder::new_local(&path).build().await.unwrap().connect().unwrap();
        conn.execute("PRAGMA foreign_keys = OFF", ()).await.unwrap();
        use store::turso::Value;
        let orgs: &[(i64, &str, &[(&str, usize)])] = &[
            (701, "Sheffield Hallam University", &[("University of Sheffield", 5), ("Sheffield Hallam University", 1)]),
            (702, "Stray Body", &[
                ("Main Body", 3),
                ("Nord Body", 2),
                ("Sued Body", 2),
                ("Ost Body", 2),
                ("West Body", 2),
                ("Stray Body", 1),
            ]),
        ];
        let mut notice = 0i64;
        for (id, head, mentions) in orgs {
            conn.execute(
                "INSERT INTO organizations
                   (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
                 VALUES (?, 'DE', 'national', ?, ?, ?, 0, 0)",
                vec![Value::Integer(*id), Value::Text(format!("DE{id}")), Value::Text((*head).into()), Value::Text(store::org_name_norm(head))],
            )
            .await
            .unwrap();
            for (name, n) in mentions.iter() {
                for _ in 0..*n {
                    notice += 1;
                    conn.execute(
                        "INSERT INTO organization_mentions
                           (notice_id, section_id, organization_id, name, country, raw_identifier, scheme)
                         VALUES (?, 'ORG-0001', ?, ?, 'DE', NULL, NULL)",
                        vec![Value::Integer(notice), Value::Integer(*id), Value::Text((*name).into())],
                    )
                    .await
                    .unwrap();
                }
            }
        }
        let head_of = |id: i64| {
            let conn = &conn;
            async move {
                let mut rows = conn.query("SELECT name FROM organizations WHERE id = ?", (Value::Integer(id),)).await.unwrap();
                rows.next().await.unwrap().unwrap().get_value(0).unwrap()
            }
        };
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        sup.run_spec(&job(Spec::RefreshOrgNames { dry_run: true, min_mentions: 2, samples: 30, org_ids: None }))
            .await
            .expect("the dry plan");
        let (genuine, at) = db.latest_report("org-name-refresh-plan").await.unwrap().unwrap();
        let plan: serde_json::Value = serde_json::from_str(&genuine).unwrap();
        let planned: Vec<(i64, &str)> =
            plan["planned"].as_array().unwrap().iter().map(|e| (e["org_id"].as_i64().unwrap(), e["rule"].as_str().unwrap())).collect();
        assert_eq!(planned, vec![(701, "R1"), (702, "R2")]);
        let wet_stale = |id: u64, exclude_rules: &[&str], exclude_released: &[&str], exclude_stale_top: bool| Job {
            id,
            kind: "refresh-org-names".into(),
            ..job(Spec::RefreshOrgNamesWet {
                org_ids: None,
                max_groups: None,
                exclude_rules: exclude_rules.iter().map(|s| (*s).to_owned()).collect(),
                exclude_released: exclude_released.iter().map(|s| (*s).to_owned()).collect(),
                exclude_stale_top,
            })
        };
        let wet = |id: u64, exclude_rules: &[&str], exclude_released: &[&str]| wet_stale(id, exclude_rules, exclude_released, false);
        // 701 marked as a digits release in a copy of the plan: both filters together drop both.
        let mut marked = plan.clone();
        marked["planned"][0]["recent_released"] = serde_json::json!("digits");
        db.put_report("org-name-refresh-plan", &marked.to_string(), at).await.unwrap();
        let msg = sup.run_spec(&wet(2, &["R2"], &["digits"])).await.expect("everything filtered");
        for needle in [
            "0 of the plan's 2 planned change(s) in scope.",
            "Filters (rule v9): exclude_rules=R2 exclude_released=digits — 2 planned change(s) in scope dropped before the pre-pass (1 by rule, 1 by junk release).",
            "Pre-pass: 0 ready",
            "RENAMED 0 head(s)",
        ] {
            assert!(msg.contains(needle), "missing {needle:?} in: {msg}");
        }
        assert_eq!((head_of(701).await, head_of(702).await), (Value::Text("Sheffield Hallam University".into()), Value::Text("Stray Body".into())));
        // Rule v11: the genuine plan, with `exclude_stale_top` beside the R2 filter. Nothing here is dated,
        // so 701's stored `top_newest` is null: an undated top fails closed as stale, and 701 is dropped too.
        db.put_report("org-name-refresh-plan", &genuine, at).await.unwrap();
        assert!(plan["planned"][0]["top_newest"].is_null(), "{}", plan["planned"][0]);
        let msg = sup.run_spec(&wet_stale(5, &["R2"], &[], true)).await.expect("stale top and R2 filtered");
        for needle in [
            "refresh-org-names WET (issue 524 unit 2b, rule 524u2-v13, job 5): 0 of the plan's 2 planned change(s) in scope.",
            "Filters (rule v9, v11): exclude_rules=R2 exclude_stale_top=true — 2 planned change(s) in scope dropped before the pre-pass (1 by rule, 0 by junk release, 1 by stale top).",
            "RENAMED 0 head(s)",
        ] {
            assert!(msg.contains(needle), "missing {needle:?} in: {msg}");
        }
        let (body, _) = db.latest_report("org-name-refresh-applied").await.unwrap().unwrap();
        let applied: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((applied["exclude_stale_top"].as_bool(), applied["excluded_by_stale_top"].as_u64()), (Some(true), Some(1)));
        assert_eq!((head_of(701).await, head_of(702).await), (Value::Text("Sheffield Hallam University".into()), Value::Text("Stray Body".into())));
        // Rule v10: the wet pre-pass re-elects with the STORED plan's `as_of` — not the clock, a constant
        // or `computed_at` — so a distinctive past instant written into the plan (2015-06-01) comes back
        // in the ledger's evidence. Nothing here is dated, so it moves no election.
        let mut dated = serde_json::from_str::<serde_json::Value>(&genuine).unwrap();
        dated["as_of"] = serde_json::json!(1_433_116_800);
        db.put_report("org-name-refresh-plan", &dated.to_string(), at).await.unwrap();
        // The R2 fallback: the R1 change is renamed, the R2 one never read.
        let msg = sup.run_spec(&wet(3, &["R2"], &[])).await.expect("R2 excluded");
        assert!(msg.contains("RENAMED 1 head(s)") && msg.contains("1 ready") && msg.contains("(1 by rule, 0 by junk release)"), "{msg}");
        assert_eq!(head_of(701).await, Value::Text("University of Sheffield".into()));
        let Some(Value::Text(evidence)) = db.scalar("SELECT evidence FROM org_name_refresh_log WHERE job_id = 3").await.unwrap()
        else {
            panic!("job 3 wrote no ledger evidence");
        };
        let evidence: serde_json::Value = serde_json::from_str(&evidence).unwrap();
        assert_eq!(evidence["as_of"], "2015-06-01", "the stored plan's as_of reaches the pre-pass: {evidence}");
        assert_eq!(head_of(702).await, Value::Text("Stray Body".into()), "the excluded class is left as it was");
        let (body, _) = db.latest_report("org-name-refresh-applied").await.unwrap().unwrap();
        let applied: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((applied["job"].as_u64(), applied["targets"].as_u64(), applied["applied"].as_u64()), (Some(3), Some(1), Some(1)));
        assert_eq!((applied["exclude_rules"].clone(), applied["excluded_ids"].clone()), (serde_json::json!(["R2"]), serde_json::json!([702])));
        // Unfiltered, the rest: 701 reads already renamed, 702 is renamed.
        let msg = sup.run_spec(&wet(4, &[], &[])).await.expect("the rest");
        assert!(msg.contains("RENAMED 1 head(s)") && msg.contains("1 already renamed") && !msg.contains("Filters"), "{msg}");
        assert_eq!(head_of(702).await, Value::Text("Main Body".into()));
        remove_db(&path);
    }

    /// Issue 524 rule v7's follow-up check: a wet run a cancel stopped during its pre-pass says how
    /// far the pre-pass read and that this run wrote nothing — never a pre-pass of zeros, a `limit 0`,
    /// or "the committed windows stand" — and names the earlier renames of a recovered job.
    #[test]
    fn a_pre_pass_stop_is_reported_as_one() {
        let plan = RefreshPlanTargets { planned: 600, ..Default::default() };
        let fresh = store::OrgNameRefreshApplied {
            targets: 600,
            stopped: true,
            prepass_stopped_after: Some(512),
            drift_limit: store::org_name_refresh_drift_limit(600),
            ..Default::default()
        };
        let line = org_name_refresh_applied_summary(&fresh, 7, &plan, None);
        assert!(
            line.contains("STOPPED by cancel during the pre-pass after 512 of 600 target(s); nothing written by this run; no rename by this job"),
            "{line}"
        );
        for absent in ["Pre-pass:", "limit", "RENAMED", "committed windows stand"] {
            assert!(!line.contains(absent), "{absent:?} in: {line}");
        }
        let recovered = store::OrgNameRefreshApplied { prior_applied: 3, ..fresh };
        let line = org_name_refresh_applied_summary(&recovered, 7, &plan, None);
        assert!(line.contains(r#"earlier windows made 3 rename(s), which stand unless reverted: undo them with {"kind":"revert-org-name-refresh","job":7}"#), "{line}");
    }

    /// The v8 review: a plan lists up to 500 released ids for the re-judge; its job line names the
    /// first 30 and counts the rest.
    #[test]
    fn the_plan_line_names_30_released_ids_and_counts_the_rest() {
        let plan = store::OrgNameRefreshPlan { recent_released_ids: (1..=35).collect(), ..Default::default() };
        let line = org_name_refresh_summary(&plan, None);
        let shown: Vec<i64> = (1..=30).collect();
        assert!(line.contains(&format!("(ids {shown:?} and 5 more in `recent_released_ids`)")), "{line}");
        let few = store::OrgNameRefreshPlan { recent_released_ids: vec![7, 9], ..Default::default() };
        assert!(org_name_refresh_summary(&few, None).contains("(ids [7, 9]);"));
    }

    /// Issue 524 unit 2a, end to end with the REAL ingest functions (`head_vote_key`, `not_a_name`,
    /// `head_spelling_unfit`, `head_change_hold`): the decision's canary shapes, seeded under their prod
    /// ids, plan as the decision expects; an expected canary the walk does not find is UNEXPECTED, and a
    /// scoped plan reads the canaries it did not ask for as outside its scope; the plan is stored as
    /// `org-name-refresh-plan`; nothing is written to `organizations` or `changes`; and the arm itself
    /// refuses a wet spec.
    #[tokio::test]
    async fn refresh_org_names_plans_the_canary_shapes_and_writes_nothing() {
        let path = format!("/tmp/tender-db-sup-refresh-names-{}-{}.db", std::process::id(), store::now_unix());
        remove_db(&path);
        let db = Arc::new(store::Db::open(&path).await.unwrap());
        db.build_organization_indexes().await.unwrap();
        let conn = store::turso::Builder::new_local(&path).build().await.unwrap().connect().unwrap();
        conn.execute("PRAGMA foreign_keys = OFF", ()).await.unwrap();
        let sheffield: &[(&str, usize)] = &[
            ("UNIVERSITY OF SHEFFIELD", 14),
            ("University of Sheffield", 1),
            ("The University of Sheffield", 1),
            ("Sheffield Hallam University", 1),
        ];
        let hallam: &[(&str, usize)] = &[("University of Sheffield", 4), ("Sheffield Hallam University", 1)];
        let belovo: &[(&str, usize)] = &[("ОБЩИНА БЕЛОВО", 5), ("Obshtina Belovo", 1)];
        let alchimistes: &[(&str, usize)] = &[
            ("les alchimistes", 2),
            ("LES ALCHIMISTES", 2),
            ("Les Alchimistes SAS", 1),
            ("Les Alchimistes Loire Atlantique", 1),
        ];
        let orgs: &[(i64, &str, Option<&str>, &str, &[(&str, usize)])] = &[
            (334, "FR", Some("FR33400000000"), "Les Alchimistes Loire Atlantique", alchimistes),
            // Not a canary: 334's shape left undated, so it changes (the wet half renames it last).
            (335, "FR", Some("FR33500000000"), "Les Alchimistes Loire Atlantique", alchimistes),
            // Not a canary: the winning cluster spells only lower case, so the change is held.
            (500, "FR", Some("FR50000000000"), "Atelier Nord", &[("les alchimistes", 3), ("Atelier Nord", 1)]),
            (1_165_973, "GB", None, "Sheffield Hallam University", hallam),
            (6_341_366, "SE", Some("2120000829"), "", &[("Kalmar kommun", 4)]),
            (7_912_592, "BG", Some("000215853"), "Obshtina Belovo", belovo),
            (22_713_056, "DE", Some("0251411691"), "s.o.", &[("Vergabekammer bei der Bezirksregierung", 28)]),
            (31_558_903, "GB", Some("GBUKPRN10007157"), "Sheffield Hallam University", sheffield),
        ];
        use store::turso::Value;
        let mut notice = 0i64;
        for (id, country, identifier, head, mentions) in orgs {
            let params: Vec<Value> = vec![
                Value::Integer(*id),
                Value::Text((*country).into()),
                identifier.map_or(Value::Null, |_| Value::Text("national".into())),
                identifier.map_or(Value::Null, |i| Value::Text(i.into())),
                Value::Text((*head).into()),
                Value::Text(store::org_name_norm(head)),
                Value::Integer(i64::from(identifier.is_none())),
            ];
            conn.execute(
                "INSERT INTO organizations
                   (id, country, identifier_kind, identifier, name, name_norm, provisional, created_at)
                 VALUES (?, ?, ?, ?, ?, ?, ?, 0)",
                params,
            )
            .await
            .unwrap();
            for (name, n) in mentions.iter() {
                for _ in 0..*n {
                    notice += 1;
                    let params: Vec<Value> = vec![
                        Value::Integer(notice),
                        Value::Integer(*id),
                        Value::Text((*name).into()),
                        Value::Text((*country).into()),
                    ];
                    conn.execute(
                        "INSERT INTO organization_mentions
                           (notice_id, section_id, organization_id, name, country, raw_identifier, scheme)
                         VALUES (?, 'ORG-0001', ?, ?, ?, NULL, NULL)",
                        params,
                    )
                    .await
                    .unwrap();
                }
            }
        }
        conn.execute(
            "INSERT INTO organization_names (org_id, lang, name, name_norm)
             VALUES (7912592, 'ENG', 'Obshtina Belovo', 'obshtina belovo')",
            (),
        )
        .await
        .unwrap();
        // The v8 review: 334 dated as prod dates it — its head's one mention (tender 56385, 2026-07-17)
        // is the organization's newest item, the elected cluster's newest 542462 (2026-04-01).
        let mut rows = conn
            .query("SELECT notice_id, name FROM organization_mentions WHERE organization_id = 334 ORDER BY notice_id", ())
            .await
            .unwrap();
        let mut dated_334 = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            let notice = *row.get_value(0).unwrap().as_integer().unwrap();
            let name = row.get_value(1).unwrap().as_text().unwrap().clone();
            dated_334.push((notice, name));
        }
        drop(rows);
        let (mut lower, mut caps) = (vec![(7_221_314, 1_622_505_600), (7_424_584, 1_646_092_800)], vec![
            (749_220, 1_745_280_000),
            (542_462, 1_775_001_600),
        ]);
        for (notice, name) in &dated_334 {
            let (tender, at) = match name.as_str() {
                "les alchimistes" => lower.remove(0),
                "LES ALCHIMISTES" => caps.remove(0),
                "Les Alchimistes SAS" => (335_385, 1_714_694_400),
                _ => (56_385, 1_784_246_400),
            };
            conn.execute(
                "INSERT INTO tender_versions (tender_id, seq, caused_by_notice_id, published_at, publication_id)
                 VALUES (?, 1, ?, ?, 'x')",
                vec![Value::Integer(tender), Value::Integer(*notice), Value::Integer(at)],
            )
            .await
            .unwrap();
        }
        assert_eq!(dated_334.len(), 6);
        // One feed row already there, so "no change row written" is a count that must not move.
        conn.execute(
            "INSERT INTO changes (entity_kind, entity_id, version_seq, op, changed_at)
             VALUES ('organization', 334, NULL, 'added', 0)",
            (),
        )
        .await
        .unwrap();
        let heads = || {
            let conn = &conn;
            async move {
                let mut rows = conn.query("SELECT id, name, name_norm FROM organizations ORDER BY id", ()).await.unwrap();
                let mut all = Vec::new();
                while let Some(row) = rows.next().await.unwrap() {
                    all.push((row.get_value(0).unwrap(), row.get_value(1).unwrap(), row.get_value(2).unwrap()));
                }
                all
            }
        };
        // The 2b review: a NULL `name_norm` is a pre-image too. The plan lists it as null, the wet run's
        // parser takes it, and the revert below puts the NULL back.
        conn.execute("UPDATE organizations SET name_norm = NULL WHERE id = 6341366", ()).await.unwrap();
        let before = heads().await;
        assert_eq!(before.len(), orgs.len());
        let sup = Supervisor::new(db.clone(), "archive".into(), reqwest::Client::new());
        let dry = |dry_run: bool| job(Spec::RefreshOrgNames { dry_run, min_mentions: 2, samples: 30, org_ids: None });
        // Issue 524 unit 2b: a wet job with a distinct id (the ledger's `job_id`, the revert's handle).
        let wet = |id: u64, org_ids: Option<Vec<i64>>| Job {
            id,
            kind: "refresh-org-names".into(),
            ..job(Spec::RefreshOrgNamesWet {
                org_ids,
                max_groups: None,
                exclude_rules: vec![],
                exclude_released: vec![],
                exclude_stale_top: false,
            })
        };
        let err = sup.run_spec(&wet(2, None)).await.expect_err("no plan is stored yet");
        assert!(err.contains("REFUSED") && err.contains("no org-name-refresh-plan is stored"), "{err}");
        let msg = sup.run_spec(&dry(true)).await.expect("the dry plan");
        for reading in [
            // Seeded as they were BEFORE 2516 renamed them: rule v7 expects the live keep:S1, so the
            // pre-rename shapes read UNEXPECTED (after the wet run below they read as expected).
            r#"31558903 change:R1 "The University of Sheffield" UNEXPECTED (want keep:S1)"#,
            r#"22713056 change:R0n "Vergabekammer bei der Bezirksregierung" UNEXPECTED (want keep:S1)"#,
            r#"6341366 change:R0e "Kalmar kommun" UNEXPECTED (want keep:S1)"#,
            "7912592 keep:D4 as expected",
            // The v8 review: dated, 334's head is its newest item — held `residue`.
            r#"334 hold:residue "Les Alchimistes SAS" as expected"#,
            "1165973 keep:E1 as expected",
            // Not seeded: an expected canary the walk does not find is no pass.
            "760 not found UNEXPECTED (want keep:S1)",
            "178 not found UNEXPECTED (want hold:recent)",
            r#"445 not found UNEXPECTED (want hold:residue "KADEA Berlin GmbH")"#,
            r#"3740262 not found UNEXPECTED (want hold:residue "Junta de Gobierno del Ayuntamiento de Fuengirola")"#,
            "10 not found UNEXPECTED (want keep:S1)",
            "30914328 not found (reported)",
            // Rule v9's nine canaries are not seeded here either.
            r#"22028982 not found UNEXPECTED (want hold:review_body "Vergabekammer BW")"#,
            // Rule v12: 3042 and 1800186, renamed by job 2567, are keep:S1 (no spelling).
            "3042 not found UNEXPECTED (want keep:S1)",
            // Rule v10: seven re-pointed to `hold:head_current`; v10's six change:R1 canaries, applied by
            // job 2554, are keep:S1 since rule v11 (no spelling).
            r#"1220 not found UNEXPECTED (want hold:head_current "Miasto Bielsko-Biała Urząd Miejski w Bielsku-Białej")"#,
            "4220276 not found UNEXPECTED (want keep:S1)",
            // Rule v11's nine are not seeded here either.
            r#"1556789 not found UNEXPECTED (want hold:top_stale "Instituto Navarro de Deporte y Juventud")"#,
            r#"22831984 not found UNEXPECTED (want hold:placeholder_id "AOK PLUS - Die Gesundheitskasse für Sachsen und Thüringen")"#,
            // Rule v12: job 2565's eight renames are keep:S1 (no spelling), the six fresh tops new rows.
            "2857103 not found UNEXPECTED (want keep:S1)",
            "8765882 not found UNEXPECTED (want keep:S1)",
            "1800186 not found UNEXPECTED (want keep:S1)",
            "(56 unexpected)",
            // Rule v12's two counts, named at zero.
            "Rule v12: control-only unfit releases the lines guard withheld (release_withheld lines, held): 0; R0w wrap \
             collapses (the head's own words, its line breaks collapsed): 0 (0 mentions).",
            // Rule v7's and v8's counters: 334 is the one residue hold.
            "R1's recent hold: 0; R1/R2's residue hold: 1; undated 0 (MUST be 0)",
            "residue that still ships (planned changes whose org's newest procedure is the head's: R0, or released): none.",
            "NOTHING IS WRITTEN",
        ] {
            assert!(msg.contains(reading), "missing {reading:?} in: {msg}");
        }
        let (body, _) = db.latest_report("org-name-refresh-plan").await.unwrap().expect("the plan is stored");
        let plan: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(plan["dry_run"], true);
        assert_eq!(plan["epoch"], store::HEAD_ELECTION_EPOCH);
        // Rule v10: the planner's start, stored for the wet pre-pass, and its date on the job line.
        let as_of = plan["as_of"].as_i64().expect("rule v10: the plan carries as_of");
        assert!(as_of > 0 && as_of <= store::now_unix(), "{as_of}");
        assert_eq!(plan["as_of_date"], store::rates::civil_date(as_of));
        assert!(
            msg.contains(&format!("Rule v10: R1's head_current hold (a head printed within 1095 days of as_of {}): 0.", store::rates::civil_date(as_of))),
            "{msg}"
        );
        assert_eq!(plan["fns"]["twin_key"], "ingest::crosswalk::head_twin_key");
        assert_eq!(plan["fns"]["tail_family"], "ingest::crosswalk::head_tail_family", "rule v12");
        assert_eq!(plan["fns"]["r2_hold"], "ingest::crosswalk::head_r2_hold");
        assert_eq!(plan["fns"]["serve_hold"], "ingest::crosswalk::head_serve_hold", "rule v9");
        // Rule v9's counters, named at zero: no serve hold fires on these shapes, no release withheld.
        // Rule v11's two serve holds join the list.
        assert!(
            msg.contains(
                "Rule v9: R1/R2 serve holds: review_body 0, organ 0, code_added 0, address_added 0, caps_variant 0, \
                 doubled 0, seat_dropped 0; releases withheld (digits, rule v9: glue, junk_only; control-only \
                 unfit, rule v12: lines; held under their recent, residue or head_current hold, \
                 release_withheld): none (ids [])."
            ),
            "{msg}"
        );
        // Rule v11's stale-top hold and placeholder guard, named at zero, with the plan's `as_of`.
        assert!(
            msg.contains(&format!(
                "Rule v11: R1's top_stale hold (a rival cluster, and the elected spelling's newest dated item more \
                 than 365 days before as_of {}, or undated): 0; the placeholder_id bind guard: 0.",
                store::rates::civil_date(as_of)
            )),
            "{msg}"
        );
        assert_eq!(plan["release_withheld_ids"], serde_json::json!([]));
        assert!(msg.contains("(R2's initialism hold: 0)"), "the summary names the R2 hold even at zero: {msg}");
        let planned: Vec<i64> = plan["planned"].as_array().unwrap().iter().map(|e| e["org_id"].as_i64().unwrap()).collect();
        assert_eq!(planned, vec![335, 6_341_366, 22_713_056, 31_558_903], "by org id");
        assert_eq!(plan["planned"][3]["old_name_norm"], "sheffield hallam university");
        assert_eq!(plan["planned"][3]["new_name_norm"], "the university of sheffield");
        assert!(plan["planned"][1]["old_name_norm"].is_null(), "6341366's NULL key: {}", plan["planned"][1]);
        assert_eq!((&plan["held"][0]["org_id"], &plan["held"][0]["reason"]), (&serde_json::json!(334), &serde_json::json!("residue")));
        assert_eq!(plan["held"][0]["newest_is_head"], true);
        assert_eq!(plan["by_hold"]["residue"]["orgs"], 1);
        assert_eq!(plan["held"][1]["org_id"], 500);
        assert_eq!(plan["held"][1]["reason"], "no_fit");
        assert_eq!(plan["d4_eng"]["equal"], 1, "TED's ENG rendering is the head the guard keeps");
        assert_eq!(plan["canary_readings"].as_array().unwrap().len(), ORG_NAME_REFRESH_CANARIES.len());
        assert_eq!(heads().await, before, "dry: no organization's (name, name_norm) moved");
        assert_eq!(db.scalar("SELECT COUNT(*) FROM changes").await.unwrap(), Some(Value::Integer(1)), "no change row");

        // Scoped: the canaries it did not ask for are outside its scope, not unexpected; an asked one
        // that is missing still is.
        let scoped = job(Spec::RefreshOrgNames {
            dry_run: true,
            min_mentions: 2,
            samples: 30,
            org_ids: Some(vec![760, 31_558_903]),
        });
        let msg = sup.run_spec(&scoped).await.expect("the scoped dry plan");
        for reading in [
            r#"31558903 change:R1 "The University of Sheffield" UNEXPECTED (want keep:S1)"#,
            "760 not found UNEXPECTED",
            "22713056 outside the scope",
            "30914328 outside the scope",
            "(2 unexpected)",
            "(scoped to 2 org id(s))",
        ] {
            assert!(msg.contains(reading), "missing {reading:?} in: {msg}");
        }
        assert_eq!(heads().await, before);
        assert_eq!(db.scalar("SELECT COUNT(*) FROM changes").await.unwrap(), Some(Value::Integer(1)));
        let err = sup.run_spec(&dry(false)).await.expect_err("the dry arm plans only");
        assert!(err.contains("REFUSED") && err.contains("RefreshOrgNamesWet"), "{err}");

        // Issue 524 unit 2b, the wet path. An unscoped wet run refuses the scoped plan just stored.
        let err = sup.run_spec(&wet(2, None)).await.expect_err("a scoped plan, unscoped");
        assert!(err.contains("scoped to 2 org id(s)") && err.contains("Nothing was written"), "{err}");
        // The whole plan again, then tampered copies of it: each refused, nothing written.
        sup.run_spec(&dry(true)).await.expect("the dry plan");
        let (genuine, at) = db.latest_report("org-name-refresh-plan").await.unwrap().unwrap();
        // Rule v10: a plan without an integer `as_of` (a v9 plan, or one that lost the field) is refused:
        // the pre-pass could not re-elect as the plan did.
        for as_of in [None, Some(serde_json::json!("2026-10-16")), Some(serde_json::Value::Null)] {
            let mut plan: serde_json::Value = serde_json::from_str(&genuine).unwrap();
            match &as_of {
                None => {
                    plan.as_object_mut().unwrap().remove("as_of");
                }
                Some(value) => plan["as_of"] = value.clone(),
            }
            db.put_report("org-name-refresh-plan", &plan.to_string(), at).await.unwrap();
            let err = sup.run_spec(&wet(2, None)).await.expect_err("no as_of");
            assert!(
                err.contains("REFUSED: the stored plan carries no as_of (rule v10); re-run the dry plan")
                    && err.ends_with("Nothing was written"),
                "{as_of:?}: {err}"
            );
        }
        for (field, value, needle) in [
            // Rule v10: a v9 plan is refused, and (rule v7) so is one that held anything `undated`.
            ("epoch", serde_json::json!("524u2-v9"), "rule epoch \"524u2-v9\""),
            (
                "by_hold",
                serde_json::json!({ "undated": { "orgs": 1, "mentions": 2 } }),
                "holds 1 organization(s) `undated`",
            ),
            ("rev", serde_json::json!("another-binary"), "binary \"another-binary\""),
            ("truncated", serde_json::json!(true), "truncated"),
        ] {
            let mut plan: serde_json::Value = serde_json::from_str(&genuine).unwrap();
            plan[field] = value;
            db.put_report("org-name-refresh-plan", &plan.to_string(), at).await.unwrap();
            let err = sup.run_spec(&wet(2, None)).await.expect_err(field);
            assert!(err.contains("REFUSED") && err.contains(needle), "{field}: {err}");
        }
        assert_eq!(heads().await, before, "a refused wet run writes nothing");
        assert_eq!(db.scalar("SELECT COUNT(*) FROM changes").await.unwrap(), Some(Value::Integer(1)));
        // Job 2 has no ledger row yet, so its refusal is the plain one, even with a resume cursor.
        let recovered = Job { resume_after: Some("1".into()), ..wet(2, None) };
        let err = sup.run_spec(&recovered).await.expect_err("still the truncated plan");
        assert!(err.contains("truncated") && err.ends_with("Nothing was written"), "{err}");

        // Past the drift limit: six planned changes for organizations that do not exist (gone) of ten
        // targets read, max(10/50, 5) = 5. The run aborts before any write — not even its 4 ready targets
        // — and is the job's error, with the applied report stored first.
        let mut stale: serde_json::Value = serde_json::from_str(&genuine).unwrap();
        for id in 90_000_001..=90_000_006_i64 {
            stale["planned"].as_array_mut().unwrap().push(serde_json::json!({
                "org_id": id, "verdict": "change", "rule": "R1",
                "old_name": "Gone Ltd", "old_name_norm": "gone ltd", "new_name": "Gone Limited",
            }));
        }
        db.put_report("org-name-refresh-plan", &stale.to_string(), at).await.unwrap();
        let err = sup.run_spec(&wet(9, None)).await.expect_err("drifted + gone past the limit is the job's error");
        for needle in ["ABORTED before any write", "4 ready", "0 drifted", "6 gone (limit 5)", "90000001 the organization is gone"] {
            assert!(err.contains(needle), "missing {needle:?} in: {err}");
        }
        assert_eq!(heads().await, before, "an aborted run writes nothing");
        assert_eq!(db.scalar("SELECT COUNT(*) FROM changes").await.unwrap(), Some(Value::Integer(1)));
        assert_eq!(db.scalar("SELECT COUNT(*) FROM org_name_refresh_log").await.unwrap(), Some(Value::Integer(0)));
        let (body, _) = db.latest_report("org-name-refresh-applied").await.unwrap().expect("an aborted run's report");
        let aborted: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(
            (aborted["job"].as_u64(), aborted["aborted"].as_bool(), aborted["applied"].as_u64(), aborted["gone"].as_u64()),
            (Some(9), Some(true), Some(0), Some(6))
        );
        db.put_report("org-name-refresh-plan", &genuine, at).await.unwrap();

        // The runbook's first wet run: the five positive canaries. Three are seeded and planned; 760
        // and 61 are not, and the summary names them.
        let canaries = vec![31_558_903, 22_713_056, 6_341_366, 760, 61];
        let msg = sup.run_spec(&wet(2, Some(canaries.clone()))).await.expect("the canary wet run");
        for needle in ["RENAMED 3 head(s)", "3 ready", "0 drifted", "2 asked org id(s) the plan does not plan", "[61, 760]"] {
            assert!(msg.contains(needle), "missing {needle:?} in: {msg}");
        }
        let after = heads().await;
        let named = |id: i64| {
            after
                .iter()
                .find(|(i, _, _)| *i == Value::Integer(id))
                .map(|(_, name, norm)| (name.clone(), norm.clone()))
                .expect("the organization")
        };
        let text = |s: &str| Value::Text(s.to_owned());
        assert_eq!(named(31_558_903), (text("The University of Sheffield"), text("the university of sheffield")));
        assert_eq!(
            named(22_713_056),
            (text("Vergabekammer bei der Bezirksregierung"), text(&store::org_name_norm("Vergabekammer bei der Bezirksregierung")))
        );
        assert_eq!(named(6_341_366), (text("Kalmar kommun"), text("kalmar kommun")));
        for id in [334, 335, 500, 1_165_973, 7_912_592] {
            let was = before.iter().find(|(i, _, _)| *i == Value::Integer(id)).unwrap();
            assert_eq!(after.iter().find(|(i, _, _)| *i == Value::Integer(id)).unwrap(), was, "{id} is untouched");
        }
        let changed = "SELECT COUNT(*) FROM changes WHERE entity_kind = 'organization' AND op = 'changed' \
                       AND version_seq IS NULL";
        assert_eq!(db.scalar(changed).await.unwrap(), Some(Value::Integer(3)), "one change row per moved org");
        assert_eq!(
            db.scalar("SELECT COUNT(*) FROM org_name_refresh_log WHERE job_id = 2 AND reverted_at IS NULL").await.unwrap(),
            Some(Value::Integer(3))
        );
        assert_eq!(
            db.scalar("SELECT old_name FROM org_name_refresh_log WHERE org_id = 22713056").await.unwrap(),
            Some(text("s.o.")),
            "the byte-exact pre-image"
        );
        let (body, _) = db.latest_report("org-name-refresh-applied").await.unwrap().expect("the wet report");
        let applied: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!((applied["job"].as_u64(), applied["applied"].as_u64(), applied["unplanned"].as_u64()), (Some(2), Some(3), Some(2)));
        let sampled: Vec<i64> = applied["applied_samples"].as_array().unwrap().iter().map(|r| r["org_id"].as_i64().unwrap()).collect();
        assert_eq!(sampled, vec![6_341_366, 22_713_056, 31_558_903], "a run under the sample size lists every rename");

        // A replay of the same run renames nothing and announces nothing.
        let msg = sup.run_spec(&wet(3, Some(canaries))).await.expect("the replay");
        assert!(msg.contains("3 already renamed") && msg.contains("RENAMED 0 head(s)"), "{msg}");
        assert_eq!(heads().await, after);
        assert_eq!(db.scalar(changed).await.unwrap(), Some(Value::Integer(3)));
        // Rule v7: renamed, the three canaries elect keep:S1, as the live 2516 five do.
        let msg = sup.run_spec(&dry(true)).await.expect("the re-plan");
        for reading in ["31558903 keep:S1 as expected", "22713056 keep:S1 as expected", "6341366 keep:S1 as expected"] {
            assert!(msg.contains(reading), "missing {reading:?} in: {msg}");
        }
        db.put_report("org-name-refresh-plan", &genuine, at).await.unwrap();
        // Job 2 recovered onto another binary (a deploy's restart): refused on the plan's `rev`, and the
        // line names the renames its earlier windows made, since that attempt stored no report.
        let mut moved: serde_json::Value = serde_json::from_str(&genuine).unwrap();
        moved["rev"] = serde_json::json!("the-binary-before");
        db.put_report("org-name-refresh-plan", &moved.to_string(), at).await.unwrap();
        let recovered = Job { resume_after: Some("31558903".into()), ..wet(2, None) };
        let err = sup.run_spec(&recovered).await.expect_err("another binary's plan");
        assert!(err.contains("binary \"the-binary-before\""), "{err}");
        assert!(err.contains("Nothing further was written by this run, but this job's earlier windows made 3 rename(s)"), "{err}");
        assert!(err.contains(r#"{"kind":"revert-org-name-refresh","job":2}"#) && !err.contains("Nothing was written"), "{err}");
        db.put_report("org-name-refresh-plan", &genuine, at).await.unwrap();
        // A recovered job resumes after its durable cursor (`job_queue.progress`): the three targets at
        // or below it are skipped, so 335 is not reached.
        let resumed = Job { resume_after: Some("22713056".into()), ..wet(4, None) };
        let msg = sup.run_spec(&resumed).await.expect("a resumed wet run");
        assert!(msg.contains("Resumed after org id 22713056: 3 target(s) skipped"), "{msg}");
        assert!(msg.contains("1 already renamed") && msg.contains("RENAMED 0 head(s)"), "{msg}");
        // The whole plan: only 335 is left to rename.
        let msg = sup.run_spec(&wet(4, None)).await.expect("the full wet run");
        assert!(msg.contains("RENAMED 1 head(s)") && msg.contains("3 already renamed"), "{msg}");
        assert_eq!(db.scalar(changed).await.unwrap(), Some(Value::Integer(4)));

        // The revert of job 2 restores its three pre-images and announces each; job 4's rename stands.
        let revert = Job { id: 5, kind: "revert-org-name-refresh".into(), ..job(Spec::RevertOrgNameRefresh { job: 2 }) };
        let msg = sup.run_spec(&revert).await.expect("the revert");
        assert!(msg.contains("3 RESTORED") && msg.contains("0 renamed again") && msg.contains("0 gone"), "{msg}");
        let restored = heads().await;
        for id in [6_341_366, 22_713_056, 31_558_903] {
            let was = before.iter().find(|(i, _, _)| *i == Value::Integer(id)).unwrap();
            assert_eq!(restored.iter().find(|(i, _, _)| *i == Value::Integer(id)).unwrap(), was, "{id} restored");
        }
        assert_ne!(
            restored.iter().find(|(i, _, _)| *i == Value::Integer(335)),
            before.iter().find(|(i, _, _)| *i == Value::Integer(335)),
            "another job's rename stands"
        );
        assert_eq!(db.scalar(changed).await.unwrap(), Some(Value::Integer(7)));
        assert_eq!(
            db.scalar("SELECT COUNT(*) FROM org_name_refresh_log WHERE job_id = 2 AND reverted_job = 5").await.unwrap(),
            Some(Value::Integer(3))
        );
        let msg = sup.run_spec(&revert).await.expect("a second revert");
        assert!(msg.contains("no unreverted org_name_refresh_log row"), "{msg}");
        assert_eq!(db.scalar(changed).await.unwrap(), Some(Value::Integer(7)));
        remove_db(&path);
    }

    /// Issue 524 units 2a.1/2a.2, with the REAL ingest functions: the vote key folds diacritics, so dry
    /// plan 2501's accent-only split (13731240) is one cluster and an S1 keep; the diacritic-bearing
    /// spelling is served over its ASCII TWIN and never over a wider cluster mate; a mojibake spelling
    /// is never served; an AG -> Sàrl swap is held as a family change; an R2 change that abbreviates
    /// the head (15075247) is held, while 2a.1's truncations, an address strip-down, a name that grows
    /// and every R1 shorthand change.
    #[test]
    fn the_head_election_folds_diacritics_and_holds_r2_shorthands_with_the_real_keys() {
        use store::{HeadKeep, HeadRule, HeadVerdict, elect_head};
        let fns = head_elect_fns();
        let org = |head| store::HeadElectOrg {
            head,
            identifier_kind: Some("national"),
            identifier: Some("RO12345678"),
            bind_defect: false,
            dated: None,
            // Rule v10: read only with dates.
            as_of: 0,
        };
        let dumbraveni = [("Comuna Dumbrăveni", 10), ("COMUNA DUMBRAVENI", 32)];
        assert_eq!(elect_head(&dumbraveni, &org("Comuna Dumbrăveni"), &fns), HeadVerdict::Keep(HeadKeep::S1));
        // Rule v6, dry plan 2515's 22609166: its `&` dropped to a doubled space, tied 2-2 with the intact
        // name in one cluster under the real vote key. Collapsed, `&` wins the byte tie-break.
        let brune = [("Julius Brune GmbH  Co. KG", 2), ("Julius Brune GmbH & Co. KG", 2), ("Mehrwert Logistik", 1)];
        assert_eq!(
            elect_head(&brune, &org("Mehrwert Logistik"), &fns),
            HeadVerdict::Change { rule: HeadRule::R1, new: "Julius Brune GmbH & Co. KG".into() }
        );
        // The sum decides under the real key too: `Acme  Services` 2 + `Acme Services` 2 beat `Acme
        // Services Ltd` 3 (one cluster: the key drops the legal form, and reads whitespace alike).
        let summed = [("Acme  Services", 2), ("Acme Services", 2), ("Acme Services Ltd", 3), ("Zeta Holdings", 1)];
        assert_eq!(elect_head(&summed, &org("Zeta Holdings"), &fns).new_name(), Some("Acme Services"));
        // The v7 review: a spelling must be fit as published AND once collapsed. U+2003 (an em space)
        // after `Ã` is no continuation character and no ASCII space, so the raw spelling passes the
        // mojibake test; collapsed to `SocietÃ Cooperativa` it is the word-final shape, and unfit.
        let em = "SocietÃ\u{2003}Cooperativa";
        assert!(ingest::crosswalk::head_spelling_unfit(em, "Head Body").is_none(), "fit as published");
        assert_eq!(ingest::crosswalk::head_spelling_unfit("SocietÃ Cooperativa", "Head Body"), Some("mojibake"));
        assert_eq!(
            elect_head(&[(em, 5), ("Head Body", 1)], &org("Head Body"), &fns),
            HeadVerdict::Hold { reason: store::HEAD_HOLD_NO_FIT, rule: HeadRule::R1, new: None }
        );
        // R0's tie-break reads fitness the same way: tied 3-3 under an empty head, the em-space cluster's
        // only non-ALL-CAPS spelling is unfit collapsed, so it ranks below the ALL-CAPS cluster and loses
        // the tie (read raw, it would win it and then hold `no_fit`) — although its vote key sorts first.
        let key = ingest::crosswalk::head_vote_key;
        assert!(key(em) < key("ZETA SRL"), "the key order alone would elect the em cluster");
        assert_eq!(
            elect_head(&[(em, 3), ("ZETA SRL", 3)], &org(""), &fns),
            HeadVerdict::Change { rule: HeadRule::R0e, new: "ZETA SRL".into() }
        );
        let ita =[("Itä-Suomen  aluehallintovirasto", 3), ("Pohjois-Savon ELY", 1)];
        assert_eq!(elect_head(&ita, &org("Pohjois-Savon ELY"), &fns).new_name(), Some("Itä-Suomen aluehallintovirasto"));
        let dotacion = [("Dotacion y Equipamiento S.L.", 4), ("Dotación y Equipamiento, S. L.", 1), ("Equipos Norte", 1)];
        assert_eq!(
            elect_head(&dotacion, &org("Equipos Norte"), &fns),
            HeadVerdict::Change { rule: HeadRule::R1, new: "Dotación y Equipamiento, S. L.".into() }
        );
        // R2's shape: the top holds 3 of 12, the stray head 1.
        let r2 = |new: &'static str, head: &'static str| {
            [(new, 3), ("Alpha Nord", 2), ("Beta Sud", 2), ("Gamma Est", 2), ("Delta West", 2), (head, 1)]
        };
        let caux = "Communauté de communes Terroir de Caux";
        assert_eq!(
            elect_head(&r2("CDC Terroir de Caux", caux), &org(caux), &fns),
            HeadVerdict::Hold { reason: "initialism", rule: HeadRule::R2, new: Some("CDC Terroir de Caux".into()) }
        );
        // Unit 2a.2 dropped 2a.1's truncation arm: this synthetic R2 now changes (the real 13839658 is
        // an S1 keep once the fold joins its `C3I` spellings to the head's cluster).
        let c3i = "C 3 I - CONCEPT EN INGENIERIE D'INFRASTRUCTURES INNOVANTES";
        assert_eq!(
            elect_head(&r2("SAS C3i", c3i), &org(c3i), &fns),
            HeadVerdict::Change { rule: HeadRule::R2, new: "SAS C3i".into() }
        );
        assert_eq!(
            elect_head(&r2("EY Advisory", "Ernst & Young Advisory"), &org("Ernst & Young Advisory"), &fns),
            HeadVerdict::Change { rule: HeadRule::R2, new: "EY Advisory".into() },
            "two letters are no initialism"
        );
        let address = "Firma Kowalski ul. Polna 1 00-001 Warszawa NIP 1234567890";
        assert_eq!(
            elect_head(&r2("Firma Kowalski", address), &org(address), &fns),
            HeadVerdict::Change { rule: HeadRule::R2, new: "Firma Kowalski".into() },
            "the address and NIP strip-down still changes"
        );
        assert_eq!(
            elect_head(&r2("FREGONESE ET FILS", "FREGONESE"), &org("FREGONESE"), &fns),
            HeadVerdict::Change { rule: HeadRule::R2, new: "FREGONESE ET FILS".into() },
            "a name that grows is no shorthand"
        );
        // R1 is untouched: a shorthand the R2 hold would read as a truncation still changes under R1.
        let ta = "TRIBUNAL ADMINISTRATIF DE NICE (TA)";
        let nice = [("Tribunal administratif de Nice", 10), (ta, 1)];
        assert_eq!(
            elect_head(&nice, &org(ta), &fns),
            HeadVerdict::Change { rule: HeadRule::R1, new: "Tribunal administratif de Nice".into() }
        );
        let greffe = "Tribunal administratif de Nice Greffe";
        assert_eq!(
            elect_head(&r2("Tribunal administratif de Nice", greffe), &org(greffe), &fns),
            HeadVerdict::Change { rule: HeadRule::R2, new: "Tribunal administratif de Nice".into() },
            "no truncation hold since unit 2a.2"
        );
        // An initialism the R2 hold reads still changes under R1.
        assert_eq!(ingest::crosswalk::head_r2_hold(caux, "CDC Terroir de Caux"), Some("initialism"));
        let majority = [("CDC Terroir de Caux", 10), (caux, 1)];
        assert_eq!(
            elect_head(&majority, &org(caux), &fns),
            HeadVerdict::Change { rule: HeadRule::R1, new: "CDC Terroir de Caux".into() }
        );
        // Unit 2a.2's display regression fix: an accent outside a twin does not beat the votes.
        let trading = [("Acme Ltd", 20), ("Acme Ltd t/a Café Rouge", 1), ("Other Body", 1)];
        assert_eq!(elect_head(&trading, &org("Other Body"), &fns).new_name(), Some("Acme Ltd"));
        let form = [("Acme GmbH", 20), ("Acme Sàrl", 1), ("Other Body", 1)];
        assert_eq!(elect_head(&form, &org("Other Body"), &fns).new_name(), Some("Acme GmbH"));
        // Mojibake is unfit: the clean spelling is served whatever the votes.
        let napoli = [("UniversitÃ\u{a0}degli Studi di Napoli", 9), ("Università degli Studi di Napoli", 1), ("Ateneo Sud", 1)];
        assert_eq!(elect_head(&napoli, &org("Ateneo Sud"), &fns).new_name(), Some("Università degli Studi di Napoli"));
        // The family hold reads the folded names: AG -> Sàrl is a family swap. Rule v13 (issue 548 U2):
        // it holds only while the head's own cluster holds 2+ votes (dated, so that H does not hold
        // `undated` first); a stray head (H = 1) changes.
        let undated: [store::DatedVote<'_>; 0] = [];
        let dated = |head| store::HeadElectOrg { dated: Some(&undated), ..org(head) };
        let swiss = [("Acme Sàrl", 5), ("Acme Schweiz AG", 2)];
        assert_eq!(
            elect_head(&swiss, &dated("Acme Schweiz AG"), &fns),
            HeadVerdict::Hold { reason: "family", rule: HeadRule::R1, new: Some("Acme Sàrl".into()) }
        );
        let stray = [("Acme Sàrl", 5), ("Acme Schweiz AG", 1)];
        assert_eq!(
            elect_head(&stray, &org("Acme Schweiz AG"), &fns),
            HeadVerdict::Change { rule: HeadRule::R1, new: "Acme Sàrl".into() },
            "rule v13: a stray head's family swap is released"
        );
        // Unit 2a.3: …and joins a dotted form's letters first: AG -> S.à r.l. is one too.
        let dotted = [("Acme S.à r.l.", 5), ("Acme Schweiz AG", 2)];
        assert_eq!(
            elect_head(&dotted, &dated("Acme Schweiz AG"), &fns),
            HeadVerdict::Hold { reason: "family", rule: HeadRule::R1, new: Some("Acme S.à r.l.".into()) }
        );
        // Unit 2a.3: an accented winner keeps its place against a one-mention typo twin (1526605).
        let ministry = [
            ("Ministerstvo práce, sociálnych vecí a rodiny Slovenskej republiky", 717),
            ("Ministerstvo práce,sociálných vecí a rodiny Slovenskej republiky", 1),
            ("Urad Prace", 1),
        ];
        assert_eq!(
            elect_head(&ministry, &org("Urad Prace"), &fns).new_name(),
            Some("Ministerstvo práce, sociálnych vecí a rodiny Slovenskej republiky")
        );
        // Unit 2a.3: a bare ALL-CAPS initialism is held under R2.
        let pays = "Communauté de communes du Pays de Caux";
        assert_eq!(
            elect_head(&r2("CDCPC", pays), &org(pays), &fns),
            HeadVerdict::Hold { reason: "initialism", rule: HeadRule::R2, new: Some("CDCPC".into()) }
        );
    }

    /// Issue 524 rule v8, with the REAL ingest functions, on the new canaries' plan-2523 spellings and
    /// counts (dates synthetic, in the shape plan 2523 read): 3909's lower-case head and 1846's `CA2BM`
    /// head, both released by v7's junk exemption, are held `recent` now; 3740262's head, printed on
    /// the newest procedure with the window silent, is held `residue`; an address number still
    /// releases where the elected name is the head minus junk (rule v9: 1341's own shape is withheld).
    #[test]
    fn the_v8_canary_shapes_hold_with_the_real_keys() {
        use store::{DatedVote, HeadRule, HeadVerdict, elect_head_counted};
        let fns = head_elect_fns();
        let day = 86_400;
        // `old` items from day 1 on, then `new` items from day 1,000 on: the head owns the newest k.
        let window = |old: &'static str, n: i64, head: &'static str, k: i64| -> Vec<DatedVote<'static>> {
            (0..n)
                .map(|i| DatedVote { spelling: old, tender: 1 + i, at: (1 + i) * day })
                .chain((0..k).map(|i| DatedVote { spelling: head, tender: 1_000 + i, at: (1_000 + i) * day }))
                .collect()
        };
        let elect = |votes: &[(&str, u64)], head: &str, dated: &[DatedVote<'_>]| {
            let org = store::HeadElectOrg {
                head,
                identifier_kind: Some("national"),
                identifier: Some("X1"),
                bind_defect: false,
                dated: Some(dated),
                // Rule v10: a plan of 2026-10-16; every head here was printed by day 1,100 (1973), so
                // none is current and these shapes read as v9 read them.
                as_of: 1_792_108_800,
            };
            elect_head_counted(votes, &org, &fns)
        };
        let hold = |reason: &'static str, new: &str| HeadVerdict::Hold { reason, rule: HeadRule::R1, new: Some(new.into()) };

        // 3909: the registered current name is all lower case — v7 released it as `unfit`.
        let act = "act legal s.r.o., advokátní kancelář";
        let randa = "act Řanda Havel Legal advokátní kancelář s.r.o.";
        assert_eq!(ingest::crosswalk::head_spelling_unfit(act, act), Some("lowercase"));
        let votes = [(randa, 186), (act, 52), ("Řanda Havel Legal advokátní kancelář s.r.o.", 65)];
        let e = elect(&votes, act, &window(randa, 10, act, 3));
        assert_eq!((e.verdict, e.recent.unwrap().released), (hold(store::HEAD_HOLD_RECENT, randa), None));

        // 1846: `CA2BM` is the body's acronym — v7 released it as `digits` (a digit inside a word).
        let ca2bm = "CA2BM - Communauté d'Agglomération des deux Baies en Montreuillois";
        let baies = "CA des Deux Baies en Montreuillois";
        let key = ingest::crosswalk::head_vote_key(ca2bm);
        assert!(key.split(' ').any(|t| t.chars().any(char::is_numeric)), "v7's test saw a digit: {key}");
        let votes = [
            ("CA DES DEUX BAIES EN MONTREUILLOIS", 104),
            ("ca des deux baies en montreuillois", 83),
            (baies, 44),
            (ca2bm, 52),
            ("Communauté d'agglomération des Deux Baies en Montreuillois", 16),
        ];
        let e = elect(&votes, ca2bm, &window(baies, 10, ca2bm, 3));
        assert_eq!((e.verdict, e.recent.unwrap().released), (hold(store::HEAD_HOLD_RECENT, baies), None));

        // 3740262: an organ (`Junta de Gobierno …`) holds the majority, the window is silent (k = 6,
        // h_W = 1), and the entity's head names the newest procedure: held `residue`.
        let fuengirola = "Ayuntamiento de Fuengirola";
        let junta = "Junta de Gobierno del Ayuntamiento de Fuengirola";
        let votes = [(junta, 247), (fuengirola, 67), ("AYUNTAMIENTO DE FUENGIROLA", 8), ("Ayuntamiento Fuengirola", 1)];
        let mut dated = window(junta, 20, fuengirola, 0);
        for (i, at) in [2, 4, 6, 8, 10, 30].into_iter().enumerate() {
            dated.push(DatedVote { spelling: fuengirola, tender: 100 + i as i64, at: at * day });
        }
        let e = elect(&votes, fuengirola, &dated);
        let read = e.recent.unwrap();
        assert_eq!((read.head_procs, read.head_in_window, read.fires, read.newest_is_head), (6, 1, false, true));
        assert_eq!((e.verdict, read.released), (hold(store::HEAD_HOLD_RESIDUE, junta), None));

        // An address number the elected key lacks: v8 released 1341's shape and R1 served. Rule v9
        // changed this expectation on purpose: the elected name drops five head words besides the number
        // (the owner `Jelka … Škugor`, `Sisak`, `Tina Ujevića`), more than junk-only's one, so the
        // release is withheld and the window's hold stands — 1341 is in the decision's withheld list
        // (labelled right: one of the 8 forgone fixes it accepts as cost).
        let obrt = "MARČINKOVIĆ GRAĐEVINSKI OBRT";
        let street = "MARČINKOVIĆ, GRAĐEVINSKI OBRT, JELKA MARČINKOVIĆ ŠKUGOR, SISAK, TINA UJEVIĆA 18";
        let votes = [(obrt, 14), (street, 6), ("Obrt Marčinković", 2)];
        let e = elect(&votes, street, &window(obrt, 10, street, 3));
        assert_eq!((e.recent.unwrap().released, e.recent.unwrap().release_withheld), (None, Some("junk_only")));
        assert_eq!(e.verdict, hold(store::HEAD_HOLD_RECENT, obrt));
        // The v8 point survives on a head that is the elected name plus its street and number: released.
        let plus = "MARČINKOVIĆ GRAĐEVINSKI OBRT, UJEVIĆA 18";
        let votes = [(obrt, 14), (plus, 6), ("Obrt Marčinković", 2)];
        let e = elect(&votes, plus, &window(obrt, 10, plus, 3));
        assert_eq!(e.recent.unwrap().released, Some("digits"));
        assert_eq!(e.verdict, HeadVerdict::Change { rule: HeadRule::R1, new: obrt.into() });
    }

    /// Issue 524 rule v9, with the REAL ingest functions, on plan 2526's own spellings and vote counts
    /// (dates synthetic, in the shape plan 2526 read each one): one canary per serve hold, a review
    /// body's self-rename that still changes, the two withheld releases back under `residue`, and the
    /// releases v9 keeps. The planner and the wet pre-pass both run these through `head_elect_fns()`.
    #[test]
    fn the_v9_canary_shapes_with_the_real_keys() {
        use store::{DatedVote, HeadRule, HeadVerdict, elect_head_counted};
        let fns = head_elect_fns();
        let day = 86_400;
        // `n` items of each spelling, one per tender, a day apart from `from` on.
        let spread = |spelling: &'static str, tender: i64, from: i64, n: i64| -> Vec<DatedVote<'static>> {
            (0..n).map(|i| DatedVote { spelling, tender: tender + i, at: (from + i) * day }).collect()
        };
        let elect = |votes: &[(&str, u64)], head: &str, dated: &[DatedVote<'_>]| {
            let org = store::HeadElectOrg {
                head,
                identifier_kind: Some("national"),
                identifier: Some("X1"),
                bind_defect: false,
                dated: Some(dated),
                // Rule v10: a plan of 2026-10-16; every head here was printed by day 1,100 (1973), so
                // none is current and these shapes read as v9 read them.
                as_of: 1_792_108_800,
            };
            elect_head_counted(votes, &org, &fns)
        };
        let held = |reason: &'static str, rule: HeadRule, new: &str| HeadVerdict::Hold { reason, rule, new: Some(new.into()) };
        let change = |new: &str| HeadVerdict::Change { rule: HeadRule::R1, new: new.into() };
        // The elected cluster newest: no date hold, so the serve hold answers.
        let forward = |old: &'static str, new: &'static str| [spread(old, 1, 1, 2), spread(new, 100, 10, 3)].concat();

        // 22028982: a review chamber's name for a university clinic (V 448, T 402, H 40).
        let (uni, vk) = ("Universitätsklinikum Freiburg", "Vergabekammer BW");
        let e = elect(&[(vk, 402), (uni, 40), ("Vergabekammer Baden-Württemberg, Regierungspräsidium Karlsruhe", 6)], uni, &forward(uni, vk));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_REVIEW_BODY, HeadRule::R1, vk));
        // 791: the review body's own self-rename changes (its head carries `odwola`).
        let (uzp, kio) = ("Urząd Zamówień Publicznych Departament Odwołań", "Krajowa Izba Odwoławcza");
        let e = elect(&[(kio, 19_394), (uzp, 4_018), ("KRAJOWA IZBA ODWOŁAWCZA", 991)], uzp, &forward(uzp, kio));
        assert_eq!(e.verdict, change(kio));
        // 4065575: an organ for its entity.
        let (ayto, junta) = ("Ayuntamiento de Fuenlabrada", "Junta de Gobierno Local del Ayuntamiento de Fuenlabrada");
        let e = elect(&[(junta, 308), (ayto, 113), ("Ayuntamiento de fuenlabrada", 1)], ayto, &forward(ayto, junta));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_ORGAN, HeadRule::R1, junta));
        // 2762: an organ head to its entity changes.
        let (organ, diputacion) =
            ("Junta de Gobierno de la Diputación Provincial de Valladolid", "Diputación Provincial de Valladolid");
        let e = elect(&[(diputacion, 89), ("DIPUTACIÓN PROVINCIAL DE VALLADOLID", 21), (organ, 32)], organ, &forward(organ, diputacion));
        assert_eq!(e.verdict, change(diputacion));
        // 17116440: a department code added.
        let (chiconi, coded) = ("Commune de Chiconi", "Commune de Chiconi (976)");
        let e = elect(&[(coded, 16), (chiconi, 4)], chiconi, &forward(chiconi, coded));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_CODE_ADDED, HeadRule::R1, coded));
        // 8069375: the registered name plus `…, Ljubljana, Kolodvorska 11`.
        let institut = "Prometni institut Ljubljana d.o.o.";
        let seat = "PROMETNI INSTITUT LJUBLJANA d.o.o. za področje raziskovalne in informativne dejavnosti ter izdelavo \
                    predinvesticijskih in investicijskih programov, Ljubljana, Kolodvorska 11";
        let seat_mixed = "Prometni institut Ljubljana d.o.o. za področje raziskovalne in informativne dejavnosti ter \
                          izdelavo predinvesticijskih in investicijskih programov, Ljubljana, Kolodvorska 11";
        let e = elect(&[(seat, 25), (seat_mixed, 24), (institut, 10)], institut, &forward(institut, seat));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_ADDRESS_ADDED, HeadRule::R1, seat));
        // 16508165, an R2: an ALL-CAPS respelling of the mixed-case head's words (V 19, T 6, H 1).
        let (hurt, caps) = ("Hurt-Papier Ryszard Cebula Sp. j.", "HURT PAPIER RYSZARD CEBULA SPÓŁKA JAWNA");
        let votes = [
            (caps, 6),
            ("Hurt-Papier Ryszard Cebula spółka komandytowa", 5),
            ("„HURT – PAPIER” RYSZARD CEBULA S.J.", 3),
            ("„HURT – PAPIER” RYSZARD CEBULA sp. komandytowa", 3),
            ("Hurt-Papier Ryszard Cebula", 1),
            (hurt, 1),
        ];
        let e = elect(&votes, hurt, &forward(hurt, caps));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_CAPS_VARIANT, HeadRule::R2, caps));

        // 4295185: `S.M.D.3` keys with the head (`smd 3`, H 83); the elected `smd3` holds its `3` glued:
        // no junk, so the residue hold stands (`glue`). k = 2, h_W = 1: the head names the newest item.
        let votes = [("SMD3", 166), ("smd3", 74), ("Smd3", 2), ("S.M.D.3", 45), ("SMD 3", 33), ("s.M.D.3", 5)];
        let mut dated = spread("SMD3", 1, 1, 10);
        dated.push(DatedVote { spelling: "SMD 3", tender: 50, at: 5 * day });
        dated.push(DatedVote { spelling: "S.M.D.3", tender: 60, at: 100 * day });
        let e = elect(&votes, "SMD 3", &dated);
        let read = e.recent.unwrap();
        assert_eq!((e.head_votes, read.fires, read.newest_is_head), (83, false, true));
        assert_eq!((e.verdict, read.release_withheld), (held(store::HEAD_HOLD_RESIDUE, HeadRule::R1, "Smd3"), Some("glue")));
        // 9814: the activity phrase for the owner's head and address (one procedure, the newest).
        let head = "IZRADA ŠUMSKIH SORTIMENATA DRAGAN ŠAPINA, KORENICA, ZAGREBAČKA 49/2";
        let phrase = "Izrada šumskih sortimenata";
        let mut dated = spread(phrase, 1, 1, 13);
        dated.push(DatedVote { spelling: head, tender: 500, at: 100 * day });
        dated.push(DatedVote { spelling: head, tender: 500, at: 101 * day });
        let e = elect(&[(phrase, 13), (head, 2)], head, &dated);
        assert_eq!((e.verdict, e.recent.unwrap().release_withheld), (held(store::HEAD_HOLD_RESIDUE, HeadRule::R1, phrase), Some("junk_only")));
        // 3042: the head owns the newest procedures, its `(68)` the one number and no word lost: released.
        let (colmar68, colmar) = ("Hôpitaux Civils de Colmar (68)", "Hôpitaux civils de Colmar");
        let votes = [(colmar, 440), (colmar68, 251), ("Hopitaux civils de Colmar", 84), ("Hôpitaux Civils de Colmar", 69)];
        let e = elect(&votes, colmar68, &[spread(colmar, 1, 1, 10), spread(colmar68, 100, 100, 4)].concat());
        assert_eq!((e.verdict, e.recent.unwrap().released), (change(colmar), Some("digits")));
        // 14971333: `DF 5`'s number is glued to nothing the elected `s5` holds: released, as in v8.
        let (df, s5) = ("Infrastructură DF 5", "Infrastructura S5");
        let votes = [("INFRASTRUCTURA S5", 20), ("Infrastructura DF 5", 3), ("Infrastructura S 5", 2), (s5, 2), (df, 2)];
        let mut dated = spread(s5, 1, 1, 6);
        dated.push(DatedVote { spelling: df, tender: 50, at: 3 * day });
        dated.push(DatedVote { spelling: df, tender: 60, at: 100 * day });
        let e = elect(&votes, df, &dated);
        assert_eq!((e.verdict, e.recent.unwrap().released), (change(s5), Some("digits")));
    }

    /// Issue 524 rule v10, with the REAL ingest functions: an R1 change on a head printed within 3
    /// years of the plan's `as_of` holds `head_current` with the spelling it would serve, and the same
    /// change planned more than 3 years after the head's last print changes (canary 4220276's rename,
    /// `Pöyry CM Oy` → `Ramboll CM Oy`, dates synthetic); 3042's `(68)`, released by the window's junk
    /// exemption, still changes on a current head; and a serve hold keeps its reason on a current head
    /// (22028982). The planner and the wet pre-pass both run these through `head_elect_fns()`.
    #[test]
    fn the_v10_head_current_shapes_with_the_real_keys() {
        use store::{DatedVote, HeadRule, HeadVerdict, elect_head_counted};
        let fns = head_elect_fns();
        let day = 86_400;
        let spread = |spelling: &'static str, tender: i64, from: i64, n: i64| -> Vec<DatedVote<'static>> {
            (0..n).map(|i| DatedVote { spelling, tender: tender + i, at: (from + i) * day }).collect()
        };
        let elect = |votes: &[(&str, u64)], head: &str, dated: &[DatedVote<'_>], as_of: i64| {
            let org = store::HeadElectOrg {
                head,
                identifier_kind: Some("national"),
                identifier: Some("X1"),
                bind_defect: false,
                dated: Some(dated),
                as_of,
            };
            elect_head_counted(votes, &org, &fns)
        };
        let held = |reason: &'static str, new: &str| HeadVerdict::Hold { reason, rule: HeadRule::R1, new: Some(new.into()) };
        let change = |new: &str| HeadVerdict::Change { rule: HeadRule::R1, new: new.into() };

        // 4220276's shape: the head's two items (days 1–2) older than every elected one (days 10–29).
        let (poyry, ramboll) = ("Pöyry CM Oy", "Ramboll CM Oy");
        let votes = [(ramboll, 20), (poyry, 2)];
        let dated = [spread(poyry, 1, 1, 2), spread(ramboll, 100, 10, 20)].concat();
        let e = elect(&votes, poyry, &dated, 100 * day);
        assert_eq!(e.verdict, held(store::HEAD_HOLD_CURRENT, ramboll), "printed 98 days before the plan");
        let read = e.recent.unwrap();
        assert_eq!((read.fires, read.newest_is_head, read.released), (false, false, None));
        let e = elect(&votes, poyry, &dated, (2 + store::HEAD_CURRENT_DAYS + 1) * day);
        assert_eq!(e.verdict, change(ramboll), "last printed 1,096 days before the plan");

        // 3042: the window fires on the head's newest items and releases its `(68)`; v10 keeps it.
        let (colmar68, colmar) = ("Hôpitaux Civils de Colmar (68)", "Hôpitaux civils de Colmar");
        let votes = [(colmar, 440), (colmar68, 251), ("Hopitaux civils de Colmar", 84), ("Hôpitaux Civils de Colmar", 69)];
        let dated = [spread(colmar, 1, 1, 10), spread(colmar68, 100, 100, 4)].concat();
        let e = elect(&votes, colmar68, &dated, 104 * day);
        assert_eq!(e.recent.unwrap().head_newest, Some(103 * day), "printed the day before the plan");
        assert_eq!((e.verdict, e.recent.unwrap().released), (change(colmar), Some("digits")));

        // 22028982: the review hold answers before v10, on a head as current as can be.
        let (uni, vk) = ("Universitätsklinikum Freiburg", "Vergabekammer BW");
        let dated = [spread(uni, 1, 1, 2), spread(vk, 100, 10, 3)].concat();
        let e = elect(&[(vk, 402), (uni, 40)], uni, &dated, 13 * day);
        assert_eq!(e.verdict, held(store::HEAD_HOLD_REVIEW_BODY, vk));
    }

    /// Issue 524 rule v11, with the REAL ingest functions, on the v11 canaries' plan-2543 spellings and
    /// vote counts (an unlisted spelling or two added where the listing's top five fall short of V), each
    /// head's and elected spelling's newest dates as plan 2543 read them and its `as_of`: job 2555's three
    /// wrongs hold `top_stale`; 1918631 holds `doubled`, 5350675 `seat_dropped` and 22831984
    /// `placeholder_id` (a v10 `digits` release: the bind guard answers in `serve`, before any release
    /// counts); the stale no-rival tops 2857103 and 2715115 and the fresh top with a rival 1800186
    /// change; and 3042, released by the window, changes on its stale top with a rival. The planner and
    /// the wet pre-pass both run these through `head_elect_fns()`.
    #[test]
    fn the_v11_canary_shapes_with_the_real_keys() {
        use store::{DatedVote, HeadRule, HeadVerdict, elect_head_counted};
        let fns = head_elect_fns();
        let day = 86_400;
        // Plan 2543's `as_of`, 2026-10-16 11:20:05 UTC.
        let as_of = 1_792_132_805;
        // Days since 1970-01-01 of a `YYYY-MM-DD` (Hinnant's days-from-civil), checked against the store's
        // own inverse.
        let on = |date: &str| {
            let part = |at: std::ops::Range<usize>| date[at].parse::<i64>().expect("a date");
            let (y, m, d) = (part(0..4), part(5..7), part(8..10));
            let y = if m <= 2 { y - 1 } else { y };
            let era = y.div_euclid(400);
            let yoe = y - era * 400;
            let doy = (153 * ((m + 9) % 12) + 2) / 5 + d - 1;
            let days = era * 146_097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719_468;
            assert_eq!(store::rates::civil_date(days * day), date);
            days
        };
        // `n` items of `spelling`, one per tender from `tender` on, a day apart, the newest on `newest`.
        let ending = |spelling: &'static str, tender: i64, newest: &str, n: i64| -> Vec<DatedVote<'static>> {
            let last = on(newest);
            (0..n).map(|i| DatedVote { spelling, tender: tender + i, at: (last - i) * day }).collect()
        };
        let elect = |votes: &[(&str, u64)], head: &str, identifier: &str, dated: &[DatedVote<'_>]| {
            let org = store::HeadElectOrg {
                head,
                identifier_kind: Some("national"),
                identifier: Some(identifier),
                bind_defect: false,
                dated: Some(dated),
                as_of,
            };
            elect_head_counted(votes, &org, &fns)
        };
        let held = |reason: &'static str, new: &str| HeadVerdict::Hold { reason, rule: HeadRule::R1, new: Some(new.into()) };
        let change = |new: &str| HeadVerdict::Change { rule: HeadRule::R1, new: new.into() };

        // 1556789: V 27, T 15, H 1, 4 clusters; head 2011-12-24, top 2020-03-11 — a revert spelling's rival.
        let (head, elected) = ("Instituto Navarro del Deporte y Actividad Fisica", "Instituto Navarro de Deporte y Juventud");
        let votes = [
            (elected, 15),
            ("INSTITUTO NAVARRO DEL DEPORTE", 7),
            ("INSTITUTO NAVARRO DEL DEPORTE Y DE LA ACTIVIDAD FISICA", 2),
            ("Instituto Navarro del Deporte", 2),
            (head, 1),
        ];
        let dated = [
            ending(elected, 1, "2020-03-11", 15),
            ending("INSTITUTO NAVARRO DEL DEPORTE", 100, "2019-06-01", 7),
            ending("Instituto Navarro del Deporte", 200, "2018-06-01", 2),
            ending("INSTITUTO NAVARRO DEL DEPORTE Y DE LA ACTIVIDAD FISICA", 300, "2016-06-01", 2),
            ending(head, 400, "2011-12-24", 1),
        ]
        .concat();
        let e = elect(&votes, head, "Q3150025I", &dated);
        assert_eq!((e.voting, e.top, e.head_votes, e.second, e.clusters), (27, 15, 1, 9, 4));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_TOP_STALE, elected), "1556789");

        // 1276213: V 96, T 56, H 7, 3 clusters; head 2015-09-04, top 2023-11-20; the superseding name newer.
        let head = "Instituto Andaluz de Investigación y Formación Agraria Y Pesquera (IFAPA)";
        let elected = "Instituto de Investigación y Formación Agraria y Pesquera";
        let caps = "INSTITUTO DE INVESTIGACIÓN Y FORMACIÓN AGRARIA Y PESQUERA";
        let newer = "Instituto Andaluz de Investigación y Formación Agraria, Pesquera, Alimentaria y de la Producción Ecológica";
        let head_twin = "Instituto Andaluz de Investigación y Formación Agraria y Pesquera (IFAPA)";
        let votes = [(caps, 35), (newer, 33), (elected, 21), (head_twin, 6), (head, 1)];
        let dated = [
            ending(caps, 1, "2023-11-20", 35),
            ending(elected, 100, "2022-01-01", 21),
            ending(newer, 200, "2026-09-01", 33),
            ending(head_twin, 300, "2015-09-03", 6),
            ending(head, 400, "2015-09-04", 1),
        ]
        .concat();
        let e = elect(&votes, head, "Q4100689A", &dated);
        assert_eq!((e.voting, e.top, e.head_votes, e.second, e.clusters), (96, 56, 7, 33, 3));
        assert_eq!(e.recent.map(|r| (r.fires, r.newest_is_head)), Some((false, false)));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_TOP_STALE, elected), "1276213");
        assert_eq!(e.recent.unwrap().rival_newest, Some(on("2026-09-01") * day), "the superseding name, newer than the top");

        // 1345526: V 143, T 128, H 1, 4 clusters; head 2011-11-03, top 2025-01-29 (625 days).
        let head = "Mairie de Valence - direction de l'administration, de la commande publique et des affaires juridiques";
        let elected = "Valence Romans Sud Rhône-Alpes";
        let votes = [
            ("valence romans sud rhone-alpes", 55),
            (elected, 52),
            ("Ville de Valence", 12),
            ("VALENCE ROMANS SUD RHONE-ALPES", 10),
            ("Valence-Romans Sud Rhône-Alpes", 8),
            ("Valence Romans Sud Rhone-Alpes", 3),
            ("Commune de Valence", 2),
            (head, 1),
        ];
        let dated = [
            ending(elected, 1, "2025-01-29", 52),
            ending("Ville de Valence", 100, "2024-03-01", 12),
            ending("Commune de Valence", 200, "2013-01-01", 2),
            ending(head, 300, "2011-11-03", 1),
        ]
        .concat();
        let e = elect(&votes, head, "21260362500014", &dated);
        assert_eq!((e.voting, e.top, e.head_votes, e.clusters), (143, 128, 1, 4));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_TOP_STALE, elected), "1345526");

        // 1918631: the doubled name, a fresh top (2026-09-02), H 69 (head 2021-07-20).
        let head = "Instituto Foral de Bienestar Social";
        let doubled = "Instituto Foral de Bienestar Social - Instituto Foral de Bienestar Social";
        let area = "Instituto Foral de Bienestar Social, Área de Contratación y Régimen Jurídico";
        let votes = [
            (doubled, 218),
            (head, 69),
            (area, 8),
            ("Instituto Foral de Bienestar Social — Área de Contratación y Régimen Jurídico", 4),
            ("Instituto Foral de Bienestar Social — Instituto Foral de Bienestar Social", 3),
            ("INSTITUTO FORAL DE BIENESTAR SOCIAL - INSTITUTO FORAL DE BIENESTAR SOCIAL", 1),
        ];
        let dated = [ending(doubled, 1, "2026-09-02", 218), ending(area, 300, "2024-01-01", 8), ending(head, 500, "2021-07-20", 69)]
            .concat();
        let e = elect(&votes, head, "G01019124", &dated);
        assert_eq!((e.top, e.head_votes), (222, 69));
        assert_eq!(e.verdict, held(store::HEAD_HOLD_DOUBLED, doubled), "1918631");

        // 5350675: the seat dropped; a stale top with no rival (V 4, T 3, H 1).
        let (head, elected) = ("Ośrodek Pomocy Społecznej w Kluczborku", "Ośrodek Pomocy Społecznej");
        let dated = [ending(elected, 1, "2017-05-27", 3), ending(head, 100, "2014-07-05", 1)].concat();
        let e = elect(&[(elected, 3), (head, 1)], head, "7511368012", &dated);
        assert_eq!(e.clusters, 2);
        assert_eq!(e.verdict, held(store::HEAD_HOLD_SEAT_DROPPED, elected), "5350675");

        // 22831984: `KEINEANGABE7`; the head printed within 3 years (a v10 `digits` release).
        let (head, aok) = ("Kapitel 2", "AOK PLUS - Die Gesundheitskasse für Sachsen und Thüringen");
        let dated = [ending(aok, 1, "2025-05-13", 4), ending(head, 100, "2024-11-26", 2)].concat();
        let votes = [(aok, 4), (head, 2)];
        let e = elect(&votes, head, "KEINEANGABE7", &dated);
        assert_eq!(e.verdict, held(store::HEAD_HOLD_PLACEHOLDER_ID, aok), "22831984");
        // On a real identifier the same shape is v10's `digits` release, as plan 2543 planned it.
        let e = elect(&votes, head, "DE123456789", &dated);
        assert_eq!((e.verdict, e.recent.unwrap().released), (change(aok), Some("digits")));

        // 2857103 and 2715115: stale tops (2020-10-26, 2018-11-27) with no rival: they change.
        let dated = [ending("Itslearning Oy", 1, "2020-10-26", 3), ending("itslearning Oy", 50, "2019-01-01", 1), ending("Fronter Oy", 100, "2012-11-03", 1)].concat();
        let e = elect(&[("Itslearning Oy", 3), ("Fronter Oy", 1), ("itslearning Oy", 1)], "Fronter Oy", "21389668", &dated);
        assert_eq!((e.clusters, e.verdict), (2, change("Itslearning Oy")), "2857103");
        let (lannen, turun) = ("Lännen Tekstiilihuolto Oy", "Turun Tekstiilihuolto Oy");
        let dated = [ending(lannen, 1, "2018-11-27", 7), ending("Lännen tekstiilihuolto Oy", 50, "2017-01-01", 2), ending(turun, 100, "2013-09-25", 2)].concat();
        let e = elect(&[(lannen, 7), ("Lännen tekstiilihuolto Oy", 2), (turun, 2)], turun, "17188580", &dated);
        assert_eq!((e.clusters, e.verdict), (2, change(lannen)), "2715115");

        // 1800186: a fresh top (2026-09-22) with a rival above the head: it changes.
        let (head, elected) = ("Attendo MedOne Oy", "Terveystalo Julkiset Palvelut Oy");
        let votes = [
            (elected, 283),
            ("Attendo Terveyspalvelut Oy", 113),
            ("Terveystalon Julkiset Palvelut Oy", 23),
            ("Terveystalo Julkiset palvelut Oy", 20),
            ("Attendo Terveyspalvelut Oy (10A)", 2),
            (head, 1),
        ];
        let dated = [ending(elected, 1, "2026-09-22", 283), ending("Attendo Terveyspalvelut Oy", 400, "2025-01-01", 113), ending(head, 600, "2012-02-18", 1)].concat();
        let e = elect(&votes, head, "16251744", &dated);
        assert!(e.clusters > 2 && e.head_votes == 1, "a rival: {} clusters", e.clusters);
        assert_eq!(e.verdict, change(elected), "1800186");

        // 3042: the window fires on the head's newest procedures and releases its `(68)`; the top
        // (2022-10-12) is stale and two rivals vote, and the release ships it.
        let (colmar68, colmar) = ("Hôpitaux Civils de Colmar (68)", "Hôpitaux civils de Colmar");
        let votes = [
            (colmar, 440),
            (colmar68, 251),
            ("Hopitaux civils de Colmar", 84),
            ("Hôpitaux Civils de Colmar", 69),
            ("Hopitaux Civils de Colmar", 28),
            ("Groupe Hospitalier Centre Alsace", 6),
            ("GHT Alsace Centre", 2),
        ];
        let dated = [
            ending(colmar, 1, "2022-10-12", 440),
            ending("Groupe Hospitalier Centre Alsace", 1_000, "2021-01-01", 6),
            ending(colmar68, 2_000, "2026-10-08", 251),
        ]
        .concat();
        let e = elect(&votes, colmar68, "26680090300012", &dated);
        assert_eq!((e.head_votes, e.clusters), (251, 4));
        assert_eq!(e.recent.map(|r| (r.fires, r.released)), Some((true, Some("digits"))));
        assert!(store::head_top_stale(e.recent.unwrap().top_newest, as_of), "its top is stale");
        assert_eq!(e.verdict, change(colmar), "3042");
    }

    /// Issue 552 (issue 524 rule v12), unit 3's pins with the REAL ingest functions, on plan 2543's own
    /// heads and listed spellings (`.scratch/tender-db/552-control-whitespace/cw_rows.json`; dates
    /// synthetic, in the `head_current` shape plan 2543 released them from: every non-elected spelling
    /// printed 2025-03-01, within 3 years of plan 2543's `as_of`, and the elected cluster 2026-09-01, a
    /// fresh top). R0w: 22289866, 22661109, 22981989 and 23474998 change to the head collapsed.
    /// Withheld `lines`, no R0w: 22737299 (`GmbH` ends line 2), 22862316 (`GmbH` ends line 1), 22299001
    /// (a person's line), 22545991 and 22718921. The guard passes: 14770, 22216826, 22925490, 4040,
    /// 22393047 and 22648679, released `unfit` as before. `long`, not asked: 22354266 and 22650988,
    /// released `unfit` as before. Then the synthetic legal-form pin and the durability test: each
    /// R0w-written head re-elected on the same votes with the fresh elected date HOLDS — and a wrapped
    /// head whose collapse the junk exemption would release (`digits`) is no R0w at all.
